def create_app() -> Flask:
    validate_runtime_secrets()
    flask_app = Flask(__name__)
    CORS(flask_app, supports_credentials=True)
    register_routes(flask_app)
    return flask_app

def database_url() -> str:
    value = os.environ.get("DATABASE_URL", "").strip()
    if not value:
        raise NextApiError("DATABASE_URL is not configured", 503)
    return value


def _connect_timeout_ms(env_name: str, default_ms: int) -> int:
    value = os.environ.get(env_name, "").strip()
    if not value:
        return default_ms
    try:
        parsed = int(value)
    except ValueError:
        return default_ms
    return parsed if parsed > 0 else default_ms


def connect():
    import psycopg

    # Bounds how long a single SQL statement (statement_timeout) or a wait for a
    # lock (lock_timeout) may run before Postgres cancels it, so a stuck/slow
    # database fails fast with a normal, catchable psycopg.OperationalError
    # subclass (QueryCanceled/LockNotAvailable) -- handled by
    # handle_database_offline_error() -- instead of hanging for gunicorn's full
    # --timeout (deliberately generous, to tolerate slow imports/exports) before
    # the worker is killed. Only applied to this API-side connect(); the
    # background worker (next_worker.py) and migrations (next_database.py) have
    # their own separate connect() and are intentionally left unbounded, since
    # their jobs (imports, MovieVault sync, migrations) can legitimately run long.
    statement_timeout_ms = _connect_timeout_ms("DISCVAULT_NEXT_API_STATEMENT_TIMEOUT_MS", 10_000)
    lock_timeout_ms = _connect_timeout_ms("DISCVAULT_NEXT_API_LOCK_TIMEOUT_MS", 5_000)
    return psycopg.connect(
        database_url(),
        row_factory=dict_row,
        autocommit=False,
        options=f"-c statement_timeout={statement_timeout_ms} -c lock_timeout={lock_timeout_ms}",
    )


def build_version() -> str:
    return backend_version()


def build_sha() -> str:
    return version_build_sha()


# --- App update check (About page) -----------------------------------------
#
# DiscVault ships as a Docker stack and cannot safely recreate its own
# container from inside the app, so this is a *check-only* feature: it compares
# the running version against the latest published version for the instance's
# release channel and surfaces the host command an operator runs to update.

UPDATE_GITHUB_REPO = "helmerzNL/DiscVault"
UPDATE_IMAGE_NAME = "ghcr.io/helmerznl/discvault"
UPDATE_CHANNELS = ("auto", "beta", "stable")
UPDATE_CHANNEL_IMAGE_TAG = {"beta": "v26-beta", "stable": "stable"}
UPDATE_CHANNEL_BRANCH = {"beta": "release/v26-beta", "stable": "main"}
UPDATE_CHANNEL_SETTING_KEY = "update_channel"
UPDATE_HTTP_TIMEOUT = 8.0
UPDATE_USER_AGENT = "DiscVault-UpdateCheck"


def _update_version_tuple(value: Any) -> tuple[int, ...]:
    """Parse a semver-ish string into a comparable integer tuple.

    ``26.2.45`` -> ``(26, 2, 45)``; a trailing ``-beta`` and any non-numeric
    leading ``v`` are ignored. Blank/garbage input returns ``()`` which sorts
    below any real version.
    """

    text = str(value or "").strip().lstrip("vV")
    if not text:
        return ()
    parts: list[int] = []
    for chunk in re.split(r"[._-]+", text):
        match = re.match(r"\d+", chunk)
        if not match:
            break
        parts.append(int(match.group(0)))
    return tuple(parts)


def normalize_update_channel(value: Any) -> str:
    text = str(value or "").strip().lower()
    if text == "v26":
        # Legacy channel retired in the 2-image model; treat any persisted
        # "v26" preference as its successor "stable" (main == the old v26 line).
        return "stable"
    return text if text in UPDATE_CHANNELS else "auto"


def _update_request_headers(accept: str = "application/json") -> dict[str, str]:
    return {"User-Agent": UPDATE_USER_AGENT, "Accept": accept}


def github_latest_stable_release() -> dict[str, Any] | None:
    """Return the latest published stable GitHub Release, or ``None``."""

    url = f"https://api.github.com/repos/{UPDATE_GITHUB_REPO}/releases/latest"
    resp = http_requests.get(
        url,
        headers=_update_request_headers("application/vnd.github+json"),
        timeout=UPDATE_HTTP_TIMEOUT,
    )
    if resp.status_code != 200:
        return None
    data = resp.json() or {}
    tag = str(data.get("tag_name") or "").strip()
    version = tag.lstrip("vV")
    if not version:
        return None
    return {
        "version": version,
        "releaseUrl": data.get("html_url"),
        "publishedAt": data.get("published_at"),
        "source": url,
    }


def github_branch_version(branch: str) -> dict[str, Any] | None:
    """Read ``app/VERSION`` from a branch via raw.githubusercontent.com."""

    url = f"https://raw.githubusercontent.com/{UPDATE_GITHUB_REPO}/{branch}/app/VERSION"
    resp = http_requests.get(
        url,
        headers=_update_request_headers("text/plain"),
        timeout=UPDATE_HTTP_TIMEOUT,
    )
    if resp.status_code != 200:
        return None
    version = (resp.text or "").strip()
    if not version:
        return None
    return {
        "version": version,
        "releaseUrl": f"https://github.com/{UPDATE_GITHUB_REPO}/commits/{branch}/app/VERSION",
        "publishedAt": None,
        "source": url,
    }


def resolve_update_channel(conn, requested: Any = None) -> tuple[str, str]:
    """Resolve the effective channel and where the decision came from.

    Priority: explicit request -> stored admin override -> env var -> heuristic
    (running version newer than latest stable release implies a pre-release
    build, so check the beta branch).
    """

    requested_channel = normalize_update_channel(requested)
    if requested_channel != "auto":
        return requested_channel, "request"

    stored = normalize_update_channel(app_setting_value(conn, UPDATE_CHANNEL_SETTING_KEY, "auto"))
    if stored != "auto":
        return stored, "setting"

    env_channel = normalize_update_channel(os.environ.get("DISCVAULT_UPDATE_CHANNEL"))
    if env_channel != "auto":
        return env_channel, "env"

    current = _update_version_tuple(build_version())
    stable = github_latest_stable_release()
    if stable is None:
        return "stable", "auto-fallback"
    if current and current > _update_version_tuple(stable["version"]):
        return "beta", "auto"
    return "stable", "auto"


def _update_command_for_channel(channel: str) -> str:
    return "docker compose pull && docker compose up -d"


def perform_update_check(conn, requested_channel: Any = None) -> dict[str, Any]:
    current_version = build_version()
    checked_at = datetime.now(timezone.utc).isoformat()
    try:
        channel, channel_source = resolve_update_channel(conn, requested_channel)
        # Every channel resolves its "latest" from an app/VERSION on a branch:
        # stable -> main, beta -> release/v26-beta. This keeps the reported
        # version, the published image and the source branch in lockstep, with
        # no drift against independently-cut GitHub Releases (changelogs only).
        latest = github_branch_version(UPDATE_CHANNEL_BRANCH.get(channel, "main"))
        if not latest:
            return {
                "status": "error",
                "message": "Could not determine the latest published version.",
                "channel": channel,
                "channelSource": channel_source,
                "currentVersion": current_version,
                "currentSha": build_sha(),
                "checkedAt": checked_at,
            }
        latest_version = latest["version"]
        update_available = _update_version_tuple(latest_version) > _update_version_tuple(current_version)
        image_tag = UPDATE_CHANNEL_IMAGE_TAG.get(channel, "stable")
        return {
            "status": "ok",
            "channel": channel,
            "channelSource": channel_source,
            "currentVersion": current_version,
            "currentSha": build_sha(),
            "latestVersion": latest_version,
            "updateAvailable": update_available,
            "releaseUrl": latest.get("releaseUrl"),
            "publishedAt": latest.get("publishedAt"),
            "imageRef": f"{UPDATE_IMAGE_NAME}:{image_tag}",
            "updateCommand": _update_command_for_channel(channel),
            "source": latest.get("source"),
            "checkedAt": checked_at,
        }
    except Exception as exc:  # noqa: BLE001 - network/parse failures must not 500
        return {
            "status": "error",
            "message": f"Update check failed: {exc}",
            "currentVersion": current_version,
            "currentSha": build_sha(),
            "checkedAt": checked_at,
        }


def physical_media_format_key(value: Any) -> str:
    text = (clean_text(value) or "").casefold().replace("-", " ").replace("_", " ").replace("/", " ")
    text = " ".join(text.split())
    if not text:
        return ""
    if "ultra hd" in text or "uhd" in text or "4k" in text:
        return "ultra_hd_blu_ray"
    if "blu ray" in text or "bluray" in text or text == "bd":
        return "blu_ray"
    if text in {"dvd", "dvd video"}:
        return "dvd"
    if "hd dvd" in text or "hddvd" in text:
        return "hd_dvd"
    if "laserdisc" in text or "laser disc" in text:
        return "laserdisc"
    if "svcd" in text or "vcd" in text:
        return "vcd_svcd"
    return text


def physical_media_formats_compatible(candidate: Any, expected: Any) -> bool:
    candidate_key = physical_media_format_key(candidate)
    expected_key = physical_media_format_key(expected)
    return not candidate_key or not expected_key or candidate_key == expected_key


def should_reuse_box_set_container_for_import(
    candidate: dict[str, Any],
    *,
    incoming_barcode: Any = "",
    incoming_format: Any = "",
) -> bool:
    """Protect physical box-set releases from title-only cross-edition reuse."""
    incoming_barcode_text = (clean_text(incoming_barcode) or "").casefold()
    candidate_barcode_text = (clean_text(candidate.get("barcode")) or "").casefold()
    if incoming_barcode_text:
        return bool(candidate_barcode_text and candidate_barcode_text == incoming_barcode_text)
    if candidate_barcode_text:
        return False
    metadata = candidate.get("metadata") if isinstance(candidate.get("metadata"), dict) else {}
    candidate_format = clean_text(metadata.get("format") or metadata.get("media_format"))
    return physical_media_formats_compatible(candidate_format, incoming_format)


def import_container_preview_key(
    container_type: str,
    title: str,
    *,
    barcode: Any = "",
    media_format: Any = "",
) -> tuple[str, str, str]:
    type_key = clean_text(container_type)
    title_key = (clean_text(title) or "").casefold()
    if type_key == "box_set":
        barcode_key = (clean_text(barcode) or "").casefold()
        if barcode_key:
            return (type_key, "barcode", barcode_key)
        format_key = physical_media_format_key(media_format)
        if format_key:
            return (type_key, "title_format", f"{title_key}:{format_key}")
    return (type_key, "title", title_key)


def html_response(html: str):
    result = Response(html, mimetype="text/html")
    result.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    result.headers["Pragma"] = "no-cache"
    result.headers["Expires"] = "0"
    return result


def render_database_offline_page(locale: str, *, busy: bool = False) -> str:
    """A minimal, translated, dependency-free page for when Postgres is unreachable.

    Deliberately has no dependency on ``ui_preview_html``/``collection_dashboard_snapshot`` —
    both require a live database connection, which is exactly what's missing here.

    With ``busy=True`` the same page renders the "busy" headline instead: the
    database answered but cancelled the query (statement/lock timeout), so the
    situation resolves in seconds rather than requiring an operator.
    """
    if busy:
        headline = next_translate(locale, "errors.databaseBusy", "DiscVault is busy right now — please try again in a moment")
        refresh_seconds = 5
    else:
        headline = next_translate(locale, "errors.databaseOffline", "DiscVault is temporarily offline")
        refresh_seconds = 20
    retry_label = next_translate(locale, "errors.databaseOfflineRetry", "Try again")
    return f"""<!doctype html>
<html lang="{html_lib.escape(locale)}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="{refresh_seconds}">
<title>{html_lib.escape(headline)}</title>
<style>
  :root {{ color-scheme: light dark; }}
  body {{
    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif; text-align: center; padding: 24px;
    background: #f7f7f8; color: #1a1a1a;
  }}
  @media (prefers-color-scheme: dark) {{
    body {{ background: #14161a; color: #e8e8ea; }}
  }}
  h1 {{ font-size: 1.375rem; margin: 0 0 8px; }}
  button {{
    margin-top: 20px; padding: 10px 20px; border-radius: 8px; border: 1px solid #8886;
    background: transparent; color: inherit; font-size: 1rem; cursor: pointer;
  }}
</style>
</head>
<body>
  <div>
    <h1>{html_lib.escape(headline)}</h1>
    <button type="button" onclick="location.reload()">{html_lib.escape(retry_label)}</button>
  </div>
</body>
</html>"""


