def emit_watchlist_change(conn, user_id, movie_id, *, operation: str) -> int:
    """Append a watchlist upsert/delete to the caller's private sync stream."""
    entity_id = str(movie_id)
    if operation == "delete":
        payload: dict[str, Any] = {"id": entity_id, "movieId": entity_id}
    else:
        entity = watchlist_sync_entity(conn, user_id, movie_id)
        payload = {"id": entity_id, "movieId": entity_id}
        if entity is not None:
            payload["entity"] = entity
    return user_sync_change(
        conn,
        user_id,
        entity_type="watchlist",
        entity_id=entity_id,
        operation=operation,
        payload=payload,
    )


def emit_watch_history_change(conn, user_id, entry_id, *, operation: str, movie_id=None) -> int:
    """Append a watch_history upsert/delete to the caller's private sync stream."""
    entity_id = str(entry_id)
    payload: dict[str, Any] = {"id": entity_id}
    if operation == "delete":
        if movie_id is not None:
            payload["movieId"] = str(movie_id)
    else:
        entity = watch_history_sync_entity(conn, user_id, entry_id)
        if entity is not None:
            payload["entity"] = entity
            payload["movieId"] = entity.get("movieId")
        elif movie_id is not None:
            payload["movieId"] = str(movie_id)
    return user_sync_change(
        conn,
        user_id,
        entity_type="watch_history",
        entity_id=entity_id,
        operation=operation,
        payload=payload,
    )


# ---------------------------------------------------------------------------
# Lists expansion (wishlist / tags / loans): per-user sync entity builders and
# emit helpers. Each mirrors the watchlist trio above and rides the generic
# per-user sync stream (user_sync_change). All are table_exists-guarded so they
# no-op on pre-026 schemas.
# ---------------------------------------------------------------------------


def wishlist_snapshot_with_local_poster_asset(
    snapshot: dict[str, Any],
    media_id: UUID | str,
) -> dict[str, Any]:
    trusted_snapshot = dict(snapshot)
    trusted_snapshot[WISHLIST_POSTER_ASSET_SNAPSHOT_KEY] = str(media_id)
    return trusted_snapshot


def wishlist_snapshot_preserving_local_poster_asset(
    snapshot: dict[str, Any],
    current_snapshot: dict[str, Any],
    *,
    poster_url_supplied: bool,
) -> dict[str, Any]:
    trusted_snapshot = dict(snapshot)
    if poster_url_supplied:
        return trusted_snapshot
    trusted_poster_asset_id = clean_text(current_snapshot.get(WISHLIST_POSTER_ASSET_SNAPSHOT_KEY))
    if trusted_poster_asset_id:
        trusted_snapshot[WISHLIST_POSTER_ASSET_SNAPSHOT_KEY] = trusted_poster_asset_id
    return trusted_snapshot


def _wishlist_row_entity(row: dict[str, Any]) -> dict[str, Any]:
    acquired_movie = row.get("acquired_movie_id")
    created_by = row.get("created_by_user_id")
    snapshot = row.get("snapshot")
    public_snapshot = dict(snapshot) if isinstance(snapshot, dict) else {}
    public_snapshot.pop(WISHLIST_POSTER_ASSET_SNAPSHOT_KEY, None)
    return {
        "id": str(row.get("id")),
        "title": row.get("title"),
        "year": row.get("year"),
        "barcode": row.get("barcode"),
        "format": row.get("format"),
        "movievaultId": row.get("movievault_id"),
        "posterUrl": row.get("poster_url"),
        "note": row.get("note"),
        "snapshot": public_snapshot,
        "addedAt": row.get("added_at"),
        "acquiredAt": row.get("acquired_at"),
        "acquiredMovieId": str(acquired_movie) if acquired_movie else None,
        "createdByUserId": str(created_by) if created_by else None,
        # Price alert fields
        "alertEnabled": bool(row.get("alert_enabled")),
        "targetPrice": float(row["target_price"]) if row.get("target_price") is not None else None,
        "priceUrl": row.get("price_url"),
        "lastSeenPrice": float(row["last_seen_price"]) if row.get("last_seen_price") is not None else None,
        "priceCurrency": row.get("price_currency") or "EUR",
        "lastPriceCheckedAt": row.get("last_price_checked_at"),
        "lastAlertedAt": row.get("last_alerted_at"),
    }


def _wishlist_shop_row_entity(row: dict[str, Any]) -> dict[str, Any]:
    selector_options = row.get("selector_options")
    if not isinstance(selector_options, dict):
        selector_options = {}
    return {
        "id": str(row.get("id")),
        "wishlistItemId": str(row.get("wishlist_item_id")),
        "shopName": row.get("shop_name"),
        "priceUrl": row.get("price_url"),
        "priceCurrency": row.get("price_currency") or "EUR",
        "priceSelector": {
            "type": row.get("selector_type"),
            "value": row.get("selector_value"),
            "options": selector_options,
        },
        "providerId": row.get("provider_plugin_id"),
        "providerProductRef": row.get("provider_product_ref"),
        "providerLastStatus": row.get("provider_last_status"),
        "providerLastError": row.get("provider_last_error"),
        "lastSeenPrice": float(row["last_seen_price"]) if row.get("last_seen_price") is not None else None,
        "lastPriceCheckedAt": row.get("last_price_checked_at"),
        "createdAt": row.get("created_at"),
        "updatedAt": row.get("updated_at"),
    }


def _wishlist_shops_by_item(conn, user_id, item_ids: list[Any]) -> dict[str, list[dict[str, Any]]]:
    if not user_id or not item_ids or not table_exists(conn, "wishlist_item_shops"):
        return {}
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, wishlist_item_id, shop_name, price_url, price_currency,
                   selector_type, selector_value, selector_options,
                   provider_plugin_id, provider_product_ref, provider_last_status, provider_last_error,
                   last_seen_price, last_price_checked_at, created_at, updated_at
            FROM wishlist_item_shops
            WHERE user_id=%s
              AND wishlist_item_id = ANY(%s)
            ORDER BY created_at ASC
            """,
            (user_id, item_ids),
        )
        rows = cur.fetchall()
    out: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        key = str(row.get("wishlist_item_id"))
        out.setdefault(key, []).append(_wishlist_shop_row_entity(row))
    return out


def _attach_wishlist_shops(conn, user_id, entities: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not entities:
        return entities
    item_ids = [entity.get("id") for entity in entities if entity.get("id")]
    shops_map = _wishlist_shops_by_item(conn, user_id, item_ids)
    for entity in entities:
        entity["shops"] = shops_map.get(str(entity.get("id")), [])
    return entities


def wishlist_sync_entity(conn, user_id, item_id) -> dict[str, Any] | None:
    if not table_exists(conn, "wishlist_items"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, title, year, barcode, format, movievault_id, poster_url,
                   note, snapshot, added_at, acquired_at, acquired_movie_id,
                   created_by_user_id,
                   alert_enabled, target_price, price_url, last_seen_price,
                   price_currency, last_price_checked_at, last_alerted_at
            FROM wishlist_items
            WHERE user_id=%s AND id=%s
            """,
            (user_id, item_id),
        )
        row = cur.fetchone()
    if not row:
        return None
    entity = _wishlist_row_entity(row)
    entity["shops"] = _wishlist_shops_by_item(conn, user_id, [item_id]).get(str(item_id), [])
    return entity


def all_wishlist_sync_entities(conn, user_id) -> list[dict[str, Any]]:
    if not user_id or not table_exists(conn, "wishlist_items"):
        return []
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, title, year, barcode, format, movievault_id, poster_url,
                   note, snapshot, added_at, acquired_at, acquired_movie_id,
                   created_by_user_id,
                   alert_enabled, target_price, price_url, last_seen_price,
                   price_currency, last_price_checked_at, last_alerted_at
            FROM wishlist_items
            WHERE user_id=%s
            ORDER BY added_at
            """,
            (user_id,),
        )
        rows = cur.fetchall()
    entities = [_wishlist_row_entity(row) for row in rows]
    return _attach_wishlist_shops(conn, user_id, entities)


def _wishlist_existing_identity_id(conn, user_id, fields: dict[str, Any]):
    movievault_id = fields.get("movievault_id")
    tmdb_id = fields.get("tmdb_id")
    if movievault_id:
        query = """
            SELECT id
            FROM wishlist_items
            WHERE user_id=%s AND movievault_id=%s
            ORDER BY added_at, id
            LIMIT 1
        """
        params = (user_id, movievault_id)
    elif tmdb_id:
        query = """
            SELECT id
            FROM wishlist_items
            WHERE user_id=%s
              AND snapshot->>'tmdb_id' = %s
              AND COALESCE(NULLIF(snapshot->>'tmdb_media_type', ''), 'movie') = %s
            ORDER BY added_at, id
            LIMIT 1
        """
        params = (user_id, tmdb_id, fields.get("tmdb_media_type") or "movie")
    else:
        return None

    with conn.cursor() as cur:
        cur.execute(query, params)
        row = cur.fetchone()
    return (row or {}).get("id")


def _insert_wishlist_item_once(
    conn,
    *,
    user_id,
    created_by_user_id,
    fields: dict[str, Any],
    snapshot: dict[str, Any],
):
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO wishlist_items
                (user_id, title, year, barcode, format, movievault_id, poster_url, note, snapshot, created_by_user_id)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            ON CONFLICT DO NOTHING
            RETURNING id
            """,
            (
                user_id,
                fields["title"],
                fields["year"],
                fields["barcode"],
                fields["format"],
                fields["movievault_id"],
                fields["poster_url"],
                fields["note"],
                Jsonb(snapshot),
                created_by_user_id,
            ),
        )
        inserted = cur.fetchone()
    item_id = (inserted or {}).get("id")
    if item_id is not None:
        return item_id, True

    item_id = _wishlist_existing_identity_id(conn, user_id, fields)
    if item_id is None:
        raise NextApiError("Wishlist item could not be created", 409)
    return item_id, False


def _create_wishlist_item_record(
    conn,
    *,
    actor: dict[str, Any],
    fields: dict[str, Any],
    snapshot: dict[str, Any],
):
    user_id = actor.get("id")
    with conn.transaction():
        item_id, created = _insert_wishlist_item_once(
            conn,
            user_id=user_id,
            created_by_user_id=actor.get("id"),
            fields=fields,
            snapshot=snapshot,
        )
        if created:
            emit_wishlist_change(conn, user_id, item_id, operation="upsert")
            audit_event(
                conn,
                event_type="wishlist.added",
                category="personal",
                actor=actor,
                target_type="wishlist_item",
                target_id=item_id,
                summary="Added wishlist entry",
                metadata={"title": fields["title"]},
            )
    return item_id, created


def emit_wishlist_change(conn, user_id, item_id, *, operation: str) -> int:
    entity_id = str(item_id)
    payload: dict[str, Any] = {"id": entity_id}
    if operation != "delete":
        entity = wishlist_sync_entity(conn, user_id, item_id)
        if entity is not None:
            payload["entity"] = entity
    return user_sync_change(
        conn,
        user_id,
        entity_type="wishlist",
        entity_id=entity_id,
        operation=operation,
        payload=payload,
    )


