def movie_metadata_missing_contribution_report(
    *,
    movie_id: UUID | str,
    title: Any,
    fetched: list[dict[str, Any]],
    contributed: list[dict[str, Any]],
    generated_at: Any,
    entity_kind: str = "movie",
) -> dict[str, Any] | None:
    """Build a self-describing report of fields fetched by DiscVault but not
    accepted by a receiver's contribution template (e.g. MovieVault).

    The list is derived from the real contribution filtering: each receiver's
    ``excludedFields`` (incoming payload keys dropped by the template allow-list)
    cross-referenced against the fetched field decisions for source + sample value.
    """

    def _norm(key: Any) -> str:
        return "".join(ch for ch in str(key or "").lower() if ch.isalnum())

    lookup: dict[str, dict[str, Any]] = {}
    for plugin in fetched or []:
        if not isinstance(plugin, dict):
            continue
        for field in plugin.get("fields") or []:
            if not isinstance(field, dict):
                continue
            norm_key = _norm(field.get("field"))
            if not norm_key or norm_key in lookup:
                continue
            lookup[norm_key] = {
                "sourcePluginId": plugin.get("pluginId"),
                "sourceLabel": plugin.get("sourceLabel"),
                "sampleValue": field.get("value"),
                "target": field.get("target"),
            }

    receivers_out: list[dict[str, Any]] = []
    for receiver in contributed or []:
        if not isinstance(receiver, dict):
            continue
        excluded = receiver.get("excludedFields") or []
        missing: list[dict[str, Any]] = []
        for item in excluded:
            if not isinstance(item, dict) or not item.get("field"):
                continue
            info = lookup.get(_norm(item.get("field")), {})
            missing.append(
                {
                    "field": item.get("field"),
                    "target": info.get("target"),
                    "sourcePluginId": info.get("sourcePluginId"),
                    "sourceLabel": info.get("sourceLabel"),
                    "sampleValue": info.get("sampleValue"),
                    "reason": item.get("reason"),
                }
            )
        if not missing:
            continue
        receivers_out.append(
            {
                "pluginId": receiver.get("pluginId"),
                "name": receiver.get("name") or receiver.get("pluginId"),
                "templateVersion": receiver.get("templateVersion"),
                "missingFields": missing,
            }
        )

    if not receivers_out:
        return None

    return {
        "report": "discvault.metadata.missing_in_receiver",
        "version": 1,
        "note": "Fields fetched by DiscVault but not accepted by the receiver's contribution template.",
        "generatedAt": generated_at,
        f"{entity_kind}Id": str(movie_id),
        "title": title,
        "receivers": receivers_out,
    }


def metadata_debug_fetched_sources(fetched_meta: dict[str, Any] | None) -> list[dict[str, Any]]:
    """Build the per-source "loaded metadata" cards from a refresh_fetched event's metadata."""
    fetched_meta = fetched_meta if isinstance(fetched_meta, dict) else {}

    source_states: dict[str, dict[str, Any]] = {}
    for entry in fetched_meta.get("sourceSummary") or []:
        if isinstance(entry, dict) and entry.get("pluginId"):
            source_states[str(entry["pluginId"])] = entry

    grouped: dict[str, dict[str, Any]] = {}
    order: list[str] = []

    def ensure_plugin(plugin_id: str, *, source_label: Any, source_ref: Any) -> dict[str, Any]:
        if plugin_id not in grouped:
            summary_entry = source_states.get(plugin_id) or {}
            grouped[plugin_id] = {
                "pluginId": plugin_id,
                "sourceLabel": source_label or summary_entry.get("name") or plugin_id,
                "state": summary_entry.get("state"),
                "reason": summary_entry.get("reason"),
                "sourceRef": source_ref or "",
                "fields": [],
            }
            order.append(plugin_id)
        return grouped[plugin_id]

    for decision in fetched_meta.get("fieldDecisions") or []:
        if not isinstance(decision, dict):
            continue
        target = decision.get("target")
        field = decision.get("field")
        for candidate in decision.get("candidates") or []:
            if not isinstance(candidate, dict):
                continue
            plugin_id = str(candidate.get("pluginId") or "")
            if not plugin_id:
                continue
            entry = ensure_plugin(
                plugin_id,
                source_label=candidate.get("sourceLabel"),
                source_ref=candidate.get("sourceRef"),
            )
            if not entry.get("sourceRef") and candidate.get("sourceRef"):
                entry["sourceRef"] = candidate.get("sourceRef")
            # `accepted` only means the merge *selected* this candidate — that
            # `should_apply_field` said yes. Whether it survived to the movies
            # row is a separate fact, recorded on the decision by
            # `metadata_field_decisions_with_write_state`. Reporting acceptance
            # alone made a field that was chosen and then never written look
            # identical to one that landed, which is exactly how an int-into-a-
            # text-column failure could sit in plain sight reading "used".
            accepted = bool(candidate.get("accepted") or candidate.get("winner"))
            written = decision.get("written")
            entry["fields"].append(
                {
                    "target": target,
                    "field": field,
                    "value": candidate.get("value"),
                    "accepted": accepted,
                    # None when the event predates write tracking — the UI keeps
                    # showing "used" there rather than claiming a failure it
                    # cannot actually see.
                    "written": None if written is None else (accepted and bool(written)),
                    "writeState": decision.get("writeState"),
                    "appliedValue": decision.get("appliedValue"),
                }
            )

    for result in fetched_meta.get("providerResults") or []:
        if not isinstance(result, dict):
            continue
        plugin_id = str(result.get("pluginId") or "")
        if not plugin_id or plugin_id in grouped:
            continue
        ensure_plugin(
            plugin_id,
            source_label=result.get("sourceLabel"),
            source_ref=result.get("sourceRef"),
        )

    return [grouped[plugin_id] for plugin_id in order]


def movie_metadata_debug_entity(conn, movie_id: UUID | str) -> dict[str, Any] | None:
    if not table_exists(conn, "audit_events"):
        return None
    fetched_event = movie_metadata_debug_latest_audit_event(conn, movie_id, "metadata.refresh_fetched")
    pushed_event = movie_metadata_debug_latest_audit_event(conn, movie_id, "metadata.receiver_pushed")
    if not fetched_event and not pushed_event:
        return None

    fetched_meta = (fetched_event or {}).get("metadata") or {}
    pushed_meta = (pushed_event or {}).get("metadata") or {}

    fetched = metadata_debug_fetched_sources(fetched_meta)

    payload_summary = pushed_meta.get("payloadSummary") or {}
    payload_fields = payload_summary.get("fields") or []
    payload_sources = payload_summary.get("sourceProviders") or []
    contributed: list[dict[str, Any]] = []
    for receiver in pushed_meta.get("receivers") or []:
        if not isinstance(receiver, dict):
            continue
        contributed.append(
            {
                "pluginId": receiver.get("pluginId"),
                "name": receiver.get("name") or receiver.get("pluginId"),
                "status": receiver.get("status"),
                "state": receiver.get("state"),
                "resultStatus": receiver.get("resultStatus"),
                "reason": receiver.get("reason"),
                "provider": receiver.get("provider"),
                "error": receiver.get("error"),
                "templateVersion": receiver.get("templateVersion"),
                "fields": payload_fields,
                "acceptedFields": receiver.get("acceptedFields") if isinstance(receiver.get("acceptedFields"), list) else [],
                "excludedFields": [
                    {"field": item.get("field"), "reason": item.get("reason")}
                    for item in (receiver.get("droppedFields") or [])
                    if isinstance(item, dict) and item.get("field")
                ],
                "sourceProviders": payload_sources,
            }
        )

    if not fetched and not contributed:
        return None

    fetched_at = (fetched_event or {}).get("createdAt")
    if hasattr(fetched_at, "isoformat"):
        fetched_at = fetched_at.isoformat()

    movie_title = pushed_meta.get("title") or fetched_meta.get("title")
    missing_report = movie_metadata_missing_contribution_report(
        movie_id=movie_id,
        title=movie_title,
        fetched=fetched,
        contributed=contributed,
        generated_at=fetched_at,
    )

    return {
        "fetchedAt": fetched_at,
        "fetched": fetched,
        "contributed": contributed,
        "missingContributionReport": missing_report,
    }


def movie_client_id_mappings(conn, movie_id: UUID) -> list[dict[str, Any]]:
    """Every device/record token pair the sync API has bound to this movie.

    ``client_id_mappings.client_id`` stores the composite ``"<device client
    id>:<record token>"`` written by :func:`store_client_entity_mapping`; it is
    split back apart here so the two halves stay recognisable as the two
    different things the sync contract calls ``client_id`` (§1). These are the
    ids an iOS or Android client shows on its own Identity (Debug) panel, and
    the only way to line a phone's record up with the server row from this side.
    """
    if not table_exists(conn, "client_id_mappings"):
        return []
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT client_id, created_at
            FROM client_id_mappings
            WHERE entity_id=%s AND entity_type='movie'
            ORDER BY created_at
            """,
            (movie_id,),
        )
        rows = cur.fetchall()
    mappings: list[dict[str, Any]] = []
    for row in rows:
        composite = str(row.get("client_id") or "")
        device, _, record_token = composite.partition(":")
        mappings.append(
            {
                "deviceClientId": device or None,
                "recordToken": record_token or None,
                "createdAt": row.get("created_at"),
            }
        )
    return mappings


def movie_identity_debug_entity(conn, movie_id: UUID, movie: dict[str, Any]) -> dict[str, Any]:
    """Identity fields plus a real ladder scan for one movie record.

    The server/PWA counterpart to the iOS ``Identity (Debug)`` card
    (DiscVaultApp ``Sources/Diagnostics/DebugIdentityPanel.swift``), and it
    keeps that panel's first rule: never re-normalize. Every normalized value
    and every verdict below comes out of the same ``normalize_*`` /
    ``find_movie_by_*`` functions the sync merge path calls, so the panel can
    never display something subtly different from what actually matched.

    A tier that resolves back to this same movie is the healthy case and is
    reported as a self-match. A tier that resolves to a *different* live movie
    is the finding worth chasing: two rows the ladder cannot tell apart.
    """
    barcode = movie.get("barcode")
    title = movie.get("title")
    fmt = movie.get("format")
    edition = movie.get("edition")
    year = movie.get("year")

    tmdb_id = None
    imdb_id = None
    for row in movie_identifier_entities(conn, movie_id):
        provider = str(row.get("provider_id") or "").lower()
        identifier = str(row.get("identifier") or "").strip()
        if not identifier:
            continue
        if provider == "tmdb" and tmdb_id is None:
            tmdb_id = identifier
        elif provider == "imdb" and imdb_id is None:
            imdb_id = identifier

    container_ids: list[str] = []
    if table_exists(conn, "container_movies"):
        with conn.cursor() as cur:
            cur.execute(
                "SELECT container_id::text AS container_id FROM container_movies WHERE movie_id=%s ORDER BY container_id",
                (movie_id,),
            )
            container_ids = [str(row["container_id"]) for row in cur.fetchall()]

    def _resolved(tier: str, resolved_id: UUID | None, *, key: str | None) -> dict[str, Any]:
        entry: dict[str, Any] = {
            "tier": tier,
            "key": key,
            "matchedMovieId": str(resolved_id) if resolved_id else None,
            "isSelf": bool(resolved_id) and str(resolved_id) == str(movie_id),
            "matchedTitle": None,
        }
        if resolved_id and not entry["isSelf"]:
            with conn.cursor() as cur:
                cur.execute("SELECT title FROM movies WHERE id=%s", (resolved_id,))
                row = cur.fetchone()
            entry["matchedTitle"] = (row or {}).get("title")
        return entry

    normalized_barcode = normalize_barcode(barcode)
    normalized_title = normalize_title(title)

    ladder: list[dict[str, Any]] = []
    # Each call is wrapped: a diagnostic panel must never be the reason a movie
    # page fails to load, and these run four extra queries against live tables.
    try:
        ladder.append(
            _resolved(
                "client_id",
                find_movie_by_client_id(conn, movie.get("client_id")),
                key=movie.get("client_id"),
            )
        )
        ladder.append(
            _resolved(
                "barcode",
                find_movie_by_barcode_match(
                    conn, barcode, incoming_media_type=movie.get("media_type")
                ),
                key=normalized_barcode,
            )
        )
        ladder.append(
            _resolved(
                "tmdb_format_edition",
                find_movie_by_tmdb_edition(
                    conn,
                    tmdb_id=tmdb_id,
                    fmt=fmt,
                    edition=edition,
                    incoming_title=title,
                    incoming_year=year,
                    incoming_barcode=barcode,
                    incoming_media_type=movie.get("media_type"),
                ),
                key=f"{tmdb_id or '-'} / {physical_media_format_key(fmt) or '-'} / {edition or '-'}",
            )
        )
        ladder.append(
            _resolved(
                "title_year",
                find_movie_by_title_year(
                    conn,
                    title=title,
                    year=year,
                    fmt=fmt,
                    incoming_barcode=barcode,
                    incoming_edition=edition,
                    incoming_container_ids=container_ids,
                    incoming_media_type=movie.get("media_type"),
                ),
                key=f"{normalized_title or '-'} / {year or '-'}",
            )
        )
    except Exception:  # pragma: no cover - a scan failure must not hide the fields
        pass

    return {
        "normalizedBarcode": normalized_barcode,
        "normalizedTitle": normalized_title,
        "formatKey": physical_media_format_key(fmt),
        "tmdbId": tmdb_id,
        "imdbId": imdb_id,
        "containerIds": container_ids,
        "clientMappings": movie_client_id_mappings(conn, movie_id),
        "ladder": ladder,
    }


def movie_detail_entity(conn, movie_id: UUID) -> dict[str, Any] | None:
    movie = movie_entity(conn, movie_id)
    if not movie:
        return None
    attach_location_summaries(conn, [movie])
    metadata_debug = None
    try:
        metadata_debug = movie_metadata_debug_entity(conn, movie_id)
    except Exception:  # pragma: no cover - debug info must never break detail load
        metadata_debug = None
    identity_debug = None
    try:
        identity_debug = movie_identity_debug_entity(conn, movie_id, movie)
    except Exception:  # pragma: no cover - debug info must never break detail load
        identity_debug = None
    # The box set a member film's value belongs to. Present means the price
    # field is read-only: the set carries the money for everything inside it.
    value_lock = None
    try:
        value_lock = movie_value_lock(conn, movie_id)
    except Exception:  # pragma: no cover - never break detail load over a hint
        value_lock = None
    return {
        "movie": movie,
        "estimatedValueLocked": bool(value_lock),
        "estimatedValueLockedBy": value_lock,
        "identityDebug": identity_debug,
        "identifiers": movie_identifier_entities(conn, movie_id),
        "localizations": movie_localization_entities(conn, movie_id),
        "technicalSpecs": movie_technical_spec_entity(conn, movie_id),
        "credits": movie_credit_entities(conn, movie_id),
        "containers": movie_container_entities(conn, movie_id),
        # None means "not linked"; a linked disc with an empty seasons list means
        # the complete series or unspecified. The UI has to tell those apart.
        "series": movie_series_payload(conn, movie_id),
        # The physical discs inside this release, seasons and episodes resolved.
        # An empty list means nobody has broken the release down yet, which is
        # not the same as a single-disc release -- `technicalSpecs` above keeps
        # answering for both.
        "discs": movie_disc_entities(conn, movie_id),
        "mediaGroups": movie_media_group_entities(conn, movie_id),
        "mediaAssets": entity_media_asset_entities(
            conn, "movie", movie_id, include_hidden=True
        ),
        "digitalItems": movie_digital_item_entities(conn, movie_id),
        "metadataDebug": metadata_debug,
    }



def person_metadata_source_plugins(conn, *, include_disabled: bool = False) -> list[dict[str, Any]]:
    """Return TMDb when it is installed and exposes person details."""
    if not table_exists(conn, "plugins"):
        return []
    sync_metadata_plugin_registry(conn)
    registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
    plugins: list[dict[str, Any]] = []
    for plugin in registry.get("plugins") or []:
        if str(plugin.get("id") or "").strip().lower() != "tmdb":
            continue
        if not plugin.get("installed"):
            continue
        if not include_disabled and not plugin.get("enabled"):
            continue
        if "metadata_source" not in plugin_categories(plugin):
            continue
        if "person_details" not in plugin_runtime_entrypoints(plugin):
            continue
        plugins.append(plugin)
    return plugins


def person_filmography_source_plugins(conn, *, include_disabled: bool = False) -> list[dict[str, Any]]:
    """Return TMDb when it is installed and exposes person filmography."""
    if not table_exists(conn, "plugins"):
        return []
    sync_metadata_plugin_registry(conn)
    registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
    plugins: list[dict[str, Any]] = []
    for plugin in registry.get("plugins") or []:
        if str(plugin.get("id") or "").strip().lower() != "tmdb":
            continue
        if not plugin.get("installed"):
            continue
        if not include_disabled and not plugin.get("enabled"):
            continue
        if "metadata_source" not in plugin_categories(plugin):
            continue
        if "person_filmography" not in plugin_runtime_entrypoints(plugin):
            continue
        plugins.append(plugin)
    return plugins


def person_metadata_plugin(conn) -> dict[str, Any] | None:
    candidates = person_metadata_source_plugins(conn, include_disabled=True)
    return candidates[0] if candidates else None


def person_filmography_plugin(conn) -> dict[str, Any] | None:
    candidates = person_filmography_source_plugins(conn, include_disabled=True)
    return candidates[0] if candidates else None



def _refresh_one_movie_person_credit(
    credit: dict[str, Any],
    *,
    dry_run: bool,
    actor: dict[str, Any] | None,
    force: bool,
) -> dict[str, Any]:
    person_id = str(credit.get("person_id") or credit.get("personId") or "").strip()
    entry = {
        "personId": person_id,
        "name": credit.get("name"),
        "creditType": credit.get("credit_type") or credit.get("creditType"),
        "job": credit.get("job"),
        "character": credit.get("character"),
    }
    try:
        with connect() as person_conn:
            with person_conn.transaction():
                result = refresh_person_metadata(person_conn, UUID(person_id), dry_run=dry_run, actor=actor, force=force)
        cached = (result.get("execution") or {}).get("state") == "cached"
        entry["status"] = "cached" if cached else ("previewed" if dry_run else "refreshed")
        entry["plugin"] = (result.get("plugin") or {}).get("id")
        execution = result.get("execution") or {}
        if execution:
            entry["elapsedMs"] = execution.get("elapsedMs")
    except NextApiError as exc:
        entry["status"] = "skipped" if exc.status_code in {404, 409, 503} else "error"
        entry["reason"] = str(exc)
        if exc.status_code not in {404, 409, 503}:
            entry["errorMessage"] = str(exc)
            entry["errorStatusCode"] = exc.status_code
    except Exception as exc:
        entry["status"] = "error"
        entry["reason"] = str(exc)
        entry["errorMessage"] = str(exc)
    return entry


def refresh_movie_person_metadata_cascade(
    conn,
    movie_id: UUID | str,
    *,
    dry_run: bool = False,
    actor: dict[str, Any] | None = None,
    limit: int = MOVIE_METADATA_PERSON_REFRESH_LIMIT,
    scope: str = "all",
    force: bool = True,
) -> dict[str, Any]:
    normalized_scope = normalize_movie_metadata_person_refresh_scope(scope)
    summary = movie_metadata_person_refresh_empty(requested=True, dry_run=dry_run, limit=limit, scope=normalized_scope)
    movie_uuid = UUID(str(movie_id))
    credits = movie_credit_entities(conn, movie_uuid, limit=100)
    selected = select_movie_metadata_person_refresh_credits(credits, limit=limit, scope=normalized_scope)
    summary["considered"] = len(credits)
    summary["selected"] = len(selected)
    if not selected:
        return summary

    plugin = person_metadata_plugin(conn)
    skip_reason = ""
    if not plugin:
        skip_reason = "person_metadata_plugin_unavailable"
    elif not plugin.get("enabled"):
        skip_reason = "person_metadata_plugin_disabled"
    else:
        config = plugin_config_from_db(conn, str(plugin["id"]))
        if plugin_requires_config_for_entrypoint(plugin, config, "person_details"):
            skip_reason = "person_metadata_plugin_configuration_incomplete"
    if skip_reason:
        summary["skipped"] = len(selected)
        summary["people"] = movie_metadata_person_refresh_skipped_people(selected, skip_reason)
        return summary

    needs_fetch, already_cached = select_movie_metadata_person_refresh_credits_needing_fetch(selected, force=force)
    if already_cached:
        summary["cached"] += len(already_cached)
        summary["people"].extend(
            movie_metadata_person_refresh_cached_people(already_cached, "person_metadata_cache_fresh")
        )
    if not needs_fetch:
        return summary

    # Each task opens its own DB connection: psycopg connections are not
    # thread-safe, so concurrent TMDB fetches can't share the caller's `conn`.
    max_workers = min(4, len(needs_fetch))
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as pool:
        futures = [
            pool.submit(_refresh_one_movie_person_credit, credit, dry_run=dry_run, actor=actor, force=force)
            for credit in needs_fetch
        ]
        for future in concurrent.futures.as_completed(futures):
            entry = future.result()
            status = entry.get("status")
            if status == "cached":
                summary["cached"] += 1
            elif status == "previewed":
                summary["previewed"] += 1
            elif status == "refreshed":
                summary["refreshed"] += 1
            elif status == "skipped":
                summary["skipped"] += 1
            else:
                summary["errorCount"] += 1
                summary["errors"].append(
                    {
                        "personId": entry.get("personId"),
                        "message": entry.get("errorMessage") or entry.get("reason"),
                        "statusCode": entry.get("errorStatusCode"),
                    }
                )
            summary["people"].append(entry)
    return summary


def sanitize_profile_urls(values: Any, *, cap: int = 12) -> list[str]:
    """Return public https profile URLs: trimmed, deduped (order-preserving), capped.

    Only ``https://`` URLs are accepted (no http, local, relative or signed paths)
    so MovieVault/clients receive distributable public assets. The cap mirrors the
    TMDb plugin ``_profile_urls`` limit.
    """
    urls: list[str] = []
    for raw in values or []:
        value = clean_text(raw) or ""
        if not value.startswith("https://"):
            continue
        if value not in urls:
            urls.append(value)
        if len(urls) >= cap:
            break
    return urls


def sync_person_profile_media(
    conn,
    person_id: UUID,
    profile_urls: list[Any] | None,
    *,
    provider_id: str = "tmdb",
) -> dict[str, Any] | None:
    """Persist a person's profile image URLs as remote media assets.

    Each unique https URL is upserted into ``media_assets`` (kind ``profile``)
    and linked via ``entity_media`` (entity_type ``person``, role ``profile``).
    The first asset is marked primary and stored on ``people.profile_asset_id``
    unless the person already has a primary profile selected (which is left
    untouched so a manual selection is not overwritten).
    """
    if not table_exists(conn, "people") or not table_exists(conn, "media_assets") or not table_exists(conn, "entity_media"):
        return None
    urls = sanitize_profile_urls(profile_urls)
    if not urls:
        return None

    with conn.cursor() as cur:
        cur.execute("SELECT profile_asset_id FROM people WHERE id=%s", (person_id,))
        row = cur.fetchone()
        existing_primary = (row.get("profile_asset_id") if isinstance(row, dict) else (row[0] if row else None)) if row else None

    assign_primary = existing_primary is None
    primary_media_id = existing_primary
    linked: list[str] = []
    for index, url in enumerate(urls):
        media_id = ensure_remote_media_asset(conn, kind="profile", source_url=url, provider_id=provider_id)
        if not media_id:
            continue
        make_primary = assign_primary and primary_media_id is None
        if make_primary:
            primary_media_id = media_id
        with conn.cursor() as cur:
            if make_primary:
                cur.execute(
                    """
                    UPDATE entity_media em
                    SET is_primary=false,
                        sort_order=GREATEST(em.sort_order, 1)
                    FROM media_assets ma
                    WHERE ma.id = em.media_id
                      AND em.entity_type='person'
                      AND em.entity_id=%s
                      AND ma.kind='profile'
                      AND em.is_primary=true
                      AND em.media_id<>%s
                    """,
                    (person_id, media_id),
                )
            cur.execute(
                """
                INSERT INTO entity_media (
                    entity_type,
                    entity_id,
                    media_id,
                    role,
                    is_primary,
                    sort_order
                )
                VALUES ('person', %s, %s, 'profile', %s, %s)
                ON CONFLICT (entity_type, entity_id, media_id, role) DO UPDATE SET
                    is_primary=GREATEST(entity_media.is_primary::int, EXCLUDED.is_primary::int)::boolean,
                    sort_order=LEAST(entity_media.sort_order, EXCLUDED.sort_order),
                    deleted_at=NULL,
                    deleted_by=NULL,
                    purge_after=NULL,
                    restore_metadata='{}'::jsonb
                """,
                (person_id, media_id, make_primary, 0 if make_primary else index + 1),
            )
        linked.append(str(media_id))

    if assign_primary and primary_media_id is not None:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE people SET profile_asset_id=%s, updated_at=now() WHERE id=%s",
                (primary_media_id, person_id),
            )

    return {
        "primaryMediaId": str(primary_media_id) if primary_media_id else None,
        "linked": linked,
        "count": len(linked),
    }


def _cached_person_metadata_result(detail: dict[str, Any], *, dry_run: bool) -> dict[str, Any]:
    person = detail.get("person") if isinstance(detail.get("person"), dict) else {}
    metadata = person.get("metadata") if isinstance(person.get("metadata"), dict) else {}
    awards = metadata.get("awards") or []
    award_groups = metadata.get("awardGroups") or []
    return {
        "dryRun": dry_run,
        "plugin": {"id": metadata.get("person_metadata_source"), "name": metadata.get("person_metadata_source")},
        "sourceProviders": sorted({str(item) for item in (metadata.get("person_metadata_sources") or []) if item}),
        "execution": {"status": "skipped", "state": "cached", "elapsedMs": 0, "entrypoint": "person_details"},
        "awards": {
            "status": "skipped",
            "state": "cached",
            "applied": bool(awards),
            "count": len(awards),
            "groups": len(award_groups),
        },
        "result": {},
        "receivers": None,
        "detail": detail,
    }


def refresh_person_metadata(
    conn,
    person_id: UUID,
    *,
    dry_run: bool = False,
    actor: dict[str, Any] | None = None,
    force: bool = True,
) -> dict[str, Any]:
    detail = person_detail_entity(conn, person_id)
    if not detail:
        raise NextApiError("Person not found", 404)
    tmdb_id = detail.get("tmdbId") or ""
    if not tmdb_id:
        raise NextApiError("Person has no TMDb identifier", 409)

    if not force:
        person_metadata = (detail.get("person") or {}).get("metadata")
        fetched_at = person_metadata.get("person_metadata_fetched_at") if isinstance(person_metadata, dict) else None
        if fetched_at and person_metadata_is_fresh(fetched_at):
            return _cached_person_metadata_result(detail, dry_run=dry_run)

    candidates = [
        plugin
        for plugin in person_metadata_source_plugins(conn, include_disabled=True)
        if str(plugin.get("id") or "").strip().lower() == "tmdb"
    ]
    if not candidates:
        raise NextApiError("TMDb person metadata plugin is not available", 503)
    enabled_candidates = [plugin for plugin in candidates if plugin.get("enabled")]
    if not enabled_candidates:
        raise NextApiError("TMDb must be enabled before refreshing person metadata", 409)
    top_config = plugin_config_from_db(conn, str(enabled_candidates[0]["id"]))
    if plugin_requires_config_for_entrypoint(enabled_candidates[0], top_config, "person_details"):
        raise NextApiError("Person metadata plugin configuration is incomplete", 409)

    merged: dict[str, Any] = {}
    localizations_by_lang: dict[str, dict[str, str]] = {}
    source_providers: list[str] = []
    merged_aliases: list[str] = []
    merged_imdb = ""
    merged_profiles: list[Any] = []
    primary_plugin: dict[str, Any] | None = None
    primary_execution: dict[str, Any] = {}
    primary_result: dict[str, Any] = {}
    primary_context: dict[str, Any] | None = None
    primary_language = ""
    last_error = ""

    def _accept(key: str, value: Any) -> None:
        if value in (None, "", [], {}):
            return
        if merged.get(key) in (None, "", [], {}):
            merged[key] = value

    for plugin in enabled_candidates:
        config = plugin_config_from_db(conn, str(plugin["id"]))
        if plugin_requires_config_for_entrypoint(plugin, config, "person_details"):
            continue
        context = plugin_execution_context(conn, plugin, config, actor)
        execution = run_plugin_entrypoint(str(plugin["id"]), "person_details", {"tmdbId": tmdb_id}, context)
        if execution.get("status") != "ok":
            last_error = execution.get("error") or last_error
            continue
        result = execution.get("result") or {}
        normalized = {
            "name": clean_text(result.get("name")),
            "birth_date": clean_text(result.get("birthday") or result.get("birthDate")),
            "death_date": clean_text(result.get("deathday") or result.get("deathDate")),
            "place_of_birth": clean_text(result.get("placeOfBirth") or result.get("place_of_birth")),
            "known_for": clean_text(result.get("knownFor") or result.get("known_for")),
            "biography": clean_text(result.get("biography")),
            "profile_url": first_usable_image(
                result.get("profileUrl"),
                result.get("profile_url"),
                result.get("photoUrl"),
                result.get("photo_url"),
            ),
        }
        provider_aliases = [
            clean_text(a) for a in (result.get("alsoKnownAs") or result.get("also_known_as") or []) if clean_text(a)
        ]
        provider_imdb = clean_text(result.get("imdbId") or result.get("imdb_id"))
        provider_profiles = list(result.get("profiles") or [])
        provider_localizations = result.get("localizations") or []
        if not (
            any(normalized.values())
            or provider_aliases
            or provider_imdb
            or provider_profiles
            or provider_localizations
        ):
            continue
        if primary_plugin is None:
            primary_plugin = plugin
            primary_execution = execution
            primary_result = result
            primary_context = context
            primary_language = clean_text(result.get("language")) or "en-US"
        if str(plugin["id"]) not in source_providers:
            source_providers.append(str(plugin["id"]))
        for key, value in normalized.items():
            _accept(key, value)
        if not merged_aliases and provider_aliases:
            merged_aliases = provider_aliases
        if not merged_imdb and provider_imdb:
            merged_imdb = provider_imdb
        if not merged_profiles and provider_profiles:
            merged_profiles = provider_profiles
        provider_language = clean_text(result.get("language")) or primary_language or "en-US"
        for localization in provider_localizations:
            lang = clean_text(localization.get("lang"))
            biography = clean_text(localization.get("biography"))
            if not lang or not biography:
                continue
            localizations_by_lang.setdefault(lang.lower(), {"lang": lang, "biography": biography})
        if normalized["biography"]:
            localizations_by_lang.setdefault(
                provider_language.lower(),
                {"lang": provider_language, "biography": normalized["biography"]},
            )

    if primary_plugin is None:
        raise NextApiError(last_error or "Person metadata plugin returned no usable data", 422)

    language = primary_language or "en-US"
    updates = {
        "name": merged.get("name") or "",
        "birth_date": merged.get("birth_date") or "",
        "death_date": merged.get("death_date") or "",
        "place_of_birth": merged.get("place_of_birth") or "",
        "known_for": merged.get("known_for") or "",
        "biography": merged.get("biography") or "",
        "profile_url": merged.get("profile_url") or "",
        "language": language,
        "source": clean_text(primary_result.get("provider")) or primary_plugin.get("id"),
        "source_ref": clean_text(primary_result.get("sourceRef")) or f"tmdb:person:{tmdb_id}",
    }
    if updates["biography"]:
        localizations_by_lang.setdefault(language.lower(), {"lang": language, "biography": updates["biography"]})
    localizations = list(localizations_by_lang.values())

    aliases = merged_aliases[:50]
    imdb_id = merged_imdb
    profile_candidates = list(merged_profiles)
    if updates["profile_url"]:
        profile_candidates.insert(0, updates["profile_url"])
    profile_urls = sanitize_profile_urls(profile_candidates)

    # Awards run as an independent best-effort sub-step on the primary provider: a
    # slow/flaky Wikidata provider must never fail the metadata mapping, and a
    # transient empty/miss must not wipe awards that were previously stored.
    awards_status = "skipped"
    awards_state = None
    awards_hit = False
    awards: list[Any] = []
    award_groups: list[Any] = []
    awards_result: dict[str, Any] = {}
    try:
        awards_execution = run_plugin_entrypoint(
            str(primary_plugin["id"]),
            "person_awards",
            {"tmdbId": tmdb_id, "imdbId": imdb_id},
            primary_context,
        )
        awards_status = awards_execution.get("status")
        awards_state = awards_execution.get("state")
        if awards_execution.get("status") == "ok":
            awards_result = awards_execution.get("result") or {}
            awards = awards_result.get("awards") or []
            award_groups = awards_result.get("awardGroups") or []
            awards_hit = bool(awards)
    except Exception:
        current_app.logger.warning(
            "Person awards lookup failed for %s; keeping existing awards", person_id, exc_info=True
        )
        awards_status = "error"

    preview_detail = json_ready(detail)
    preview_person = preview_detail.get("person") if isinstance(preview_detail.get("person"), dict) else {}
    preview_metadata = preview_person.get("metadata") if isinstance(preview_person.get("metadata"), dict) else {}
    preview_metadata = dict(preview_metadata)
    for key in ("name", "birth_date", "death_date", "place_of_birth", "known_for"):
        if updates.get(key):
            preview_person[key] = updates[key]
    if updates["profile_url"]:
        preview_person["profile_url"] = updates["profile_url"]
        preview_metadata["profile_url"] = updates["profile_url"]
    if updates["biography"]:
        preview_person["biography"] = updates["biography"]
        preview_metadata["biography"] = updates["biography"]
    if aliases:
        preview_metadata["alsoKnownAs"] = aliases
    if imdb_id:
        preview_metadata["imdbId"] = imdb_id
    if profile_urls:
        preview_metadata["profiles"] = profile_urls
    if awards_hit:
        preview_metadata["awards"] = awards
        preview_metadata["awardGroups"] = award_groups
        preview_metadata["awards_source"] = (
            clean_text(awards_result.get("provider"))
            or clean_text((awards[0] if awards else {}).get("source"))
            or "wikidata"
        )
        preview_metadata["awards_source_ref"] = clean_text(awards_result.get("sourceRef"))
        preview_metadata["awards_fetched_at"] = datetime.utcnow().isoformat(timespec="seconds") + "Z"
    preview_metadata["person_metadata_source"] = updates["source"]
    preview_metadata["person_metadata_source_ref"] = updates["source_ref"]
    preview_metadata["person_metadata_sources"] = sorted({str(item) for item in source_providers if item})
    preview_metadata["person_metadata_fetched_at"] = datetime.utcnow().isoformat(timespec="seconds") + "Z"
    preview_person["metadata"] = preview_metadata
    preview_detail["person"] = preview_person
    if localizations:
        preview_detail["localizations"] = [dict(item) for item in localizations]

    if not dry_run:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE people
                SET
                    name=COALESCE(NULLIF(%s, ''), name),
                    birth_date=COALESCE(NULLIF(%s, '')::date, birth_date),
                    death_date=COALESCE(NULLIF(%s, '')::date, death_date),
                    place_of_birth=COALESCE(NULLIF(%s, ''), place_of_birth),
                    known_for=COALESCE(NULLIF(%s, ''), known_for),
                    metadata=%s,
                    updated_at=now()
                WHERE id=%s
                """,
                (
                    updates["name"],
                    updates["birth_date"],
                    updates["death_date"],
                    updates["place_of_birth"],
                    updates["known_for"],
                    Jsonb(json_ready(preview_metadata)),
                    person_id,
                ),
            )
            if localizations and table_exists(conn, "person_localizations"):
                for localization in localizations:
                    lang = clean_text(localization.get("lang"))
                    biography = clean_text(localization.get("biography"))
                    if not lang or not biography:
                        continue
                    cur.execute(
                        """
                        INSERT INTO person_localizations (person_id, lang, biography, updated_at)
                        VALUES (%s, %s, %s, now())
                        ON CONFLICT (person_id, lang) DO UPDATE
                        SET biography=EXCLUDED.biography, updated_at=now()
                        """,
                        (person_id, lang, biography),
                    )
        try:
            sync_person_profile_media(conn, person_id, profile_urls, provider_id=updates["source"])
        except Exception:
            current_app.logger.warning(
                "Person profile media sync failed for %s", person_id, exc_info=True
            )
        detail = person_detail_entity(conn, person_id) or preview_detail
    else:
        if profile_urls:
            existing_media = preview_detail.get("personMedia") if isinstance(preview_detail.get("personMedia"), list) else []
            has_primary = any(isinstance(asset, dict) and asset.get("is_primary") for asset in existing_media)
            preview_detail["personMedia"] = [
                {
                    "id": f"preview-{index}",
                    "url": url,
                    "source_url": url,
                    "kind": "profile",
                    "is_primary": (index == 0 and not has_primary),
                    "sort_order": index,
                    "preview": True,
                }
                for index, url in enumerate(profile_urls)
            ]
        detail = preview_detail

    return {
        "dryRun": dry_run,
        "plugin": {
            "id": primary_plugin.get("id"),
            "name": primary_plugin.get("name"),
        },
        "sourceProviders": sorted({str(item) for item in source_providers if item}),
        "execution": {
            "status": primary_execution.get("status"),
            "state": primary_execution.get("state"),
            "elapsedMs": primary_execution.get("elapsedMs"),
            "entrypoint": primary_execution.get("entrypoint"),
        },
        "awards": {
            "status": awards_status,
            "state": awards_state,
            "applied": awards_hit,
            "count": len(awards),
            "groups": len(award_groups),
        },
        "result": primary_result,
        "receivers": None,
        "detail": detail,
    }


def _cached_person_filmography_result(detail: dict[str, Any], *, dry_run: bool) -> dict[str, Any]:
    person = detail.get("person") if isinstance(detail.get("person"), dict) else {}
    metadata = person.get("metadata") if isinstance(person.get("metadata"), dict) else {}
    return {
        "dryRun": dry_run,
        "plugin": {"id": metadata.get("filmography_source"), "name": metadata.get("filmography_source")},
        "execution": {"status": "skipped", "state": "cached", "elapsedMs": 0, "entrypoint": "person_filmography"},
        "result": {},
        "detail": detail,
    }


def refresh_person_filmography(
    conn,
    person_id: UUID,
    *,
    dry_run: bool = False,
    actor: dict[str, Any] | None = None,
    force: bool = True,
) -> dict[str, Any]:
    detail = person_detail_entity(conn, person_id, actor=actor)
    if not detail:
        raise NextApiError("Person not found", 404)
    tmdb_id = detail.get("tmdbId") or ""
    if not tmdb_id:
        raise NextApiError("Person has no TMDb identifier", 409)
    if not force:
        person_metadata = (detail.get("person") or {}).get("metadata")
        fetched_at = person_metadata.get("filmography_fetched_at") if isinstance(person_metadata, dict) else None
        if fetched_at and person_metadata_is_fresh(fetched_at):
            return _cached_person_filmography_result(detail, dry_run=dry_run)
    candidates = person_filmography_source_plugins(conn, include_disabled=True)
    if not candidates:
        raise NextApiError("No enabled filmography plugin is available", 503)
    plugin = next((candidate for candidate in candidates if candidate.get("enabled")), None)
    if plugin is None:
        raise NextApiError("Filmography plugin must be enabled before refreshing filmography", 409)
    config = plugin_config_from_db(conn, str(plugin["id"]))
    if plugin_requires_config_for_entrypoint(plugin, config, "person_filmography"):
        raise NextApiError("Filmography plugin configuration is incomplete", 409)

    context = plugin_execution_context(conn, plugin, config, actor)
    execution = run_plugin_entrypoint(str(plugin["id"]), "person_filmography", {"tmdbId": tmdb_id}, context)
    result = execution.get("result") or {}
    if execution.get("status") != "ok":
        raise NextApiError(execution.get("error") or "Filmography plugin execution failed", 422)

    update_payload = {
        "filmography": result.get("combinedCredits") or {},
        "combined_credits": result.get("combinedCredits") or {},
        "filmography_source": result.get("provider") or plugin.get("id"),
        "filmography_source_ref": result.get("sourceRef") or "",
        "filmography_fetched_at": datetime.utcnow().isoformat(timespec="seconds") + "Z",
    }
    if not dry_run:
        metadata = detail.get("person", {}).get("metadata")
        if not isinstance(metadata, dict):
            metadata = {}
        metadata.update(update_payload)
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE people
                SET metadata=%s, updated_at=now()
                WHERE id=%s
                """,
                (Jsonb(json_ready(metadata)), person_id),
            )
        detail = person_detail_entity(conn, person_id, actor=actor) or detail
    else:
        detail["filmography"] = person_filmography_entries_from_metadata(update_payload)
        detail["counts"] = dict(detail.get("counts") or {})
        detail["counts"]["filmography"] = len(detail["filmography"])

    return {
        "dryRun": dry_run,
        "plugin": {
            "id": plugin.get("id"),
            "name": plugin.get("name"),
        },
        "execution": {
            "status": execution.get("status"),
            "state": execution.get("state"),
            "elapsedMs": execution.get("elapsedMs"),
            "entrypoint": execution.get("entrypoint"),
        },
        "result": result,
        "detail": detail,
    }


def set_primary_movie_media_asset(
    conn,
    *,
    movie_id: UUID,
    media_id: UUID,
    kind: str,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if kind not in {"poster", "backdrop"}:
        raise NextApiError("kind must be poster or backdrop", 400)
    if not table_exists(conn, "movies") or not table_exists(conn, "entity_media") or not table_exists(conn, "media_assets"):
        raise NextApiError("Media asset tables are not available", 503)

    with conn.cursor() as cur:
        cur.execute("SELECT id FROM movies WHERE id=%s", (movie_id,))
        if not cur.fetchone():
            raise NextApiError("Movie not found", 404)
        cur.execute(
            """
            SELECT
                ma.id,
                ma.kind,
                ma.variant,
                ma.storage_backend,
                ma.storage_key,
                ma.source_url,
                ma.provider_id,
                ma.content_type,
                ma.width,
                ma.height,
                ma.size_bytes,
                ma.sha256,
                ma.metadata,
                em.role,
                em.is_primary,
                em.sort_order
            FROM entity_media em
            JOIN media_assets ma ON ma.id = em.media_id
            WHERE em.entity_type='movie'
              AND em.entity_id=%s
              AND em.media_id=%s
              AND em.deleted_at IS NULL
              AND em.hidden_at IS NULL
              AND ma.kind=%s
            """,
            (movie_id, media_id, kind),
        )
        media = cur.fetchone()
        if not media:
            raise NextApiError("Media asset is not linked to this movie", 404)
        cur.execute(
            """
            UPDATE entity_media em
            SET is_primary=false,
                sort_order=GREATEST(em.sort_order, 1)
            FROM media_assets ma
            WHERE ma.id = em.media_id
              AND em.entity_type='movie'
              AND em.entity_id=%s
              AND em.deleted_at IS NULL
              AND em.hidden_at IS NULL
              AND ma.kind=%s
              AND em.is_primary=true
            """,
            (movie_id, kind),
        )
        cur.execute(
            """
            UPDATE entity_media
            SET is_primary=true,
                sort_order=0
            WHERE entity_type='movie'
              AND entity_id=%s
              AND media_id=%s
              AND deleted_at IS NULL
              AND hidden_at IS NULL
            """,
            (movie_id, media_id),
        )
        media_metadata = media.get("metadata") if isinstance(media, dict) else {}
        media_metadata = media_metadata if isinstance(media_metadata, dict) else {}
        media_metadata.update(
            {
                "lockedPrimary": True,
                "userSelectedPrimary": True,
                "source": media_metadata.get("source") or "manual_selection",
                "selectedBy": actor_job_payload(actor or {}) if actor else None,
            }
        )
        cur.execute("UPDATE media_assets SET metadata=%s WHERE id=%s", (Jsonb(json_ready(media_metadata)), media_id))
        cur.execute(
            "UPDATE movies SET metadata=metadata || %s, updated_at=now() WHERE id=%s",
            (
                Jsonb(
                    json_ready(
                        {
                            f"{kind}_url": media_asset_public_url(media),
                            f"{kind}_locked": True,
                        }
                    )
                ),
                movie_id,
            ),
        )

    revision = record_sync_change(
        conn,
        movie_id,
        {
            "movieId": str(movie_id),
            "operation": "movie.media_primary_set",
            "kind": kind,
            "mediaId": str(media_id),
            "actor": actor_job_payload(actor or {}) if actor else None,
        },
    )
    media["is_primary"] = True
    media["sort_order"] = 0
    media["url"] = media_asset_public_url(media)
    return {"movieId": str(movie_id), "kind": kind, "media": media, "revision": revision}


def set_primary_person_media_asset(
    conn,
    *,
    person_id: UUID,
    media_id: UUID,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not table_exists(conn, "people") or not table_exists(conn, "entity_media") or not table_exists(conn, "media_assets"):
        raise NextApiError("Media asset tables are not available", 503)

    with conn.cursor() as cur:
        cur.execute("SELECT id FROM people WHERE id=%s", (person_id,))
        if not cur.fetchone():
            raise NextApiError("Person not found", 404)
        cur.execute(
            """
            SELECT
                ma.id,
                ma.kind,
                ma.variant,
                ma.storage_backend,
                ma.storage_key,
                ma.source_url,
                ma.provider_id,
                ma.content_type,
                ma.width,
                ma.height,
                ma.size_bytes,
                ma.sha256,
                ma.metadata,
                em.role,
                em.is_primary,
                em.sort_order
            FROM entity_media em
            JOIN media_assets ma ON ma.id = em.media_id
            WHERE em.entity_type='person'
              AND em.entity_id=%s
              AND em.media_id=%s
              AND em.deleted_at IS NULL
              AND em.hidden_at IS NULL
              AND ma.kind='profile'
            """,
            (person_id, media_id),
        )
        media = cur.fetchone()
        if not media:
            raise NextApiError("Media asset is not linked to this person", 404)
        cur.execute(
            """
            UPDATE entity_media em
            SET is_primary=false,
                sort_order=GREATEST(em.sort_order, 1)
            FROM media_assets ma
            WHERE ma.id = em.media_id
              AND em.entity_type='person'
              AND em.entity_id=%s
              AND em.deleted_at IS NULL
              AND em.hidden_at IS NULL
              AND ma.kind='profile'
              AND em.is_primary=true
            """,
            (person_id,),
        )
        cur.execute(
            """
            UPDATE entity_media
            SET is_primary=true,
                sort_order=0
            WHERE entity_type='person'
              AND entity_id=%s
              AND media_id=%s
              AND deleted_at IS NULL
              AND hidden_at IS NULL
            """,
            (person_id, media_id),
        )
        media_metadata = media.get("metadata") if isinstance(media, dict) else {}
        media_metadata = media_metadata if isinstance(media_metadata, dict) else {}
        media_metadata.update(
            {
                "lockedPrimary": True,
                "userSelectedPrimary": True,
                "source": media_metadata.get("source") or "manual_selection",
                "selectedBy": actor_job_payload(actor or {}) if actor else None,
            }
        )
        cur.execute("UPDATE media_assets SET metadata=%s WHERE id=%s", (Jsonb(json_ready(media_metadata)), media_id))
        cur.execute(
            "UPDATE people SET profile_asset_id=%s, updated_at=now() WHERE id=%s",
            (media_id, person_id),
        )

    media["is_primary"] = True
    media["sort_order"] = 0
    media["url"] = media_asset_public_url(media)
    return {"personId": str(person_id), "kind": "profile", "media": media}


def uploaded_artwork_file() -> tuple[Any, str | None]:
    inferred_kind = None
    upload = request.files.get("file")
    if not upload:
        upload = request.files.get("poster")
        inferred_kind = "poster" if upload else None
    if not upload:
        upload = request.files.get("backdrop")
        inferred_kind = "backdrop" if upload else None
    if not upload or not upload.filename:
        raise NextApiError("Upload artwork as multipart field 'file'", 400)
    return upload, inferred_kind


def save_uploaded_artwork_file(upload: Any, *, kind: str) -> dict[str, Any]:
    if kind not in MOVIE_ARTWORK_KINDS:
        raise NextApiError("kind must be poster or backdrop", 400)
    try:
        upload.stream.seek(0)
        image = Image.open(upload.stream)
        image = ImageOps.exif_transpose(image)
        if image.mode in ("RGBA", "LA") or (image.mode == "P" and "transparency" in image.info):
            alpha_image = image.convert("RGBA")
            background = Image.new("RGBA", alpha_image.size, (255, 255, 255, 255))
            background.alpha_composite(alpha_image)
            image = background.convert("RGB")
        elif image.mode not in ("RGB", "L"):
            image = image.convert("RGB")
        elif image.mode == "L":
            image = image.convert("RGB")
        image.thumbnail((MAX_ARTWORK_DIMENSION, MAX_ARTWORK_DIMENSION), Image.Resampling.LANCZOS)
        width, height = image.size
        buffer = io.BytesIO()
        image.save(buffer, format="JPEG", quality=90)
        data = buffer.getvalue()
    except UnidentifiedImageError as exc:
        raise NextApiError("Uploaded file is not a valid image", 400) from exc
    except Exception as exc:
        raise NextApiError(f"Artwork upload failed: {exc}", 400) from exc
    if len(data) > MAX_ARTWORK_UPLOAD_BYTES:
        raise NextApiError("Artwork upload may not exceed 20 MB after processing", 413)

    digest = hashlib.sha256(data).hexdigest()
    folder = "posters" if kind == "poster" else "backdrops"
    data_dir = legacy_data_dir().resolve()
    target_dir = data_dir / "media" / folder / "original" / digest[:2] / digest[2:4]
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / f"{digest}.jpg"
    if not target.exists():
        target.write_bytes(data)
    storage_key = target.relative_to(data_dir).as_posix()
    return {
        "path": target,
        "storageKey": storage_key,
        "sha256": digest,
        "sizeBytes": len(data),
        "contentType": "image/jpeg",
        "width": width,
        "height": height,
        "originalFilename": os.path.basename(str(upload.filename or "")),
    }


def save_uploaded_profile_avatar_file(upload: Any) -> dict[str, Any]:
    try:
        upload.stream.seek(0)
        image = Image.open(upload.stream)
        image = ImageOps.exif_transpose(image)
        if image.mode in ("RGBA", "LA") or (image.mode == "P" and "transparency" in image.info):
            alpha_image = image.convert("RGBA")
            background = Image.new("RGBA", alpha_image.size, (255, 255, 255, 255))
            background.alpha_composite(alpha_image)
            image = background.convert("RGB")
        elif image.mode not in ("RGB", "L"):
            image = image.convert("RGB")
        elif image.mode == "L":
            image = image.convert("RGB")
        image.thumbnail((1024, 1024), Image.Resampling.LANCZOS)
        width, height = image.size
        buffer = io.BytesIO()
        image.save(buffer, format="JPEG", quality=88, optimize=True)
        data = buffer.getvalue()
    except UnidentifiedImageError as exc:
        raise NextApiError("Uploaded file is not a valid image", 400) from exc
    except Exception as exc:
        raise NextApiError(f"Avatar upload failed: {exc}", 400) from exc
    if len(data) > MAX_ARTWORK_UPLOAD_BYTES:
        raise NextApiError("Avatar upload may not exceed 20 MB after processing", 413)

    digest = hashlib.sha256(data).hexdigest()
    data_dir = legacy_data_dir().resolve()
    target_dir = data_dir / "media" / "profiles" / "original" / digest[:2] / digest[2:4]
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / f"{digest}.jpg"
    if not target.exists():
        target.write_bytes(data)
    storage_key = target.relative_to(data_dir).as_posix()
    return {
        "path": target,
        "storageKey": storage_key,
        "sha256": digest,
        "sizeBytes": len(data),
        "contentType": "image/jpeg",
        "width": width,
        "height": height,
        "originalFilename": os.path.basename(str(upload.filename or "")),
    }


def create_uploaded_profile_avatar_asset(
    conn,
    *,
    upload_info: dict[str, Any],
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not table_exists(conn, "media_assets"):
        raise NextApiError("Media asset table is not available", 503)
    storage_key = clean_text(upload_info.get("storageKey")) or ""
    if not storage_key:
        raise NextApiError("Uploaded avatar did not produce a storage key", 500)
    media_id = media_asset_uuid(storage_key)
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO media_assets (
                id,
                kind,
                variant,
                storage_backend,
                storage_key,
                source_url,
                provider_id,
                content_type,
                width,
                height,
                size_bytes,
                sha256,
                metadata
            )
            VALUES (%s, 'profile', 'original', 'local', %s, NULL, 'upload', %s, %s, %s, %s, %s, %s)
            ON CONFLICT (kind, variant, sha256) DO UPDATE SET
                storage_backend=EXCLUDED.storage_backend,
                storage_key=EXCLUDED.storage_key,
                provider_id=EXCLUDED.provider_id,
                content_type=EXCLUDED.content_type,
                width=EXCLUDED.width,
                height=EXCLUDED.height,
                size_bytes=EXCLUDED.size_bytes,
                metadata=EXCLUDED.metadata
            RETURNING
                id,
                kind,
                variant,
                storage_backend,
                storage_key,
                source_url,
                provider_id,
                content_type,
                width,
                height,
                size_bytes,
                sha256,
                metadata,
                created_at
            """,
            (
                media_id,
                storage_key,
                upload_info.get("contentType"),
                upload_info.get("width"),
                upload_info.get("height"),
                upload_info.get("sizeBytes"),
                upload_info.get("sha256"),
                Jsonb(
                    {
                        "source": "profile_upload",
                        "originalFilename": upload_info.get("originalFilename"),
                        "uploadedBy": actor_job_payload(actor or {}) if actor else None,
                    }
                ),
            ),
        )
        return cur.fetchone()


