def store_uploaded_poster_asset(
    conn,
    *,
    upload_info: dict[str, Any],
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Persist an uploaded poster image as a shared media asset and return the row.

    Used by lightweight entities (e.g. wishlist items) that keep a poster URL
    string rather than an entity_media relation. Serve via media_asset_public_url.
    """
    return store_uploaded_artwork_asset(
        conn,
        upload_info=upload_info,
        kind="poster",
        source="wishlist_upload",
        actor=actor,
    )


def create_uploaded_movie_media_asset(
    conn,
    *,
    movie_id: UUID,
    kind: str,
    upload_info: dict[str, Any],
    primary: bool,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not table_exists(conn, "movies") or not table_exists(conn, "media_assets") or not table_exists(conn, "entity_media"):
        raise NextApiError("Media asset tables are not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT id FROM movies WHERE id=%s", (movie_id,))
        if not cur.fetchone():
            raise NextApiError("Movie not found", 404)

        storage_key = clean_text(upload_info.get("storageKey")) or ""
        if not storage_key:
            raise NextApiError("Uploaded artwork did not produce a storage key", 500)
        media_id = media_asset_uuid(storage_key)
        cur.execute(
            """
            INSERT INTO media_assets (
                id,
                kind,
                variant,
                storage_backend,
                storage_key,
                source_url,
                provider_id,
                content_type,
                width,
                height,
                size_bytes,
                sha256,
                metadata
            )
            VALUES (%s, %s, 'original', 'local', %s, NULL, 'upload', %s, %s, %s, %s, %s, %s)
            ON CONFLICT (kind, variant, sha256) DO UPDATE SET
                kind=EXCLUDED.kind,
                storage_backend=EXCLUDED.storage_backend,
                storage_key=EXCLUDED.storage_key,
                source_url=COALESCE(media_assets.source_url, EXCLUDED.source_url),
                provider_id=EXCLUDED.provider_id,
                content_type=EXCLUDED.content_type,
                width=EXCLUDED.width,
                height=EXCLUDED.height,
                size_bytes=EXCLUDED.size_bytes,
                sha256=EXCLUDED.sha256,
                metadata=EXCLUDED.metadata
            RETURNING
                id,
                kind,
                variant,
                storage_backend,
                storage_key,
                source_url,
                provider_id,
                content_type,
                width,
                height,
                size_bytes,
                sha256,
                metadata,
                created_at
            """,
            (
                media_id,
                kind,
                storage_key,
                upload_info.get("contentType"),
                upload_info.get("width"),
                upload_info.get("height"),
                upload_info.get("sizeBytes"),
                upload_info.get("sha256"),
                Jsonb(
                    {
                        "source": "upload",
                        "originalFilename": upload_info.get("originalFilename"),
                        "uploadedBy": actor_job_payload(actor or {}) if actor else None,
                        "lockedPrimary": bool(primary),
                        "userSelectedPrimary": bool(primary),
                    }
                ),
            ),
        )
        media = cur.fetchone()

        if primary:
            cur.execute(
                """
                UPDATE entity_media em
                SET is_primary=false,
                    sort_order=GREATEST(em.sort_order, 1)
                FROM media_assets ma
                WHERE ma.id = em.media_id
                  AND em.entity_type='movie'
                  AND em.entity_id=%s
                  AND ma.kind=%s
                  AND em.is_primary=true
                """,
                (movie_id, kind),
            )
            sort_order = 0
        else:
            cur.execute(
                """
                SELECT COALESCE(MAX(sort_order), 0) + 1 AS next_sort
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                WHERE em.entity_type='movie'
                  AND em.entity_id=%s
                  AND em.deleted_at IS NULL
                  AND em.hidden_at IS NULL
                  AND ma.kind=%s
                """,
                (movie_id, kind),
            )
            row = cur.fetchone()
            sort_order = int(row["next_sort"] if row else 1)

        cur.execute(
            """
            INSERT INTO entity_media (
                entity_type,
                entity_id,
                media_id,
                role,
                is_primary,
                sort_order
            )
            VALUES ('movie', %s, %s, %s, %s, %s)
            ON CONFLICT (entity_type, entity_id, media_id, role) DO UPDATE SET
                is_primary=EXCLUDED.is_primary,
                sort_order=EXCLUDED.sort_order,
                deleted_at=NULL,
                deleted_by=NULL,
                purge_after=NULL,
                hidden_at=NULL,
                restore_metadata='{}'::jsonb
            """,
            (movie_id, media["id"], kind, primary, sort_order),
        )
        cur.execute(
            "UPDATE movies SET metadata=metadata || %s, updated_at=now() WHERE id=%s",
            (
                Jsonb(
                    json_ready(
                        ({f"{kind}_url": media_asset_public_url(media), f"{kind}_locked": True} if primary else {})
                    )
                ),
                movie_id,
            ),
        )

    media["role"] = kind
    media["is_primary"] = primary
    media["sort_order"] = sort_order
    media["url"] = media_asset_public_url(media)
    revision = record_sync_change(
        conn,
        movie_id,
        {
            "movieId": str(movie_id),
            "operation": "movie.media_uploaded",
            "kind": kind,
            "mediaId": str(media["id"]),
            "primary": primary,
            "actor": actor_job_payload(actor or {}) if actor else None,
        },
    )
    return {"movieId": str(movie_id), "kind": kind, "media": media, "revision": revision}


# Which table owns an entity that can carry artwork. The map itself lives in
# next_metadata, which is the lower layer and the one that writes artwork coming
# from a source; keeping a second copy here is how the upload path and the fetch
# path would come to disagree about what is storable.
#
# Not every key is reachable from here: `series_season` carries a poster but has
# no page and no upload route, so the route-facing check below stays narrower
# than the map on purpose.
_UPLOADABLE_ARTWORK_ENTITIES = ("movie", "container", "series")


def entity_artwork_table(entity_type: str) -> str:
    if entity_type not in _UPLOADABLE_ARTWORK_ENTITIES:
        raise NextApiError("entityType must be movie, container or series", 400)
    return ENTITY_ARTWORK_TABLES[entity_type]


def set_primary_entity_media_asset(
    conn,
    *,
    entity_type: str,
    entity_id: UUID,
    media_id: UUID,
    kind: str,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    entity_table = entity_artwork_table(entity_type)
    if kind not in MOVIE_ARTWORK_KINDS:
        raise NextApiError("kind must be poster or backdrop", 400)
    if not table_exists(conn, entity_table) or not table_exists(conn, "entity_media") or not table_exists(conn, "media_assets"):
        raise NextApiError("Media asset tables are not available", 503)
    container_id = entity_id
    with conn.cursor() as cur:
        cur.execute(f"SELECT id FROM {entity_table} WHERE id=%s", (entity_id,))
        if not cur.fetchone():
            raise NextApiError("Item not found", 404)
        cur.execute(
            """
            SELECT
                id,
                kind,
                variant,
                storage_backend,
                storage_key,
                source_url,
                provider_id,
                content_type,
                width,
                height,
                size_bytes,
                sha256,
                metadata,
                created_at
            FROM media_assets
            WHERE id=%s AND kind=%s
            """,
            (media_id, kind),
        )
        media = cur.fetchone()
        if not media:
            raise NextApiError("Media asset not found", 404)
        cur.execute(
            """
            UPDATE entity_media em
            SET is_primary=false,
                sort_order=GREATEST(em.sort_order, 1)
            FROM media_assets ma
            WHERE ma.id = em.media_id
              AND em.entity_type=%s
              AND em.entity_id=%s
              AND em.deleted_at IS NULL
              AND em.hidden_at IS NULL
              AND ma.kind=%s
              AND em.is_primary=true
            """,
            (entity_type, container_id, kind),
        )
        cur.execute(
            """
            INSERT INTO entity_media (
                entity_type,
                entity_id,
                media_id,
                role,
                is_primary,
                sort_order
            )
            VALUES (%s, %s, %s, %s, true, 0)
            ON CONFLICT (entity_type, entity_id, media_id, role) DO UPDATE SET
                is_primary=true,
                sort_order=0,
                deleted_at=NULL,
                deleted_by=NULL,
                purge_after=NULL,
                restore_metadata='{}'::jsonb
            """,
            (entity_type, container_id, media_id, kind),
        )
        media_metadata = media.get("metadata") if isinstance(media, dict) else {}
        media_metadata = media_metadata if isinstance(media_metadata, dict) else {}
        media_metadata.update(
            {
                "lockedPrimary": True,
                "userSelectedPrimary": True,
                "source": media_metadata.get("source") or "manual_selection",
                "selectedBy": actor_job_payload(actor or {}) if actor else None,
            }
        )
        cur.execute("UPDATE media_assets SET metadata=%s WHERE id=%s", (Jsonb(json_ready(media_metadata)), media_id))
        cur.execute(
            f"UPDATE {entity_table} SET metadata=metadata || %s, updated_at=now() WHERE id=%s",
            (
                Jsonb(
                    json_ready(
                        {
                            f"{kind}_url": media_asset_public_url(media),
                            f"{kind}_locked": True,
                        }
                    )
                ),
                container_id,
            ),
        )
    media["is_primary"] = True
    media["sort_order"] = 0
    media["role"] = kind
    media["url"] = media_asset_public_url(media)
    return {f"{entity_type}Id": str(entity_id), "kind": kind, "media": media, "revision": 0}


def set_primary_container_media_asset(
    conn, *, container_id: UUID, media_id: UUID, kind: str, actor: dict[str, Any] | None = None
) -> dict[str, Any]:
    return set_primary_entity_media_asset(
        conn,
        entity_type="container",
        entity_id=container_id,
        media_id=media_id,
        kind=kind,
        actor=actor,
    )


def create_uploaded_entity_media_asset(
    conn,
    *,
    entity_type: str,
    entity_id: UUID,
    kind: str,
    upload_info: dict[str, Any],
    primary: bool,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    entity_table = entity_artwork_table(entity_type)
    if not table_exists(conn, entity_table) or not table_exists(conn, "media_assets") or not table_exists(conn, "entity_media"):
        raise NextApiError("Media asset tables are not available", 503)
    container_id = entity_id
    with conn.cursor() as cur:
        cur.execute(f"SELECT id FROM {entity_table} WHERE id=%s", (entity_id,))
        if not cur.fetchone():
            raise NextApiError("Item not found", 404)
        storage_key = clean_text(upload_info.get("storageKey")) or ""
        if not storage_key:
            raise NextApiError("Uploaded artwork did not produce a storage key", 500)
        media_id = media_asset_uuid(storage_key)
        cur.execute(
            """
            INSERT INTO media_assets (
                id,
                kind,
                variant,
                storage_backend,
                storage_key,
                source_url,
                provider_id,
                content_type,
                width,
                height,
                size_bytes,
                sha256,
                metadata
            )
            VALUES (%s, %s, 'original', 'local', %s, NULL, 'upload', %s, %s, %s, %s, %s, %s)
            ON CONFLICT (kind, variant, sha256) DO UPDATE SET
                storage_backend=EXCLUDED.storage_backend,
                storage_key=EXCLUDED.storage_key,
                provider_id=EXCLUDED.provider_id,
                content_type=EXCLUDED.content_type,
                width=EXCLUDED.width,
                height=EXCLUDED.height,
                size_bytes=EXCLUDED.size_bytes,
                metadata=EXCLUDED.metadata
            RETURNING
                id,
                kind,
                variant,
                storage_backend,
                storage_key,
                source_url,
                provider_id,
                content_type,
                width,
                height,
                size_bytes,
                sha256,
                metadata,
                created_at
            """,
            (
                media_id,
                kind,
                storage_key,
                upload_info.get("contentType"),
                upload_info.get("width"),
                upload_info.get("height"),
                upload_info.get("sizeBytes"),
                upload_info.get("sha256"),
                Jsonb(
                    {
                        "source": "upload",
                        "originalFilename": upload_info.get("originalFilename"),
                        "uploadedBy": actor_job_payload(actor or {}) if actor else None,
                        "lockedPrimary": bool(primary),
                        "userSelectedPrimary": bool(primary),
                    }
                ),
            ),
        )
        media = cur.fetchone()
        if primary:
            cur.execute(
                """
                UPDATE entity_media em
                SET is_primary=false,
                    sort_order=GREATEST(em.sort_order, 1)
                FROM media_assets ma
                WHERE ma.id = em.media_id
                  AND em.entity_type=%s
                  AND em.entity_id=%s
                  AND ma.kind=%s
                  AND em.is_primary=true
                """,
                (entity_type, container_id, kind),
            )
            sort_order = 0
        else:
            cur.execute(
                """
                SELECT COALESCE(MAX(sort_order), 0) + 1 AS next_sort
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                WHERE em.entity_type=%s
                  AND em.entity_id=%s
                  AND em.deleted_at IS NULL
                  AND em.hidden_at IS NULL
                  AND ma.kind=%s
                """,
                (entity_type, container_id, kind),
            )
            row = cur.fetchone()
            sort_order = int(row["next_sort"] if row else 1)
        cur.execute(
            """
            INSERT INTO entity_media (
                entity_type,
                entity_id,
                media_id,
                role,
                is_primary,
                sort_order
            )
            VALUES (%s, %s, %s, %s, %s, %s)
            ON CONFLICT (entity_type, entity_id, media_id, role) DO UPDATE SET
                is_primary=EXCLUDED.is_primary,
                sort_order=EXCLUDED.sort_order,
                deleted_at=NULL,
                deleted_by=NULL,
                purge_after=NULL,
                restore_metadata='{}'::jsonb
            """,
            (entity_type, container_id, media["id"], kind, primary, sort_order),
        )
        cur.execute(
            f"UPDATE {entity_table} SET metadata=metadata || %s, updated_at=now() WHERE id=%s",
            (
                Jsonb(
                    json_ready(
                        ({f"{kind}_url": media_asset_public_url(media), f"{kind}_locked": True} if primary else {})
                    )
                ),
                container_id,
            ),
        )
    media["role"] = kind
    media["is_primary"] = primary
    media["sort_order"] = sort_order
    media["url"] = media_asset_public_url(media)
    return {f"{entity_type}Id": str(entity_id), "kind": kind, "media": media, "revision": 0}


