def container_member_movie_entities(conn, container_id: UUID, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "container_movies") or not table_exists(conn, "movies"):
        return []
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                m.id,
                m.public_id,
                m.barcode,
                m.title,
                m.sort_title,
                m.original_title,
                m.year,
                m.release_date,
                m.format,
                m.media_type,
                m.edition,
                m.edition_type,
                m.country,
                m.language,
                m.runtime_minutes,
                m.overview,
                m.rating,
                m.metadata,
                m.created_at,
                m.updated_at,
                m.metadata->>'poster_url' AS poster_url,
                m.metadata->>'backdrop_url' AS backdrop_url,
                cm.sort_order,
                cm.created_at AS linked_at
            FROM container_movies cm
            JOIN movies m ON m.id = cm.movie_id
            WHERE cm.container_id=%s
              AND {visibility_where}
            ORDER BY cm.sort_order, lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
            """,
            (container_id, *visibility_params),
        )
        return cur.fetchall()


def collection_item_entities(conn, container_id: UUID, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "collection_items"):
        return []
    items: list[dict[str, Any]] = []
    if table_exists(conn, "movies"):
        visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    ci.item_type,
                    ci.item_id,
                    ci.sort_order,
                    ci.created_at AS linked_at,
                    'movie' AS entity_type,
                    m.id AS entity_id,
                    m.public_id,
                    m.barcode,
                    m.title,
                    m.sort_title,
                    m.original_title,
                    m.year,
                    m.format,
                    m.media_type,
                    m.edition,
                    m.metadata,
                    m.metadata->>'poster_url' AS poster_url,
                    m.metadata->>'backdrop_url' AS backdrop_url
                FROM collection_items ci
                JOIN movies m ON m.id = ci.item_id
                WHERE ci.collection_id=%s AND ci.item_type='movie'
                  AND {visibility_where}
                ORDER BY ci.sort_order, lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                """,
                (container_id, *visibility_params),
            )
            items.extend(cur.fetchall())
    if table_exists(conn, "containers"):
        visibility_where, visibility_params = visible_container_where_sql(conn, actor, "c") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    ci.item_type,
                    ci.item_id,
                    ci.sort_order,
                    ci.created_at AS linked_at,
                    'container' AS entity_type,
                    c.id AS entity_id,
                    c.public_id,
                    c.container_type,
                    c.barcode,
                    c.badge_label,
                    c.title,
                    c.year,
                    c.description,
                    c.metadata,
                    c.metadata->>'poster_url' AS poster_url,
                    c.metadata->>'backdrop_url' AS backdrop_url
                FROM collection_items ci
                JOIN containers c ON c.id = ci.item_id
                WHERE ci.collection_id=%s AND ci.item_type <> 'movie'
                  AND {visibility_where}
                ORDER BY ci.sort_order, c.container_type, lower(c.title)
                """,
                (container_id, *visibility_params),
            )
            items.extend(cur.fetchall())
    return sorted(items, key=lambda item: (item.get("sort_order") or 0, str(item.get("title") or "").lower()))


def container_aggregate_movie_entities(
    conn,
    container_id: UUID,
    *,
    max_depth: int = 4,
    actor: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if (
        not table_exists(conn, "containers")
        or not table_exists(conn, "movies")
        or not table_exists(conn, "container_movies")
        or not table_exists(conn, "collection_items")
    ):
        return container_member_movie_entities(conn, container_id, actor=actor)
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    media_join = table_exists(conn, "entity_media") and table_exists(conn, "media_assets")
    media_select = (
        """
                poster_asset.id AS poster_asset_id,
                poster_asset.storage_backend AS poster_asset_storage_backend,
                poster_asset.storage_key AS poster_asset_storage_key,
                poster_asset.source_url AS poster_asset_source_url,
                backdrop_asset.id AS backdrop_asset_id,
                backdrop_asset.storage_backend AS backdrop_asset_storage_backend,
                backdrop_asset.storage_key AS backdrop_asset_storage_key,
                backdrop_asset.source_url AS backdrop_asset_source_url,
        """
        if media_join
        else """
                NULL AS poster_asset_id,
                NULL AS poster_asset_storage_backend,
                NULL AS poster_asset_storage_key,
                NULL AS poster_asset_source_url,
                NULL AS backdrop_asset_id,
                NULL AS backdrop_asset_storage_backend,
                NULL AS backdrop_asset_storage_key,
                NULL AS backdrop_asset_source_url,
        """
    )
    media_join_sql = (
        """
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                      AND em.entity_id=m.id
                      AND em.deleted_at IS NULL
                      AND em.hidden_at IS NULL
                      AND ma.kind='poster'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) poster_asset ON true
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                      AND em.entity_id=m.id
                      AND em.deleted_at IS NULL
                      AND em.hidden_at IS NULL
                      AND ma.kind='backdrop'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) backdrop_asset ON true
        """
        if media_join
        else ""
    )
    with conn.cursor() as cur:
        cur.execute(
            f"""
            WITH RECURSIVE container_tree(id, depth, path) AS (
                SELECT %s::uuid, 0, ARRAY[%s::uuid]
                UNION ALL
                SELECT ci.item_id, ct.depth + 1, ct.path || ci.item_id
                FROM collection_items ci
                JOIN container_tree ct ON ct.id = ci.collection_id
                WHERE ci.item_type <> 'movie'
                  AND ct.depth < %s
                  AND NOT ci.item_id = ANY(ct.path)
            ),
            movie_links AS (
                SELECT cm.movie_id, ct.depth, cm.sort_order, cm.created_at AS linked_at
                FROM container_tree ct
                JOIN container_movies cm ON cm.container_id = ct.id
                UNION ALL
                SELECT ci.item_id AS movie_id, ct.depth, ci.sort_order, ci.created_at AS linked_at
                FROM container_tree ct
                JOIN collection_items ci ON ci.collection_id = ct.id AND ci.item_type='movie'
            ),
            ranked AS (
                SELECT DISTINCT ON (m.id)
                    m.id,
                    m.public_id,
                    m.barcode,
                    m.title,
                    m.sort_title,
                    m.original_title,
                    m.year,
                    m.release_date,
                    m.format,
                    m.media_type,
                    m.edition,
                    m.edition_type,
                    m.country,
                    m.language,
                    m.runtime_minutes,
                    m.overview,
                    m.rating,
                    m.metadata,
                    m.created_at,
                    m.updated_at,
                    COALESCE(m.metadata->>'poster_url', poster_asset.source_url) AS poster_url,
                    COALESCE(m.metadata->>'backdrop_url', backdrop_asset.source_url) AS backdrop_url,
{media_select}
                    ml.depth,
                    ml.sort_order,
                    ml.linked_at
                FROM movie_links ml
                JOIN movies m ON m.id = ml.movie_id
                {media_join_sql}
                WHERE {visibility_where}
                ORDER BY m.id, ml.depth, ml.sort_order, lower(COALESCE(m.sort_title, m.title))
            )
            SELECT *
            FROM ranked
            ORDER BY depth, sort_order, lower(COALESCE(sort_title, title)), year NULLS LAST
            """,
            (container_id, container_id, max_depth, *visibility_params),
        )
        rows = cur.fetchall()
    return [with_preview_media_urls(row) for row in rows]


def container_aggregate_media_asset_entities(conn, movies: list[dict[str, Any]]) -> list[dict[str, Any]]:
    assets: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()

    def add_asset(asset: dict[str, Any], source_movie: dict[str, Any] | None = None) -> None:
        kind = clean_text(asset.get("kind"))
        url = media_asset_public_url(asset) or server_usable_image(asset.get("url") or asset.get("source_url"))
        if kind not in {"poster", "backdrop"} or not url:
            return
        key = (kind, url)
        if key in seen:
            return
        seen.add(key)
        row = dict(asset)
        row["url"] = url
        if source_movie:
            row["sourceMovieId"] = str(source_movie.get("id") or "")
            row["sourceMovieTitle"] = source_movie.get("title") or source_movie.get("original_title") or ""
            row["sourceMovieReleaseDate"] = source_movie.get("release_date") or ""
            row["sourceMovieYear"] = source_movie.get("year") or ""
            row["sourceMovieSortTitle"] = source_movie.get("sort_title") or source_movie.get("title") or ""
        assets.append(row)

    movie_ids = [movie.get("id") for movie in movies if movie.get("id")]
    movie_by_id = {str(movie.get("id")): movie for movie in movies if movie.get("id")}
    if movie_ids and table_exists(conn, "entity_media") and table_exists(conn, "media_assets"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    ma.id,
                    ma.kind,
                    ma.variant,
                    ma.storage_backend,
                    ma.storage_key,
                    ma.source_url,
                    ma.provider_id,
                    ma.content_type,
                    ma.width,
                    ma.height,
                    ma.size_bytes,
                    ma.sha256,
                    ma.metadata,
                    em.role,
                    em.is_primary,
                    em.sort_order,
                    em.entity_id AS source_movie_id,
                    m.title AS source_movie_title,
                    m.sort_title AS source_movie_sort_title,
                    m.release_date AS source_movie_release_date,
                    m.year AS source_movie_year
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                JOIN movies m ON m.id = em.entity_id
                WHERE em.entity_type='movie'
                  AND em.entity_id = ANY(%s)
                  AND em.deleted_at IS NULL
                  AND em.hidden_at IS NULL
                  AND ma.kind IN ('poster', 'backdrop')
                ORDER BY lower(m.title), ma.kind, em.is_primary DESC, em.sort_order, ma.created_at
                """,
                (movie_ids,),
            )
            for row in cur.fetchall():
                source_movie = movie_by_id.get(str(row.get("source_movie_id"))) or {
                    "id": row.get("source_movie_id"),
                    "title": row.get("source_movie_title"),
                    "sort_title": row.get("source_movie_sort_title"),
                    "release_date": row.get("source_movie_release_date"),
                    "year": row.get("source_movie_year"),
                }
                add_asset(row, source_movie)

    for movie in movies:
        for kind in ("poster", "backdrop"):
            url = server_usable_image(movie.get(f"{kind}_url"))
            if url:
                add_asset(
                    {
                        "id": f"aggregate:{kind}:{movie.get('id')}",
                        "kind": kind,
                        "source_url": url,
                        "provider_id": "aggregate",
                        "is_primary": False,
                    },
                    movie,
                )
    return assets


def container_aggregate_video_entities(movies: list[dict[str, Any]]) -> list[dict[str, Any]]:
    videos: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_video(movie: dict[str, Any], item: dict[str, Any]) -> None:
        url = clean_text(item.get("url") or item.get("video_url") or item.get("href"))
        if not url or not url.startswith(("http://", "https://")) or url in seen:
            return
        seen.add(url)
        videos.append(
            {
                "label": clean_text(item.get("label") or item.get("name") or item.get("title") or item.get("type")) or "Video",
                "type": clean_text(item.get("type")),
                "source": clean_text(item.get("source") or item.get("provider")),
                "url": url,
                "sourceMovieId": str(movie.get("id") or ""),
                "sourceMovieTitle": movie.get("title") or movie.get("original_title") or "",
                "sourceMovieReleaseDate": movie.get("release_date") or "",
                "sourceMovieYear": movie.get("year") or "",
                "sourceMovieSortTitle": movie.get("sort_title") or movie.get("title") or "",
            }
        )

    for movie in movies:
        metadata = movie.get("metadata") if isinstance(movie.get("metadata"), dict) else {}
        add_video(movie, {"label": "Trailer", "type": "Trailer", "source": "metadata", "url": movie.get("trailer_url") or metadata.get("trailer_url")})
        for item in metadata.get("videos") if isinstance(metadata.get("videos"), list) else []:
            if isinstance(item, dict):
                add_video(movie, item)
    return videos


def container_aggregate_summary(movies: list[dict[str, Any]], assets: list[dict[str, Any]], videos: list[dict[str, Any]]) -> dict[str, Any]:
    years = sorted({int(str(movie.get("year"))) for movie in movies if str(movie.get("year") or "").isdigit()})
    formats = sorted({clean_text(movie.get("format")) for movie in movies if clean_text(movie.get("format"))}, key=str.lower)
    poster_count = len([asset for asset in assets if asset.get("kind") == "poster"])
    backdrop_count = len([asset for asset in assets if asset.get("kind") == "backdrop"])
    return {
        "movieCount": len(movies),
        "memberTitles": [movie.get("title") for movie in movies if movie.get("title")],
        "formats": ", ".join(formats),
        "yearRange": f"{years[0]}-{years[-1]}" if len(years) > 1 else (str(years[0]) if years else ""),
        "posterCount": poster_count,
        "backdropCount": backdrop_count,
        "artwork": f"{poster_count} posters / {backdrop_count} backdrops",
        "videoCount": len(videos),
    }


def box_set_metadata_source_plugins(conn, *, include_disabled: bool = False) -> list[dict[str, Any]]:
    """Installed ``metadata_source`` plugins exposing ``box_set_candidates``.

    Ordered by ``order_index`` (highest priority first) like the other source
    selectors, so the top provider (e.g. MovieVault) wins when several sources
    return box-set artwork for the same container.
    """
    if not table_exists(conn, "plugins"):
        return []
    sync_metadata_plugin_registry(conn)
    registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
    plugins: list[dict[str, Any]] = []
    for plugin in registry.get("plugins") or []:
        if not plugin.get("installed"):
            continue
        if not include_disabled and not plugin.get("enabled"):
            continue
        if "metadata_source" not in plugin_categories(plugin):
            continue
        if "box_set_candidates" not in plugin_runtime_entrypoints(plugin):
            continue
        plugins.append(plugin)
    return plugins


def link_container_media_option(
    conn,
    *,
    container_id: UUID,
    kind: str,
    source_url: str,
    provider_id: str,
    sort_order: int,
    primary: bool = False,
) -> dict[str, Any] | None:
    """Attach a remote box-set artwork URL to a container as a selectable option.

    Mirrors ``link_media_option`` (movies) for ``entity_type='container'``.
    Never demotes or overwrites an existing user-selected primary; when
    ``primary`` is requested it is only honoured if the container has no other
    primary artwork of this kind yet.
    """
    if kind not in {"poster", "backdrop"}:
        return None
    media_id = ensure_remote_media_asset(conn, kind=kind, source_url=source_url, provider_id=provider_id)
    if not media_id or not table_exists(conn, "entity_media"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT is_primary, deleted_at
            FROM entity_media
            WHERE entity_type='container'
              AND entity_id=%s
              AND media_id=%s
              AND role=%s
            """,
            (container_id, media_id, kind),
        )
        row = cur.fetchone()
        if row and (row["deleted_at"] if isinstance(row, dict) else row[1]):
            return None
        if row and bool(row["is_primary"] if isinstance(row, dict) else row[0]):
            return None
        make_primary = False
        if primary:
            cur.execute(
                """
                SELECT 1
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                WHERE em.entity_type='container'
                  AND em.entity_id=%s
                  AND em.deleted_at IS NULL
                  AND em.hidden_at IS NULL
                  AND em.is_primary=true
                  AND ma.kind=%s
                """,
                (container_id, kind),
            )
            make_primary = cur.fetchone() is None
        cur.execute(
            """
            INSERT INTO entity_media (
                entity_type,
                entity_id,
                media_id,
                role,
                is_primary,
                sort_order
            )
            VALUES ('container', %s, %s, %s, %s, %s)
            ON CONFLICT (entity_type, entity_id, media_id, role) DO UPDATE SET
                sort_order=LEAST(entity_media.sort_order, EXCLUDED.sort_order)
            """,
            (container_id, media_id, kind, make_primary, sort_order),
        )
    return {
        "kind": kind,
        "mediaId": str(media_id),
        "sourceUrl": source_url,
        "providerId": provider_id,
        "primary": make_primary,
    }


def link_local_media_asset_to_container(
    conn,
    *,
    container_id: UUID,
    kind: str,
    media_asset_id: UUID,
    provider_id: str,
    sort_order: int,
    primary: bool = False,
) -> dict[str, Any] | None:
    """Attach a locally-cached media asset (e.g. from the v4 poster cache) to a
    container's entity_media without going through ensure_remote_media_asset(),
    which only handles http/https source URLs.

    Mirrors the primary/ordering/conflict logic of link_container_media_option()
    but uses a known local media_asset_id directly.
    """
    if kind not in {"poster", "backdrop"}:
        return None
    if not table_exists(conn, "entity_media"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT is_primary, deleted_at
            FROM entity_media
            WHERE entity_type='container'
              AND entity_id=%s
              AND media_id=%s
              AND role=%s
            """,
            (container_id, media_asset_id, kind),
        )
        row = cur.fetchone()
        if row and (row["deleted_at"] if isinstance(row, dict) else row[1]):
            return None
        if row and bool(row["is_primary"] if isinstance(row, dict) else row[0]):
            return None
        make_primary = False
        if primary:
            cur.execute(
                """
                SELECT 1
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                WHERE em.entity_type='container'
                  AND em.entity_id=%s
                  AND em.deleted_at IS NULL
                  AND em.hidden_at IS NULL
                  AND em.is_primary=true
                  AND ma.kind=%s
                """,
                (container_id, kind),
            )
            make_primary = cur.fetchone() is None
        cur.execute(
            """
            INSERT INTO entity_media (
                entity_type,
                entity_id,
                media_id,
                role,
                is_primary,
                sort_order
            )
            VALUES ('container', %s, %s, %s, %s, %s)
            ON CONFLICT (entity_type, entity_id, media_id, role) DO UPDATE SET
                sort_order=LEAST(entity_media.sort_order, EXCLUDED.sort_order),
                deleted_at=NULL
            """,
            (container_id, media_asset_id, kind, make_primary, sort_order),
        )
    return {
        "kind": kind,
        "mediaId": str(media_asset_id),
        "providerId": provider_id,
        "primary": make_primary,
    }


def _find_v4_cached_poster_for_container(
    conn,
    *,
    barcode: str | None,
    movievault_id: str | None,
) -> dict[str, Any] | None:
    """Look up a ready v4 display poster for a box-set container.

    Searches movievault_v2_box_sets + movievault_v2_poster_cache using the
    container's barcode (SHA-256 hash join) or movievault_id identifier.
    Returns a dict with ``media_asset_id`` and ``asset_id`` when a ready
    cached display poster is found, else None.
    """
    if not barcode and not movievault_id:
        return None
    if not table_exists(conn, "movievault_v2_poster_cache") or not table_exists(conn, "movievault_v2_box_sets"):
        return None
    with conn.cursor() as cur:
        if barcode:
            cur.execute(
                """
                SELECT pc.media_asset_id, bs.poster->>'assetId' AS asset_id
                FROM movievault_v2_box_sets bs
                JOIN movievault_v2_lookup_hashes h
                    ON h.generation = bs.generation
                   AND h.entity_id = bs.box_set_id
                   AND h.entity_type = 'box_set'
                   AND h.source_type = 'box_set_ean'
                   AND h.lookup_hash = encode(digest(%s::text, 'sha256'), 'hex')
                JOIN movievault_v2_poster_cache pc
                    ON pc.asset_id = bs.poster->>'assetId'
                   AND pc.variant = 'display'
                   AND pc.checksum = bs.poster->'display'->>'checksum'
                   AND pc.status = 'ready'
                   AND pc.media_asset_id IS NOT NULL
                LIMIT 1
                """,
                (barcode,),
            )
            row = cur.fetchone()
            if row:
                media_asset_id = row["media_asset_id"] if isinstance(row, dict) else row[0]
                asset_id = row["asset_id"] if isinstance(row, dict) else row[1]
                if media_asset_id:
                    return {"media_asset_id": str(media_asset_id), "asset_id": str(asset_id) if asset_id else ""}
        if movievault_id:
            cur.execute(
                """
                SELECT pc.media_asset_id, bs.poster->>'assetId' AS asset_id
                FROM movievault_v2_box_sets bs
                JOIN movievault_v2_poster_cache pc
                    ON pc.asset_id = bs.poster->>'assetId'
                   AND pc.variant = 'display'
                   AND pc.checksum = bs.poster->'display'->>'checksum'
                   AND pc.status = 'ready'
                   AND pc.media_asset_id IS NOT NULL
                WHERE bs.box_set_id = %s
                LIMIT 1
                """,
                (movievault_id,),
            )
            row = cur.fetchone()
            if row:
                media_asset_id = row["media_asset_id"] if isinstance(row, dict) else row[0]
                asset_id = row["asset_id"] if isinstance(row, dict) else row[1]
                if media_asset_id:
                    return {"media_asset_id": str(media_asset_id), "asset_id": str(asset_id) if asset_id else ""}
    return None


def fetch_box_set_artwork_from_sources(
    conn,
    container: dict[str, Any],
    identifiers: list[dict[str, Any]] | None,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Pull the box-set's own poster/backdrop (and title/year) from sources.

    Calls each enabled ``box_set_candidates`` source (e.g. MovieVault) with the
    container's title/year/barcode/format and returns the artwork of the
    best-matching proposal. Matching prefers an exact barcode or MovieVault id
    match over a title match, so a refresh of *this* box-set never grabs another
    set's artwork. Returns an empty dict when nothing matches.
    """

    metadata = container.get("metadata") if isinstance(container.get("metadata"), dict) else {}
    barcode = clean_text(container.get("barcode")) or clean_text(metadata.get("barcode"))
    movievault_id = clean_text(
        metadata.get("movievault_id")
        or metadata.get("movieVaultId")
        or metadata.get("movievaultId")
    )
    for identifier in identifiers or []:
        provider = str(identifier.get("provider_id") or "").lower()
        if "movievault" in provider and clean_text(identifier.get("identifier")):
            movievault_id = movievault_id or clean_text(identifier.get("identifier"))

    # Check the v4 local poster cache first — if a ready display poster is
    # already cached for this box-set's barcode or MovieVault id, link it
    # directly and skip the external plugin call entirely.
    container_id_raw = container.get("id")
    if container_id_raw and (barcode or movievault_id):
        v4_poster = _find_v4_cached_poster_for_container(
            conn, barcode=barcode, movievault_id=movievault_id
        )
        if v4_poster:
            try:
                container_uuid = UUID(str(container_id_raw))
                media_asset_uuid = UUID(v4_poster["media_asset_id"])
                link_local_media_asset_to_container(
                    conn,
                    container_id=container_uuid,
                    kind="poster",
                    media_asset_id=media_asset_uuid,
                    provider_id="movievault_v2",
                    sort_order=0,
                    primary=True,
                )
            except (ValueError, TypeError):
                pass  # bad UUID — fall through to external plugin

    plugins = box_set_metadata_source_plugins(conn)
    if not plugins:
        return {}

    title = clean_text(container.get("title")) or clean_text(metadata.get("title"))
    if not title:
        return {}
    year = clean_text(container.get("year")) or clean_text(metadata.get("year"))
    fmt = clean_text(container.get("format")) or clean_text(metadata.get("format"))

    payload = {
        "title": title,
        "year": year,
        "barcode": barcode,
        "format": fmt,
        "mediaType": fmt,
    }
    if movievault_id:
        payload["movieVaultId"] = movievault_id
        payload["identity"] = movievault_id

    norm_title = re.sub(r"[^a-z0-9]+", "", title.lower()) if title else ""

    def _proposal_artwork(proposal: dict[str, Any], provider_id: str, score: int) -> dict[str, Any]:
        poster = clean_text(
            proposal.get("poster_url") or proposal.get("posterUrl") or proposal.get("poster")
        )
        backdrop = clean_text(
            proposal.get("backdrop_url") or proposal.get("backdropUrl") or proposal.get("backdrop")
        )
        backdrops = [
            clean_text(url)
            for url in (proposal.get("backdrop_urls") or proposal.get("backdropUrls") or [])
            if clean_text(url)
        ]
        return {
            "poster_url": poster,
            "backdrop_url": backdrop,
            "backdrop_urls": backdrops,
            "title": clean_text(proposal.get("title") or proposal.get("name")),
            "year": clean_text(proposal.get("year")),
            "provider_id": provider_id,
            "sourceRef": clean_text(
                proposal.get("movievault_id") or proposal.get("movieVaultId") or proposal.get("barcode")
            ),
            "_score": score,
        }

    best: dict[str, Any] = {}
    for plugin in plugins:
        plugin_id = str(plugin.get("id") or "")
        config = plugin_config_from_db(conn, plugin_id)
        if plugin_requires_config_for_entrypoint(plugin, config, "box_set_candidates"):
            continue
        context = plugin_execution_context(conn, plugin, config, actor, ensure_movievault_token=True)
        execution = run_plugin_entrypoint(plugin_id, "box_set_candidates", payload, context)
        if execution.get("status") != "ok":
            continue
        result = execution.get("result") or {}
        proposals = result.get("boxSetProposals")
        if not isinstance(proposals, list) or not proposals:
            single = result.get("boxSetProposal")
            proposals = [single] if isinstance(single, dict) and single else []
        for proposal in proposals:
            if not isinstance(proposal, dict):
                continue
            proposal_barcode = clean_text(proposal.get("barcode"))
            proposal_mv = clean_text(proposal.get("movievault_id") or proposal.get("movieVaultId"))
            proposal_title = re.sub(
                r"[^a-z0-9]+", "", clean_text(proposal.get("title") or proposal.get("name")).lower()
            )
            score = 0
            if barcode and proposal_barcode and proposal_barcode == barcode:
                score = 3
            elif movievault_id and proposal_mv and proposal_mv == movievault_id:
                score = 3
            elif norm_title and proposal_title and proposal_title == norm_title:
                score = 2
            elif norm_title and proposal_title and (norm_title in proposal_title or proposal_title in norm_title):
                score = 1
            # Require at least a fuzzy title (or stronger barcode/id) match so a
            # refresh never adopts an unrelated box-set's artwork.
            if score < 1:
                continue
            artwork = _proposal_artwork(proposal, plugin_id, score)
            if not artwork.get("poster_url") and not artwork.get("backdrop_url"):
                continue
            if score > best.get("_score", -1):
                best = artwork
    if best:
        best.pop("_score", None)
    return best


def refresh_container_metadata(
    conn,
    container_id: UUID,
    *,
    dry_run: bool,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    container = container_entity(conn, container_id)
    if not container:
        raise NextApiError("Container not found", 404)
    movies = container_aggregate_movie_entities(conn, container_id)
    assets = container_aggregate_media_asset_entities(conn, movies)
    videos = container_aggregate_video_entities(movies)
    summary = container_aggregate_summary(movies, assets, videos)
    metadata = container.get("metadata") if isinstance(container.get("metadata"), dict) else {}
    identifiers = container_identifier_entities(conn, container_id)
    box_set_artwork = fetch_box_set_artwork_from_sources(conn, container, identifiers, actor)
    description = clean_text(container.get("description"))
    generated_description = ""
    if summary.get("memberTitles"):
        titles = ", ".join(summary["memberTitles"][:8])
        suffix = "..." if len(summary["memberTitles"]) > 8 else ""
        generated_description = f"Contains {summary.get('movieCount', 0)} movies: {titles}{suffix}"

    metadata_updates = {
        "aggregate": summary,
        "videos": videos[:80],
    }
    # The box-set's own poster/backdrop fetched from a source (e.g. MovieVault)
    # always wins over artwork aggregated from member movies, but never over a
    # cover the container already owns or that the user locked.
    has_own_poster = bool(clean_text(metadata.get("poster_url"))) and not metadata.get("poster_from_members")
    has_own_backdrop = bool(clean_text(metadata.get("backdrop_url"))) and not metadata.get("backdrop_from_members")
    box_set_poster = clean_text(box_set_artwork.get("poster_url")) if box_set_artwork else ""
    box_set_backdrop = clean_text(box_set_artwork.get("backdrop_url")) if box_set_artwork else ""
    if box_set_poster and not metadata.get("poster_locked") and not has_own_poster:
        metadata_updates["poster_url"] = box_set_poster
        metadata_updates["poster_from_members"] = False
        has_own_poster = True
    if box_set_backdrop and not metadata.get("backdrop_locked") and not has_own_backdrop:
        metadata_updates["backdrop_url"] = box_set_backdrop
        metadata_updates["backdrop_from_members"] = False
        has_own_backdrop = True
    if assets:
        primary_poster = next((asset for asset in assets if asset.get("kind") == "poster"), None)
        primary_backdrop = next((asset for asset in assets if asset.get("kind") == "backdrop"), None)
        # Only derive artwork from member movies when the container has no cover of
        # its own. A box-set keeps its own poster/backdrop (e.g. from MovieVault) in
        # metadata; member artwork must never overwrite it. Artwork previously
        # aggregated from members is tagged so it can keep tracking member changes.
        if primary_poster and not metadata.get("poster_locked") and not has_own_poster:
            metadata_updates["poster_url"] = primary_poster.get("url")
            metadata_updates["poster_from_members"] = True
        if primary_backdrop and not metadata.get("backdrop_locked") and not has_own_backdrop:
            metadata_updates["backdrop_url"] = primary_backdrop.get("url")
            metadata_updates["backdrop_from_members"] = True

    proposal = {
        "containerId": str(container_id),
        "dryRun": dry_run,
        "movieCount": summary.get("movieCount", 0),
        "metadataUpdates": metadata_updates,
        "description": description or generated_description,
        "boxSetArtwork": box_set_artwork or {},
    }
    if dry_run:
        return {"dryRun": True, "changed": False, "proposal": proposal, "summary": summary}

    next_metadata = dict(metadata)
    next_metadata.update(metadata_updates)
    with conn.cursor() as cur:
        cur.execute(
            """
            UPDATE containers
            SET metadata=%s,
                description=COALESCE(NULLIF(description, ''), %s),
                updated_at=now()
            WHERE id=%s
            """,
            (Jsonb(json_ready(next_metadata)), generated_description or None, container_id),
        )
    if box_set_artwork:
        provider_id = clean_text(box_set_artwork.get("provider_id")) or "box_set"
        if box_set_poster:
            link_container_media_option(
                conn,
                container_id=container_id,
                kind="poster",
                source_url=box_set_poster,
                provider_id=provider_id,
                sort_order=0,
                primary=not metadata.get("poster_locked"),
            )
        backdrop_options = []
        if box_set_backdrop:
            backdrop_options.append(box_set_backdrop)
        for url in box_set_artwork.get("backdrop_urls") or []:
            url = clean_text(url)
            if url and url not in backdrop_options:
                backdrop_options.append(url)
        for index, url in enumerate(backdrop_options):
            link_container_media_option(
                conn,
                container_id=container_id,
                kind="backdrop",
                source_url=url,
                provider_id=provider_id,
                sort_order=index,
                primary=(index == 0) and not metadata.get("backdrop_locked"),
            )
    revision = 0
    if table_exists(conn, "sync_changes"):
        revision = next_revision(conn)
        sync_change(
            conn,
            revision=revision,
            entity_type="container",
            entity_id=str(container_id),
            operation="container.metadata_refresh",
            payload={
                "containerId": str(container_id),
                "summary": summary,
                "actor": actor_job_payload(actor or {}) if actor else None,
            },
        )
    return {"dryRun": False, "changed": True, "revision": revision, "applied": proposal, "summary": summary}


def container_metadata_debug_entity(conn, container_id: UUID | str) -> dict[str, Any] | None:
    """Build the metadata debug payload for a container/box-set.

    Containers don't fetch metadata per source the way movies do; instead a
    container refresh contributes the box-set to receiver plugins (e.g.
    MovieVault) via asynchronous ``plugin.execute``/``receive_metadata`` jobs.
    We reconstruct the "contributed metadata per plugin" view (with
    accepted/rejected fields) from the latest completed receiver jobs for this
    container, matched via the receiver payload's embedded ``containerId``.

    The "loaded metadata per source" view is aggregated from the box-set's
    member movies (each film's latest source-load), attributed per film, since
    a container has no source fetch of its own.
    """

    name_map: dict[str, str] = {}
    try:
        for plugin in metadata_receiver_plugins(conn):
            if isinstance(plugin, dict) and plugin.get("id"):
                name_map[str(plugin["id"])] = str(plugin.get("name") or plugin["id"])
    except Exception:  # pragma: no cover - plugin registry must never break debug
        name_map = {}

    rows: list[dict[str, Any]] = []
    if table_exists(conn, "background_jobs"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    id,
                    job_type,
                    status,
                    payload,
                    result,
                    error,
                    created_at,
                    finished_at
                FROM background_jobs
                WHERE job_type = %s
                  AND payload->>'entrypoint' = 'receive_metadata'
                  AND payload->'payload'->'metadata'->>'containerId' = %s
                ORDER BY created_at DESC
                LIMIT 40
                """,
                (PLUGIN_EXECUTION_JOB_TYPE, str(container_id)),
            )
            rows = cur.fetchall()

    contributed: list[dict[str, Any]] = []
    seen_plugins: set[str] = set()
    fetched_at: Any = None
    container_title: Any = None

    for row in rows:
        payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
        receiver_payload = payload.get("payload") if isinstance(payload.get("payload"), dict) else {}
        plugin_id = str(payload.get("pluginId") or "")
        if not plugin_id or plugin_id in seen_plugins:
            continue
        seen_plugins.add(plugin_id)

        if fetched_at is None:
            created = row.get("created_at")
            fetched_at = created.isoformat() if hasattr(created, "isoformat") else created
        if container_title is None:
            container_title = (receiver_payload.get("payload") or {}).get("title") if isinstance(receiver_payload.get("payload"), dict) else None

        contribution_fields = receiver_payload.get("payload") if isinstance(receiver_payload.get("payload"), dict) else {}
        payload_metadata = receiver_payload.get("metadata") if isinstance(receiver_payload.get("metadata"), dict) else {}
        source_providers = payload_metadata.get("sourceProviders") if isinstance(payload_metadata.get("sourceProviders"), list) else []

        result = row.get("result") if isinstance(row.get("result"), dict) else {}
        execution = result.get("execution") if isinstance(result.get("execution"), dict) else {}
        exec_result = execution.get("result") if isinstance(execution.get("result"), dict) else {}

        status = row.get("status")
        accepted_fields = exec_result.get("acceptedFields") if isinstance(exec_result.get("acceptedFields"), list) else []
        excluded_fields = [
            {"field": item.get("field"), "reason": item.get("reason")}
            for item in (exec_result.get("droppedFields") or [])
            if isinstance(item, dict) and item.get("field")
        ]

        contributed.append(
            {
                "pluginId": plugin_id,
                "name": name_map.get(plugin_id) or exec_result.get("provider") or plugin_id,
                "status": execution.get("status") or status,
                "state": execution.get("state") or status,
                "resultStatus": exec_result.get("status") or (status if status in {"pending", "running", "failed"} else None),
                "reason": exec_result.get("reason") or clean_text(row.get("error")) or None,
                "provider": exec_result.get("provider"),
                "error": execution.get("error") or clean_text(row.get("error")) or None,
                "templateVersion": exec_result.get("templateVersion"),
                "fields": sorted(str(key) for key in contribution_fields.keys()) if isinstance(contribution_fields, dict) else [],
                "acceptedFields": [str(field) for field in accepted_fields],
                "excludedFields": excluded_fields,
                "sourceProviders": source_providers,
            }
        )

    # "Loaded metadata per source" is aggregated from the box-set's member
    # movies (a container doesn't fetch from sources itself). Each member's
    # latest source-load is attributed to the film via sourceRef.
    fetched: list[dict[str, Any]] = []
    if table_exists(conn, "audit_events"):
        try:
            members = container_member_movie_entities(conn, container_id)
        except Exception:  # pragma: no cover - membership lookup must never break debug
            members = []
        for member in members[:60]:
            member_id = member.get("id")
            if not member_id:
                continue
            member_event = movie_metadata_debug_latest_audit_event(conn, member_id, "metadata.refresh_fetched")
            if not member_event:
                continue
            groups = metadata_debug_fetched_sources(member_event.get("metadata") or {})
            if not groups:
                continue
            member_title = clean_text(member.get("title")) or str(member_id)
            for group in groups:
                base_ref = clean_text(group.get("sourceRef"))
                group["sourceRef"] = f"{member_title} · {base_ref}" if base_ref else member_title
                fetched.append(group)
            if fetched_at is None:
                created = member_event.get("createdAt")
                fetched_at = created.isoformat() if hasattr(created, "isoformat") else created

    if not contributed and not fetched:
        return None

    missing_report = movie_metadata_missing_contribution_report(
        movie_id=container_id,
        title=container_title,
        fetched=fetched,
        contributed=contributed,
        generated_at=fetched_at,
        entity_kind="container",
    )

    return {
        "fetchedAt": fetched_at,
        "fetched": fetched,
        "contributed": contributed,
        "missingContributionReport": missing_report,
    }


def container_detail_entity(conn, container_id: UUID, actor: dict[str, Any] | None = None) -> dict[str, Any] | None:
    container = container_entity(conn, container_id)
    if not container:
        return None
    if isinstance(container, dict):
        primary_movie_id = container.get("primary_movie_id")
        owner_id = container.get("owner_id")
        container["primaryMovieId"] = str(primary_movie_id) if primary_movie_id else None
        container["ownerId"] = str(owner_id) if owner_id else None
    attach_location_summaries(conn, [container])
    aggregate_movies = container_aggregate_movie_entities(conn, container_id, actor=actor)
    aggregate_assets = container_aggregate_media_asset_entities(conn, aggregate_movies)
    aggregate_videos = container_aggregate_video_entities(aggregate_movies)
    metadata_debug = None
    try:
        metadata_debug = container_metadata_debug_entity(conn, container_id)
    except Exception:  # pragma: no cover - debug info must never break detail load
        metadata_debug = None
    return {
        "container": container,
        "identifiers": container_identifier_entities(conn, container_id),
        "memberMovies": container_member_movie_entities(conn, container_id, actor=actor),
        "collectionItems": collection_item_entities(conn, container_id, actor=actor),
        "mediaAssets": entity_media_asset_entities(conn, "container", container_id),
        "aggregateMovies": aggregate_movies,
        "aggregateMediaAssets": aggregate_assets,
        "aggregateVideos": aggregate_videos,
        "aggregateSummary": container_aggregate_summary(aggregate_movies, aggregate_assets, aggregate_videos),
        "metadataDebug": metadata_debug,
        "actions": {
            "canConvert": actor_can_convert_container(container, actor),
        },
    }


def series_identifier_entities(conn, series_id: UUID) -> list[dict[str, Any]]:
    if not table_exists(conn, "series_identifiers"):
        return []
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT provider_id, identifier_type, identifier, created_at
            FROM series_identifiers
            WHERE series_id=%s
            ORDER BY provider_id, identifier_type, identifier
            """,
            (series_id,),
        )
        return cur.fetchall()


def series_disc_entities(conn, series_id: UUID, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """The discs filed under this series, in the same shape a container's members take.

    Deliberately the same columns as `container_member_movie_entities`: the discs
    tab renders with the movie card helpers, and a second, slightly different row
    shape would mean a second set of renderers to keep in step.

    Ordered by title rather than by an explicit sort order, because a series has
    no curated member order to preserve -- `container_movies.sort_order` has no
    equivalent here, and the season each disc covers is the ordering a reader
    actually wants (which the discs tab shows per row).
    """
    if not table_exists(conn, "movies"):
        return []
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                m.id,
                m.public_id,
                m.barcode,
                m.title,
                m.sort_title,
                m.original_title,
                m.year,
                m.release_date,
                m.format,
                m.media_type,
                m.edition,
                m.edition_type,
                m.country,
                m.language,
                m.runtime_minutes,
                m.overview,
                m.rating,
                m.metadata,
                m.created_at,
                m.updated_at,
                m.metadata->>'poster_url' AS poster_url,
                m.metadata->>'backdrop_url' AS backdrop_url
            FROM movies m
            WHERE m.series_id=%s
              AND {visibility_where}
            ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
            """,
            (series_id, *visibility_params),
        )
        return cur.fetchall()


def series_detail_entity(
    conn, series_id: UUID, actor: dict[str, Any] | None = None
) -> dict[str, Any] | None:
    """Everything the series page shows, in one read.

    Modelled on `container_detail_entity`, with one deliberate difference: a
    series owns almost nothing. It has no artwork of its own until somebody
    uploads one and no videos at all, because a video is a `movies.metadata`
    fact and there is no series-shaped source for one.

    So the artwork and video tabs are filled by aggregation from the discs, using
    the very helpers the container page uses -- both of them take a plain list of
    movies rather than a container, so nothing had to be generalised. An
    inherited asset arrives labelled with the disc it came from, which is what
    keeps "the series' poster" from quietly meaning "some disc's poster".
    """
    series = series_entity(conn, series_id)
    if not series:
        return None
    discs = series_disc_entities(conn, series_id, actor=actor)
    aggregate_assets = container_aggregate_media_asset_entities(conn, discs)
    aggregate_videos = container_aggregate_video_entities(discs)
    own_assets = entity_media_asset_entities(conn, "series", series_id)
    coverage = [
        row
        for row in collection_series_membership_entities(conn, actor=actor)
        if row.get("movieId") in {str(disc.get("id")) for disc in discs}
    ]
    return {
        "series": series,
        "identifiers": series_identifier_entities(conn, series_id),
        "discs": discs,
        "seasonCoverage": coverage,
        "mediaAssets": own_assets,
        "aggregateMovies": discs,
        "aggregateMediaAssets": aggregate_assets,
        "aggregateVideos": aggregate_videos,
        "aggregateSummary": container_aggregate_summary(discs, aggregate_assets, aggregate_videos),
    }


def all_movie_entities(conn, *, limit: int = 1000, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "movies"):
        return []
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    select_columns = _movie_select_columns(_MOVIE_SYNC_COLUMNS, prefix="m")
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                {select_columns}
            FROM movies m
            WHERE {visibility_where} AND m.deleted_at IS NULL
            ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
            LIMIT %s
            """,
            (*visibility_params, limit),
        )
        return attach_movie_discs(
            conn,
            attach_movie_seasons(
                conn, attach_movie_technical_specs(conn, attach_movie_genres(conn, cur.fetchall()))
            ),
        )


def all_movie_credit_entities(
    conn,
    *,
    movie_limit: int = 1000,
    credit_limit: int = 50000,
    actor: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not table_exists(conn, "movies") or not table_exists(conn, "movie_credits") or not table_exists(conn, "people"):
        return []
    movie_limit = max(1, min(int(movie_limit or 1000), 5000))
    credit_limit = max(1, min(int(credit_limit or 50000), 50000))
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    media_join = table_exists(conn, "media_assets")
    identifiers_join = table_exists(conn, "person_identifiers")
    profile_select = (
        """
                ma.storage_backend AS profile_storage_backend,
                ma.storage_key AS profile_storage_key,
                ma.source_url AS profile_source_url,
        """
        if media_join
        else """
                NULL AS profile_storage_backend,
                NULL AS profile_storage_key,
                NULL AS profile_source_url,
        """
    )
    profile_join = "LEFT JOIN media_assets ma ON ma.id = p.profile_asset_id" if media_join else ""
    tmdb_select = (
        """
                (
                    SELECT pi.identifier
                    FROM person_identifiers pi
                    WHERE pi.person_id = p.id
                      AND lower(pi.provider_id) = 'tmdb'
                    ORDER BY pi.identifier_type, pi.identifier
                    LIMIT 1
                ) AS tmdb_id,
        """
        if identifiers_join
        else "NULL AS tmdb_id,"
    )
    with conn.cursor() as cur:
        cur.execute(
            f"""
            WITH bootstrap_movies AS (
                SELECT m.id, lower(COALESCE(m.sort_title, m.title)) AS order_title, m.year
                FROM movies m
                WHERE {visibility_where} AND m.deleted_at IS NULL
                ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                LIMIT %s
            )
            SELECT
                mc.id,
                mc.movie_id,
                mc.person_id,
                mc.credit_type,
                mc.character,
                mc.job,
                mc.sort_order,
                p.public_id AS person_public_id,
                p.name,
                p.known_for,
                p.profile_asset_id,
                p.metadata AS person_metadata,
{profile_select}
{tmdb_select}
                bm.order_title,
                bm.year AS movie_year
            FROM movie_credits mc
            JOIN bootstrap_movies bm ON bm.id = mc.movie_id
            JOIN people p ON p.id = mc.person_id
            {profile_join}
            ORDER BY bm.order_title, bm.year NULLS LAST, mc.movie_id, mc.sort_order, p.name
            LIMIT %s
            """,
            (*visibility_params, movie_limit, credit_limit),
        )
        rows = [dict(row) for row in cur.fetchall()]
    items: list[dict[str, Any]] = []
    for row in rows:
        metadata = row.get("person_metadata") if isinstance(row.get("person_metadata"), dict) else {}
        profile_url = media_asset_public_url(
            {
                "id": row.get("profile_asset_id"),
                "storage_backend": row.pop("profile_storage_backend", None),
                "storage_key": row.pop("profile_storage_key", None),
                "source_url": row.pop("profile_source_url", None),
            }
        )
        if not profile_url:
            profile_url = profile_metadata_image_url(metadata)
        credit_type = clean_text(row.get("credit_type"))
        acting = person_credit_type_is_acting({"credit_type": credit_type})
        items.append(
            {
                "id": str(row.get("id") or ""),
                "creditId": str(row.get("id") or ""),
                "movieId": str(row.get("movie_id") or ""),
                "personId": str(row.get("person_id") or ""),
                "personPublicId": clean_text(row.get("person_public_id")),
                "tmdbId": clean_text(row.get("tmdb_id") or metadata.get("tmdbId") or metadata.get("tmdb_id")),
                "name": clean_text(row.get("name")),
                "profileUrl": clean_text(profile_url),
                "knownFor": clean_text(row.get("known_for") or metadata.get("knownFor") or metadata.get("known_for")),
                "creditType": credit_type,
                "department": "cast" if acting else "crew",
                "character": clean_text(row.get("character")),
                "job": clean_text(row.get("job")),
                "sortOrder": int(row.get("sort_order") or 0),
            }
        )
    return items


