class SyncBatchContext:
    """Per-request state that keeps batched brand-new creates from collapsing.

    A single ``POST /api/next/sync/mutations`` batch can contain several
    ``movie.upsert`` mutations that are all fresh creates (``entityId`` is null),
    e.g. the members of a box set added in one go. Two things used to silently
    collapse such a batch into a single surviving row:

    - a duplicate (non-empty) ``clientEntityId`` shared across the creates made
      every mutation resolve to the same UUID, so ``ON CONFLICT (id) DO UPDATE``
      overwrote the one row (last title wins);
    - members carrying the same barcode collided on the ``movies.barcode`` UNIQUE
      constraint, rolling back every create after the first.

    This context tracks what has already been claimed within the current batch so
    each create becomes a distinct movie and a shared barcode is healed instead of
    blocking the insert.
    """

    def __init__(self) -> None:
        self.consumed_client_entity_ids: set[str] = set()
        self.claimed_barcodes: set[str] = set()
        # Persistent per-record clientId -> server id created earlier in this
        # same batch, so the same clientId twice in one batch collapses to one
        # record (the second mutation reports created=false).
        self.claimed_client_ids: dict[str, UUID] = {}
        # Who is pushing this batch. Carried on the context rather than
        # threaded through every apply_* signature: the batch is the unit the
        # route authenticates, so this is where the answer already lives.
        # Without it a synced edit records a device and no person.
        self.actor: dict[str, Any] | None = None


#: How many entries the change history returns by default. Ten is what a person
#: can read at a glance while still covering "what happened to this record
#: recently", which is the question it exists to answer.
MOVIE_HISTORY_DEFAULT_LIMIT = 10
MOVIE_HISTORY_MAX_LIMIT = 100

#: Audit events that describe a change *to the record itself*. Deliberately not
#: every event carrying this movie as its target: a poster upload or a metadata
#: refresh attempt is activity about the film, not an edit of its fields, and
#: mixing the two makes the ten most recent entries stop answering the question.
MOVIE_HISTORY_EVENT_TYPES = (
    "movie.updated",
    "movie.identifier_added",
    "movie.identifier_removed",
    "movie.product_identifiers_changed",
    "movie.imported",
)


#: Bookkeeping that moves on every write and describes no edit anybody made.
#: `revision` and the timestamps change whether or not a field did, and
#: reporting them would make every history row claim a change to everything.
_MOVIE_CHANGE_IGNORED_KEYS = frozenset(
    {"id", "public_id", "created_at", "updated_at", "revision", "sync_revision"}
)


def changed_movie_fields(before: dict[str, Any] | None, after: dict[str, Any] | None) -> list[str]:
    """Which fields an edit actually moved.

    Compared on the whole movie entity rather than on the request body, because
    the body is not where the answer is: `movie_entity` carries the technical
    profile flattened into the same dict and the discs under `discs`, so an edit
    that touched nothing but one disc's audio tracks shows up here and shows up
    nowhere in the movie's own columns. Diffing the body would have reported
    that edit as a change to nothing -- which is exactly how it read before.
    """
    before = before or {}
    after = after or {}
    keys = (set(before) | set(after)) - _MOVIE_CHANGE_IGNORED_KEYS
    return sorted(key for key in keys if before.get(key) != after.get(key))


def movie_change_history(conn, movie_id: UUID | str, limit: int = MOVIE_HISTORY_DEFAULT_LIMIT):
    """Who changed this film, most recent first.

    Two sources, because DiscVault records the two kinds of change in two
    different places and neither alone answers the question:

    - `audit_events` holds what a *person or a device* did, with the actor, the
      client's user agent and (for a sync push) the client id;
    - `metadata_field_provenance` holds what a *plugin* supplied, per field,
      with the plugin id and its source reference.

    A value that changed underneath somebody is in one or the other, and until
    both were readable the honest answer to "who did this" was "look in the
    database". Merged and sorted here rather than in the client so every
    surface -- PWA, iOS, Android -- gets the same answer in the same order.

    Timestamps are returned as ISO 8601 with an offset and never pre-formatted.
    The device knows its own timezone and the server does not; formatting here
    would bake the server's zone into a value the reader then mis-reads by
    however many hours they are away from it.
    """
    limit = max(1, min(int(limit or MOVIE_HISTORY_DEFAULT_LIMIT), MOVIE_HISTORY_MAX_LIMIT))
    entries: list[dict[str, Any]] = []
    if table_exists(conn, "audit_events"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT created_at, event_type, actor_username, actor_role,
                       summary, metadata, user_agent
                FROM audit_events
                WHERE target_type = 'movie'
                  AND target_id = %s
                  AND event_type = ANY(%s)
                ORDER BY created_at DESC
                LIMIT %s
                """,
                (str(movie_id), list(MOVIE_HISTORY_EVENT_TYPES), limit),
            )
            for row in cur.fetchall():
                item = dict(row)
                metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
                entries.append(
                    {
                        "_at": item["created_at"],
                        "at": item["created_at"].isoformat(),
                        "event": item.get("event_type"),
                        "actor": clean_text(item.get("actor_username")) or None,
                        "actorRole": clean_text(item.get("actor_role")) or None,
                        "source": movie_history_source(item.get("event_type"), metadata, item.get("user_agent")),
                        "clientId": clean_text(metadata.get("clientId")) or None,
                        "fields": sorted(metadata.get("changedFields") or []) or None,
                        "summary": clean_text(item.get("summary")) or None,
                    }
                )
    if table_exists(conn, "metadata_field_provenance"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT captured_at, field_name, plugin_id, source_ref
                FROM metadata_field_provenance
                WHERE entity_type = 'movie' AND entity_id = %s
                ORDER BY captured_at DESC
                LIMIT %s
                """,
                (str(movie_id), limit),
            )
            for row in cur.fetchall():
                item = dict(row)
                entries.append(
                    {
                        "_at": item["captured_at"],
                        "at": item["captured_at"].isoformat(),
                        "event": "metadata.field_written",
                        "actor": None,
                        "actorRole": None,
                        "source": "plugin",
                        "plugin": clean_text(item.get("plugin_id")) or None,
                        "sourceRef": clean_text(item.get("source_ref")) or None,
                        "fields": [clean_text(item.get("field_name"))],
                    }
                )
    # Sorted on the datetime, not on the rendered string: the two queries can
    # in principle return the same instant with different offsets, and text
    # ordering would then put a later moment first purely because of its zone.
    entries.sort(key=lambda entry: entry["_at"], reverse=True)
    return [{key: value for key, value in entry.items() if key != "_at"} for entry in entries[:limit]]


def movie_history_source(event_type: Any, metadata: dict[str, Any], user_agent: Any) -> str:
    """Which surface the change came through.

    `source` is stated by the sync path itself; everything else is inferred
    from the user agent, and only coarsely. A user agent is a claim by the
    client rather than a fact, so this answers "which app says it did this"
    -- enough to tell an iPhone from a browser, not enough to be evidence.
    """
    if clean_text(metadata.get("source")) == "sync":
        agent = (clean_text(user_agent) or "").lower()
        if "discvault-ios" in agent or "cfnetwork" in agent or "darwin" in agent:
            return "ios"
        if "discvault-android" in agent or "okhttp" in agent or "android" in agent:
            return "android"
        return "sync"
    return "web"


def movie_id_for_barcode(conn, barcode: str | None) -> UUID | None:
    """Return the id of the movie that currently owns ``barcode`` (or None)."""
    if not barcode:
        return None
    with conn.cursor() as cur:
        cur.execute("SELECT id FROM movies WHERE barcode=%s", (barcode,))
        row = cur.fetchone()
    return row["id"] if row else None


def clamp_disc_count(value: Any) -> int | None:
    """A disc count, or None when nobody said.

    None rather than 1 for anything unreadable: `movies.disc_count` is nullable
    precisely so "nobody answered" stays distinct from "one disc", and a
    silently defaulted 1 would be proposed to MovieVault as a fact about a
    record nobody has looked at.

    Bounded 1..999 to match `ReleaseSummary.discCount`, so a value DiscVault
    accepts is never one MovieVault refuses.
    """
    if value is None or isinstance(value, bool):
        return None
    try:
        count = int(str(value).strip())
    except (TypeError, ValueError):
        return None
    return count if 1 <= count <= 999 else None


def normalize_barcode(barcode: str | None) -> str | None:
    """Digits-only comparison key for a barcode/EAN (leading zeros preserved).

    Used only for MATCH comparisons in the dedup ladder; barcodes are still
    stored verbatim so the import/unique paths are untouched.
    """
    if not barcode:
        return None
    digits = re.sub(r"\D", "", str(barcode))
    return digits or None


def _barcode_conflicts(incoming_barcode: Any, candidate_barcode: Any) -> bool:
    incoming = normalize_barcode(clean_text(incoming_barcode))
    candidate = normalize_barcode(clean_text(candidate_barcode))
    return bool(incoming and candidate and incoming != candidate)


def _year_key(value: Any) -> str | None:
    text = clean_text(value)
    return text or None


def find_movie_by_client_id(conn, client_id: str | None) -> UUID | None:
    """Trede 1: a live movie already carrying this persistent clientId.

    Deliberately exempt from the media-type veto (sync-contract.md §2). A shared
    per-record token identifies the same record with certainty -- a barcode
    conflict does not veto this tier either. A type disagreement on one token
    means the user retyped that record, not that there are two records.
    """
    if not client_id:
        return None
    with conn.cursor() as cur:
        cur.execute(
            "SELECT id FROM movies WHERE client_id=%s AND deleted_at IS NULL",
            (client_id,),
        )
        row = cur.fetchone()
    return row["id"] if row else None


def find_movie_by_barcode_match(
    conn,
    barcode: str | None,
    *,
    incoming_media_type: Any = None,
) -> UUID | None:
    """Trede 2: a live movie whose barcode matches (digits-only, tombstones excluded).

    A media-type conflict vetoes the match (sync-contract.md §2): a film and a
    series that happen to share a box EAN are two different works. Hence the scan
    over candidates instead of the older ``LIMIT 1`` -- a conflicting first row
    must not hide a legitimate match behind it.

    The scan is only needed when there is something to veto *with*. A client that
    states no type -- which is every client shipped before this contract version,
    so also the common case -- can never conflict, so it takes the single-row
    query instead of paging in every candidate to accept the first one anyway.

    Deliberately not narrowed with an ``AND media_type = %s`` in SQL: filtering
    the conflicting rows out would make this return some *other* barcode holder
    rather than block the match, which is the opposite of a veto.
    """
    normalized = normalize_barcode(barcode)
    if not normalized:
        return None
    can_conflict = normalize_media_type(incoming_media_type) is not None
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT id, media_type
            FROM movies
            WHERE deleted_at IS NULL
              AND barcode IS NOT NULL
              AND regexp_replace(barcode, '\\D', '', 'g') = %s
            ORDER BY created_at
            {"" if can_conflict else "LIMIT 1"}
            """,
            (normalized,),
        )
        rows = cur.fetchall()
    for row in rows:
        if media_type_conflicts(incoming_media_type, row.get("media_type")):
            continue
        return row["id"]
    return None


def find_movie_by_tmdb_edition(
    conn,
    *,
    tmdb_id: str | None,
    fmt: str | None,
    edition: str | None,
    incoming_title: str | None = None,
    incoming_year: Any = None,
    incoming_barcode: Any = None,
    incoming_media_type: Any = None,
) -> UUID | None:
    """Trede 3: same TMDB id AND physical format AND edition (all three).

    Over-merge protection:
    - format must normalize equal on both sides (4K_UHD == 4K UHD),
    - both barcodes present but different is a hard mismatch,
    - both media types present but different is a hard mismatch,
    - materially different title/year never matches on tmdb alone.
    """
    format_key = physical_media_format_key(fmt)
    if not tmdb_id or not format_key:
        return None
    if not table_exists(conn, "movie_identifiers"):
        return None
    incoming_title_key = normalize_title(incoming_title)
    incoming_year_key = _year_key(incoming_year)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT m.id, m.title, m.year, m.barcode, m.format, m.media_type
            FROM movies m
            JOIN movie_identifiers mi ON mi.movie_id = m.id
            WHERE m.deleted_at IS NULL
              AND lower(mi.provider_id) = 'tmdb'
              AND mi.identifier_type = 'movie_id'
              AND mi.identifier = %s
              AND lower(coalesce(m.edition, '')) = lower(coalesce(%s, ''))
            ORDER BY m.created_at
            """,
            (str(tmdb_id), edition),
        )
        rows = cur.fetchall()
    for row in rows:
        if physical_media_format_key(row.get("format")) != format_key:
            continue
        if _barcode_conflicts(incoming_barcode, row.get("barcode")):
            continue
        if media_type_conflicts(incoming_media_type, row.get("media_type")):
            continue
        candidate_title_key = normalize_title(row.get("title"))
        if incoming_title_key and candidate_title_key and incoming_title_key != candidate_title_key:
            continue
        candidate_year_key = _year_key(row.get("year"))
        if incoming_year_key and candidate_year_key and incoming_year_key != candidate_year_key:
            continue
        return row["id"]
    return None


def parse_client_timestamp(value: Any) -> datetime | None:
    """Best-effort parse of a client-supplied ISO-8601 timestamp (tz-aware).

    Used to decide, on a re-pushed create, whether the client's edit is newer
    than a server-side tombstone (legitimate resurrection) or older (delete wins).
    """
    text = clean_text(value)
    if not text:
        return None
    raw = text.strip()
    if raw.endswith("Z"):
        raw = raw[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(raw)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed


def find_tombstoned_movie_by_identity(
    conn,
    *,
    persistent_client_id: str | None,
    barcode: str | None,
) -> dict[str, Any] | None:
    """Return a *tombstoned* movie matching the incoming record's clientId
    (preferred) or barcode, plus how it matched, so an old client replaying a
    create cannot resurrect a record deleted elsewhere (onderzoek H4)."""
    if persistent_client_id:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, deleted_at, client_id
                FROM movies
                WHERE client_id=%s AND deleted_at IS NOT NULL
                ORDER BY deleted_at DESC
                LIMIT 1
                """,
                (persistent_client_id,),
            )
            row = cur.fetchone()
        if row:
            row["matched_by"] = "clientId"
            return row
    normalized = normalize_barcode(barcode)
    if normalized:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, deleted_at, client_id
                FROM movies
                WHERE deleted_at IS NOT NULL
                  AND barcode IS NOT NULL
                  AND regexp_replace(barcode, '\\D', '', 'g') = %s
                ORDER BY deleted_at DESC
                LIMIT 1
                """,
                (normalized,),
            )
            row = cur.fetchone()
        if row:
            row["matched_by"] = "barcode"
            return row
    return None


def tombstoned_movie_upsert_result(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
    client_entity_id: str | None,
    tombstone: dict[str, Any],
    matched_by: str | None,
    persistent_client_id: str | None,
) -> dict[str, Any]:
    entity_id = tombstone["id"]
    store_client_entity_mapping(
        conn,
        client_id=client_id,
        client_entity_id=client_entity_id,
        entity_type="movie",
        entity_id=entity_id,
        idem_key=idem_key,
    )
    entity = movie_entity(conn, entity_id) or {}
    deleted_at = entity.get("deleted_at") or tombstone.get("deleted_at")
    revision = next_revision(conn)
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "movie",
        "operation": "upsert",
        "entityId": entity_id,
        "clientEntityId": client_entity_id,
        "revision": revision,
        "entity": entity,
        "created": False,
        "matchedBy": matched_by,
        "recordClientId": tombstone.get("client_id") or persistent_client_id,
        "deleted": True,
        "deletedAt": deleted_at,
        "tombstoned": True,
    }


def match_existing_movie(
    *,
    persistent_client_id: str | None,
    batch_claimed_client_id: UUID | None,
    barcode_normalized: str | None,
    barcode_claimed_in_batch: bool,
    tmdb_id: str | None,
    fmt: str | None,
    duplicate_copy: bool,
    find_by_client_id,
    find_by_barcode,
    find_by_tmdb_edition,
) -> tuple[UUID | None, str | None]:
    """Apply the create-path identity ladder and return ``(movie_id, matchedBy)``.

    Strict order within the shared catalogue:

    1. ``clientId`` — the same persistent per-record UUID, either created earlier
       in this batch (``batch_claimed_client_id``) or already on a live movie.
    2. barcode/EAN — exact digits-only match against a live movie, *unless* the
       barcode was already claimed by an earlier create in this batch (a box-set
       member sharing the container EAN, which must stay a distinct row).
    3. TMDB id + format + edition — all three must match (over-merge protection).

    Trede 4 (title+year) is deliberately absent here; it is only active in the
    first-connect ``/sync/reconcile`` adoption path.

    ``duplicate_copy`` short-circuits the whole ladder. It used to suppress only
    tier 2, which made the flag a no-op in the case it exists for: two copies of
    one edition share their tmdb id, format and edition by definition, so tier 3
    matched them right back together and the client's deliberate "add anyway"
    silently undid itself on the next sync. An explicit second physical copy is a
    new record on every tier — including tier 1, which cannot legitimately fire
    here either: tokens are never copied (contract §6), so a second copy always
    arrives carrying a fresh one.
    """
    if duplicate_copy:
        return None, None
    if persistent_client_id and batch_claimed_client_id is not None:
        return batch_claimed_client_id, "clientId"
    if persistent_client_id:
        found = find_by_client_id()
        if found is not None:
            return found, "clientId"
    if barcode_normalized and not barcode_claimed_in_batch:
        found = find_by_barcode()
        if found is not None:
            return found, "barcode"
    if tmdb_id and fmt:
        found = find_by_tmdb_edition()
        if found is not None:
            return found, "tmdbEdition"
    return None, None


_TITLE_ARTICLES = {"the"}


def normalize_title(title: str | None) -> str | None:
    """Normalize a title for last-resort title+year matching.

    Lowercase, fold diacritics, strip punctuation, drop a leading English
    article ("the"), and collapse whitespace. Kept intentionally conservative
    for cross-client ladder parity: false negatives are safer than false
    positives, and titles like "Die Hard" / "De Aanslag" must not lose their
    first word.
    """
    text = clean_text(title)
    if not text:
        return None
    folded = unicodedata.normalize("NFKD", text)
    folded = "".join(ch for ch in folded if not unicodedata.combining(ch))
    folded = folded.lower()
    folded = re.sub(r"[^a-z0-9]+", " ", folded).strip()
    if not folded:
        return None
    parts = folded.split()
    if len(parts) > 1 and parts[0] in _TITLE_ARTICLES:
        parts = parts[1:]
    return " ".join(parts) or None


def find_movie_by_title_year(
    conn,
    *,
    title: str | None,
    year: Any,
    fmt: str | None,
    incoming_barcode: Any = None,
    incoming_edition: Any = None,
    incoming_container_ids: list[Any] | tuple[Any, ...] | None = None,
    incoming_media_type: Any = None,
) -> UUID | None:
    """Trede 4 (adoption-only): normalized title + exact year + matching format.

    Over-merge protection: the format must be present and equal on both sides, so
    a DVD and a 4K UHD of the same film never collapse. If the incoming record has
    no format we refuse to match (per contract 1.3) and let the caller create.

    This is the tier the media-type veto exists for: a film and a series sharing a
    title and a year (Fargo 1996/2014, Westworld 1973/2016) are otherwise a firm
    match here.
    """
    normalized = normalize_title(title)
    year_text = clean_text(year)
    format_key = physical_media_format_key(fmt)
    if not normalized or not year_text or not format_key:
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT m.id, m.title, m.year, m.barcode, m.format, m.edition, m.media_type,
                   ARRAY(
                       SELECT cm.container_id::text
                       FROM container_movies cm
                       WHERE cm.movie_id = m.id
                       ORDER BY cm.container_id
                   ) AS container_ids
            FROM movies m
            WHERE m.deleted_at IS NULL
              AND m.year = %s
            ORDER BY m.created_at
            """,
            (year_text,),
        )
        rows = cur.fetchall()
    for row in rows:
        if physical_media_format_key(row.get("format")) != format_key:
            continue
        if _barcode_conflicts(incoming_barcode, row.get("barcode")):
            continue
        if media_type_conflicts(incoming_media_type, row.get("media_type")):
            continue
        if not title_year_identity_compatible(
            left_edition=incoming_edition,
            right_edition=row.get("edition"),
            left_container_ids=incoming_container_ids,
            right_container_ids=row.get("container_ids"),
        ):
            continue
        if normalize_title(row.get("title")) == normalized:
            return row["id"]
    return None


def match_reconcile_item(
    *,
    persistent_client_id: str | None,
    barcode_normalized: str | None,
    tmdb_id: str | None,
    fmt: str | None,
    title: str | None,
    year: Any,
    find_by_client_id,
    find_by_barcode,
    find_by_tmdb_edition,
    find_by_title_year,
) -> tuple[UUID | None, str | None]:
    """First-connect adoption ladder (clientId → barcode → tmdbEdition → titleYear).

    Read-only: never claims batch state and never creates. The title+year tier is
    active here and *only* here, matching the contract's restriction of the
    fuzziest tier to the adoption path.
    """
    if persistent_client_id:
        found = find_by_client_id()
        if found is not None:
            return found, "clientId"
    if barcode_normalized:
        found = find_by_barcode()
        if found is not None:
            return found, "barcode"
    if tmdb_id and fmt:
        found = find_by_tmdb_edition()
        if found is not None:
            return found, "tmdbEdition"
    if title and year and fmt:
        found = find_by_title_year()
        if found is not None:
            return found, "titleYear"
    return None, None


def resolve_new_movie_identity(
    *,
    entity_id: UUID | None,
    client_entity_id: str | None,
    barcode: str | None,
    batch_ctx: "SyncBatchContext | None",
    lookup_mapping,
    barcode_owner_lookup,
) -> tuple[UUID, str | None]:
    """Decide a movie upsert's id and its (possibly healed) barcode.

    For updates (``entity_id`` provided) this is a passthrough. For brand-new
    creates it auto-heals batched creates:

    - a duplicate/missing ``clientEntityId`` still yields a distinct movie
      (the mapping is only consulted the first time a ``clientEntityId`` is seen
      in the batch, so cross-batch temp-id resolution keeps working while
      within-batch duplicates each get a fresh UUID);
    - a barcode already owned by another movie (in the DB or earlier in this
      batch) is dropped to null — the barcode belongs to the container, not each
      member — instead of raising a UNIQUE violation.
    """
    if entity_id is not None:
        return entity_id, barcode

    resolved: UUID | None = None
    already_consumed = bool(
        client_entity_id
        and batch_ctx is not None
        and client_entity_id in batch_ctx.consumed_client_entity_ids
    )
    if client_entity_id and not already_consumed:
        resolved = lookup_mapping()
    if resolved is None:
        resolved = uuid.uuid4()
    if client_entity_id and batch_ctx is not None:
        batch_ctx.consumed_client_entity_ids.add(client_entity_id)

    healed_barcode = barcode
    if barcode:
        collides = False
        if batch_ctx is not None and barcode in batch_ctx.claimed_barcodes:
            collides = True
        else:
            owner = barcode_owner_lookup(barcode)
            if owner is not None and owner != resolved:
                collides = True
        if collides:
            healed_barcode = None
        elif batch_ctx is not None:
            batch_ctx.claimed_barcodes.add(barcode)

    return resolved, healed_barcode


def apply_movie_upsert(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
    batch_ctx: "SyncBatchContext | None" = None,
) -> dict[str, Any]:
    payload = mutation.get("payload")
    if not isinstance(payload, dict):
        raise NextApiError("Movie upsert payload must be an object", 400)
    # Folded in before anything reads the payload, so every writer below sees an
    # ordinary explicit empty value and none of them learns a second way to be
    # told "clear this" -- sync-contract §4.10.
    payload = movie_clears(mutation, payload)

    client_entity_id = str(mutation.get("clientEntityId") or "").strip() or None
    provided_entity_id = parse_uuid(mutation.get("entityId"), "entityId")
    fields = movie_payload_fields(payload)

    # Persistent per-record identity fields (contract Deel 1). These are distinct
    # from the throwaway clientEntityId/clientMutationId: client_id is a stable
    # UUID minted once at record creation and reused across devices/retries.
    persistent_client_id = clean_text(payload.get("client_id"))
    metadata_payload = fields["metadata"] if isinstance(fields.get("metadata"), dict) else {}
    tmdb_id = clean_text(metadata_payload.get("tmdb_id"))
    duplicate_copy = bool(payload.get("duplicate_copy"))

    if provided_entity_id is not None:
        provided_entity = movie_entity(conn, provided_entity_id)
        if provided_entity and provided_entity.get("deleted_at") is not None:
            return tombstoned_movie_upsert_result(
                conn,
                client_id=client_id,
                idem_key=idem_key,
                mutation=mutation,
                client_entity_id=client_entity_id,
                tombstone=provided_entity,
                matched_by=None,
                persistent_client_id=persistent_client_id,
            )

    matched_by: str | None = None
    ladder_entity_id: UUID | None = None
    resurrect_tombstone = False
    if batch_ctx is not None and provided_entity_id is None:
        # Only run the dedup ladder for genuinely new records. A record already
        # mapped via clientEntityId is a normal idempotent device re-push and
        # must stay an update (matchedBy null), not a fresh match.
        mapped_existing = (
            client_entity_mapping(
                conn,
                client_id=client_id,
                entity_type="movie",
                client_entity_id=client_entity_id,
            )
            if client_entity_id
            else None
        )
        if mapped_existing is None:
            barcode_norm = normalize_barcode(fields["barcode"])
            barcode_claimed = bool(barcode_norm) and any(
                normalize_barcode(code) == barcode_norm
                for code in batch_ctx.claimed_barcodes
            )
            batch_claimed_cid = (
                batch_ctx.claimed_client_ids.get(persistent_client_id)
                if persistent_client_id
                else None
            )
            ladder_entity_id, matched_by = match_existing_movie(
                persistent_client_id=persistent_client_id,
                batch_claimed_client_id=batch_claimed_cid,
                barcode_normalized=barcode_norm,
                barcode_claimed_in_batch=barcode_claimed,
                tmdb_id=tmdb_id,
                fmt=fields["format"],
                duplicate_copy=duplicate_copy,
                find_by_client_id=lambda: find_movie_by_client_id(
                    conn, persistent_client_id
                ),
                find_by_barcode=lambda: find_movie_by_barcode_match(
                    conn,
                    fields["barcode"],
                    incoming_media_type=fields["media_type"],
                ),
                find_by_tmdb_edition=lambda: find_movie_by_tmdb_edition(
                    conn,
                    tmdb_id=tmdb_id,
                    fmt=fields["format"],
                    edition=fields["edition"],
                    incoming_title=fields["title"],
                    incoming_year=fields["year"],
                    incoming_barcode=fields["barcode"],
                    incoming_media_type=fields["media_type"],
                ),
            )

    if ladder_entity_id is not None:
        entity_id = ladder_entity_id
        healed_barcode = fields["barcode"]
    else:
        # H4 tombstone guard: before minting a fresh id, check whether this
        # record's identity belongs to a tombstoned row. Reusing that id (instead
        # of creating a new one) prevents a resurrection duplicate. Whether the
        # row comes back to life depends on client edit time vs. the tombstone.
        if provided_entity_id is None and batch_ctx is not None and not duplicate_copy:
            tomb = find_tombstoned_movie_by_identity(
                conn,
                persistent_client_id=persistent_client_id,
                barcode=fields["barcode"],
            )
            if tomb is not None:
                matched_by = tomb["matched_by"]
                client_ts = parse_client_timestamp(payload.get("updated_at"))
                deleted_at = tomb.get("deleted_at")
                resurrect = (
                    client_ts is not None
                    and deleted_at is not None
                    and client_ts > deleted_at
                )
                if not resurrect:
                    # Delete wins: do not touch the tombstone. Map the client's
                    # temp id to it and return the deleted record so the client
                    # learns (via response + delta) that it is gone.
                    return tombstoned_movie_upsert_result(
                        conn,
                        client_id=client_id,
                        idem_key=idem_key,
                        mutation=mutation,
                        client_entity_id=client_entity_id,
                        tombstone=tomb,
                        matched_by=matched_by,
                        persistent_client_id=persistent_client_id,
                    )
                # Resurrection: reuse the tombstoned id and clear deleted_at below.
                entity_id = tomb["id"]
                healed_barcode = fields["barcode"]
                resurrect_tombstone = True
            else:
                entity_id, healed_barcode = resolve_new_movie_identity(
                    entity_id=provided_entity_id,
                    client_entity_id=client_entity_id,
                    barcode=fields["barcode"],
                    batch_ctx=batch_ctx,
                    lookup_mapping=lambda: client_entity_mapping(
                        conn,
                        client_id=client_id,
                        entity_type="movie",
                        client_entity_id=client_entity_id,
                    ),
                    barcode_owner_lookup=lambda code: movie_id_for_barcode(conn, code),
                )
        else:
            entity_id, healed_barcode = resolve_new_movie_identity(
                entity_id=provided_entity_id,
                client_entity_id=client_entity_id,
                barcode=fields["barcode"],
                batch_ctx=batch_ctx,
                lookup_mapping=lambda: client_entity_mapping(
                    conn,
                    client_id=client_id,
                    entity_type="movie",
                    client_entity_id=client_entity_id,
                ),
                barcode_owner_lookup=lambda code: movie_id_for_barcode(conn, code),
            )
    if provided_entity_id is None:
        # Belt-and-braces barcode adoption for the create path.
        #
        # Batch/sync path: the dedup ladder already ran (digits-only match) and
        # left healed_barcode intact when it did not adopt, so re-checking
        # healed_barcode with the same normalized matcher is correct here.
        #
        # Single, non-batch path (Import Center movie/box-set-member imports):
        # the ladder never runs, so resolve_new_movie_identity() detects an
        # *exact* barcode collision and null-heals healed_barcode to None. That
        # would hide the conflict from the check below and mint a NULL-barcode
        # duplicate. Re-run the exact lookup against the original barcode so the
        # row adopts the live owner instead. Exact (not digits-only) matching is
        # required here because synthetic box-set member barcodes
        # (IMPORT-<title>-BOX-01) collapse to the same digits ("01") across
        # unrelated sets, and a digits-only match would wrongly merge them.
        if batch_ctx is None:
            barcode_owner = (
                movie_id_for_barcode(conn, fields["barcode"])
                if fields["barcode"]
                else None
            )
        else:
            barcode_owner = (
                find_movie_by_barcode_match(conn, healed_barcode)
                if healed_barcode
                else None
            )
        if barcode_owner is not None and barcode_owner != entity_id:
            if duplicate_copy:
                # Explicit duplicate-copy intent keeps a distinct row: drop the
                # colliding barcode instead of adopting another movie id.
                healed_barcode = None
            else:
                entity_id = barcode_owner
                matched_by = "barcode"
                healed_barcode = fields["barcode"]

    existing = movie_entity(conn, entity_id)
    created = existing is None
    if created:
        # A brand-new record was not "matched"; matchedBy only describes how an
        # existing record was found by the dedup ladder.
        matched_by = None
    title = fields["title"] or (existing or {}).get("title")
    if not title:
        raise NextApiError("Movie title is required for upsert", 400)

    public_id = payload.get("publicId") or payload.get("public_id")
    public_id = public_id or (existing or {}).get("public_id") or f"next-movie-{entity_id}"

    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO movies (
                id,
                public_id,
                barcode,
                title,
                sort_title,
                original_title,
                release_title,
                year,
                release_date,
                format,
                media_type,
                edition,
                edition_type,
                country,
                language,
                runtime_minutes,
                overview,
                notes,
                rating,
                purchase_date,
                purchase_price,
                estimated_value,
                estimated_value_currency,
                location,
                client_id,
                metadata,
                created_at,
                updated_at
            )
            VALUES (
                %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                -- The insert and the update branch need *different* answers to
                -- "the client said nothing", so media_type cannot be a plain
                -- placeholder here. A new row has to land on the column's
                -- at-rest default; naming the column explicitly and binding
                -- NULL would defeat the DEFAULT and hit the NOT NULL instead.
                COALESCE(%s, %s),
                %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                %s, %s, %s,
                now(), now()
            )
            ON CONFLICT (id) DO UPDATE SET
                barcode=COALESCE(EXCLUDED.barcode, movies.barcode),
                title=COALESCE(EXCLUDED.title, movies.title),
                sort_title=COALESCE(EXCLUDED.sort_title, movies.sort_title),
                original_title=COALESCE(EXCLUDED.original_title, movies.original_title),
                release_title=COALESCE(EXCLUDED.release_title, movies.release_title),
                year=COALESCE(EXCLUDED.year, movies.year),
                release_date=COALESCE(EXCLUDED.release_date, movies.release_date),
                format=COALESCE(EXCLUDED.format, movies.format),
                -- Deliberately the raw parameter and not EXCLUDED.media_type:
                -- the inserted row was already coalesced to the default above,
                -- so reading it back here would let a client that stated no
                -- type reset a stored SHOW to MOVIE. Only what this client
                -- actually said may overwrite what is stored — and while a
                -- series link exists, not even that: no v26 client models the
                -- link, so a stated MOVIE cannot be a decision to unlink, and
                -- writing it would trip movies_series_requires_show and lose
                -- the whole upsert. The response echoes the stored row, so
                -- the client reconciles to SHOW.
                media_type=CASE
                    WHEN movies.series_id IS NOT NULL THEN movies.media_type
                    ELSE COALESCE(%s, movies.media_type)
                END,
                edition=COALESCE(EXCLUDED.edition, movies.edition),
                edition_type=COALESCE(EXCLUDED.edition_type, movies.edition_type),
                country=COALESCE(EXCLUDED.country, movies.country),
                language=COALESCE(EXCLUDED.language, movies.language),
                runtime_minutes=COALESCE(EXCLUDED.runtime_minutes, movies.runtime_minutes),
                overview=COALESCE(EXCLUDED.overview, movies.overview),
                notes=COALESCE(EXCLUDED.notes, movies.notes),
                rating=COALESCE(EXCLUDED.rating, movies.rating),
                purchase_date=COALESCE(EXCLUDED.purchase_date, movies.purchase_date),
                purchase_price=COALESCE(EXCLUDED.purchase_price, movies.purchase_price),
                estimated_value=COALESCE(EXCLUDED.estimated_value, movies.estimated_value),
                estimated_value_currency=COALESCE(
                    EXCLUDED.estimated_value_currency, movies.estimated_value_currency
                ),
                location=COALESCE(EXCLUDED.location, movies.location),
                client_id=COALESCE(movies.client_id, EXCLUDED.client_id),
                metadata=movies.metadata || EXCLUDED.metadata,
                updated_at=now()
            """,
            (
                entity_id,
                public_id,
                healed_barcode,
                title,
                fields["sort_title"],
                fields["original_title"],
                fields["release_title"],
                fields["year"],
                fields["release_date"],
                fields["format"],
                fields["media_type"],
                MEDIA_TYPE_MOVIE,
                fields["edition"],
                fields["edition_type"],
                fields["country"],
                fields["language"],
                fields["runtime_minutes"],
                fields["overview"],
                fields["notes"],
                fields["rating"],
                fields["purchase_date"],
                fields["purchase_price"],
                fields["estimated_value"],
                fields["estimated_value_currency"],
                fields["location"],
                persistent_client_id,
                Jsonb(fields["metadata"]),
                # The ON CONFLICT clause's own media_type placeholder.
                fields["media_type"],
            ),
        )

    # The technical profile, through the same helper the PATCH path uses
    # (`write_movie_edit_record`). Deliberately not a second write path with its
    # own behaviour: the normalisers, the union-at-rest handling and the
    # absent-vs-empty rule then only exist once.
    #
    # A client that predates sync-contract §4.7 sends none of these keys, so
    # `technical_edits` is empty and this is a no-op — which is what makes it
    # safe to ship the server ahead of the clients.
    with conn.cursor() as cur:
        upsert_movie_technical_edits(
            cur,
            entity_id,
            drop_disc_derived_edits(cur, entity_id, fields.get("technical_edits") or {}),
        )
        apply_movie_location_assignment(cur, entity_id, fields.get("location_assignment") or {})
        # The discs, through the same writer the edit API uses -- one validator,
        # one diff-by-id, one blank-list rule (sync-contract §4.9). Validated
        # against the *stored* media type rather than the payload's: a client
        # may push discs without restating the type, and "no opinion" on the
        # type must not read as "this is a film" when the row says SHOW.
        if fields.get("discs") is not None:
            cur.execute("SELECT media_type FROM movies WHERE id = %s", (entity_id,))
            stored = cur.fetchone()
            apply_movie_discs(
                cur,
                entity_id,
                fields["discs"],
                media_type=(stored or {}).get("media_type") or MEDIA_TYPE_MOVIE,
            )

    # Persist the TMDB identifier so trede 3 (tmdb+format+edition) can match on a
    # later sync. Idempotent: the composite PK makes re-writes a no-op.
    if tmdb_id and table_exists(conn, "movie_identifiers"):
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO movie_identifiers
                    (movie_id, provider_id, identifier_type, identifier)
                VALUES (%s, 'tmdb', 'movie_id', %s)
                ON CONFLICT (movie_id, provider_id, identifier_type, identifier)
                DO NOTHING
                """,
                (entity_id, str(tmdb_id)),
            )

    # Resurrect a tombstoned record only when the client's edit post-dates the
    # deletion (decided above); otherwise the delete-wins path returned earlier.
    if resurrect_tombstone:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE movies SET deleted_at=NULL, updated_at=now() WHERE id=%s",
                (entity_id,),
            )

    # Record this create for batch-local dedup so a repeated clientId within the
    # same batch collapses onto this row (created=false on the second item).
    if created and batch_ctx is not None and persistent_client_id:
        batch_ctx.claimed_client_ids[persistent_client_id] = entity_id

    store_client_entity_mapping(
        conn,
        client_id=client_id,
        client_entity_id=client_entity_id,
        entity_type="movie",
        entity_id=entity_id,
        idem_key=idem_key,
    )
    entity = movie_entity(conn, entity_id) or {}
    revision = next_revision(conn)
    change_payload = {
        "entity": entity,
        "clientId": client_id,
        "clientEntityId": client_entity_id,
        "clientMutationId": mutation["clientMutationId"],
        "created": created,
        "matchedBy": matched_by,
        "recordClientId": persistent_client_id,
    }
    sync_change(
        conn,
        revision=revision,
        entity_type="movie",
        entity_id=str(entity_id),
        operation="upsert",
        payload=change_payload,
    )
    # The sync path writes the same columns the edit form does, and until now
    # left no trace of having done it. `movie.updated` was recorded for a PATCH
    # and for nothing else, so a value that changed underneath somebody could
    # be attributed to a plugin (provenance names those) or to a person (the
    # audit named those) or to nothing at all -- and "nothing at all" was every
    # write from the iOS and Android apps.
    #
    # `clientId` is the one identifier that separates them. It is a stable
    # per-installation string the client chooses, so it says *which device*
    # rather than which platform; the user agent recorded alongside it says the
    # platform. Neither alone answers "who changed this".
    audit_event(
        conn,
        event_type="movie.updated",
        category="sync",
        actor=(batch_ctx.actor if batch_ctx else None),
        target_type="movie",
        target_id=entity_id,
        summary=f"Synced movie edit from {client_id}",
        metadata={
            "movieId": str(entity_id),
            "clientId": client_id,
            "created": created,
            "source": "sync",
            # Which fields the mutation actually carried. A sync body is
            # presence-keyed, so this is the difference between "the client
            # sent a format" and "the client left it alone" -- the question
            # anyone reading this row is trying to answer.
            "changedFields": sorted(
                key for key in payload if key not in {"id", "clientEntityId", "clientMutationId"}
            ),
        },
    )
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "movie",
        "operation": "upsert",
        "entityId": entity_id,
        "clientEntityId": client_entity_id,
        "revision": revision,
        "entity": entity,
        "created": created,
        "matchedBy": matched_by,
        "recordClientId": persistent_client_id,
    }


def apply_movie_delete(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
) -> dict[str, Any]:
    client_entity_id = str(mutation.get("clientEntityId") or "").strip() or None
    entity_id = parse_uuid(mutation.get("entityId"), "entityId")
    entity_id = entity_id or client_entity_mapping(
        conn,
        client_id=client_id,
        entity_type="movie",
        client_entity_id=client_entity_id,
    )
    if not entity_id:
        raise NextApiError("Movie delete requires entityId or mapped clientEntityId", 400)
    with conn.cursor() as cur:
        cur.execute(
            """
            UPDATE movies
            SET deleted_at=now(), updated_at=now()
            WHERE id=%s AND deleted_at IS NULL
            RETURNING id
            """,
            (entity_id,),
        )
        deleted = cur.fetchone()
    if not deleted:
        # Idempotent: re-deleting an already-tombstoned record still succeeds and
        # re-emits the deletion into the delta feed. Only a truly unknown id 404s.
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM movies WHERE id=%s", (entity_id,))
            row = cur.fetchone()
        if not row:
            raise NextApiError("Movie not found", 404)
    revision = next_revision(conn)
    payload = {
        "entityId": entity_id,
        "clientId": client_id,
        "clientEntityId": client_entity_id,
        "clientMutationId": mutation["clientMutationId"],
    }
    sync_change(
        conn,
        revision=revision,
        entity_type="movie",
        entity_id=str(entity_id),
        operation="delete",
        payload=payload,
    )
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "movie",
        "operation": "delete",
        "entityId": entity_id,
        "clientEntityId": client_entity_id,
        "revision": revision,
    }


def resolve_sync_entity_id(
    conn,
    *,
    client_id: str,
    entity_type: str,
    raw_value: Any,
) -> UUID | None:
    """Resolve a mutation reference to a server UUID.

    Accepts either a real UUID or a client-supplied temporary id that an
    earlier queued mutation mapped to a server entity (offline create → link).
    """
    entity_uuid = parse_uuid(raw_value, "entityId") if raw_value else None
    if entity_uuid:
        return entity_uuid
    candidate = str(raw_value or "").strip() or None
    if not candidate:
        return None
    return client_entity_mapping(
        conn,
        client_id=client_id,
        entity_type=entity_type,
        client_entity_id=candidate,
    )


def find_container_by_barcode(
    conn,
    barcode: str | None,
    *,
    container_type: str | None = None,
) -> UUID | None:
    """Return the id of a live container whose barcode matches (or None).

    Digits-only comparison (mirrors find_movie_by_barcode_match) so formatting
    variants of the same EAN collapse; tombstoned rows are excluded. Optionally
    scoped to ``container_type`` so a box set never adopts a vault or collection
    that happens to share a barcode. Oldest row wins for a stable canonical id.
    """
    normalized = normalize_barcode(barcode)
    if not normalized:
        return None
    if not table_exists(conn, "containers"):
        return None
    clauses = [
        "deleted_at IS NULL",
        "barcode IS NOT NULL",
        "regexp_replace(barcode, '\\D', '', 'g') = %s",
    ]
    params: list[Any] = [normalized]
    if container_type:
        clauses.append("container_type = %s")
        params.append(container_type)
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT id
            FROM containers
            WHERE {' AND '.join(clauses)}
            ORDER BY created_at
            LIMIT 1
            """,
            tuple(params),
        )
        row = cur.fetchone()
    return row["id"] if row else None


def find_container_by_client_id(conn, client_id: str | None) -> UUID | None:
    """Trede 1 (§2b): a live container already carrying this persistent clientId."""
    if not client_id:
        return None
    if not table_exists(conn, "containers"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            "SELECT id FROM containers WHERE client_id=%s AND deleted_at IS NULL",
            (client_id,),
        )
        row = cur.fetchone()
    return row["id"] if row else None


def find_container_by_identifier(
    conn,
    *,
    identifier_type: str | None,
    identifier: str | None,
    container_type: str | None,
    incoming_title: str | None = None,
    incoming_barcode: Any = None,
) -> UUID | None:
    """Trede 3 (§2b): same external identifier + container_type.

    Mirrors find_movie_by_tmdb_edition's over-merge sanity checks: a shared
    identifier never merges two containers whose titles materially diverge or
    whose barcodes conflict. Structurally defined per the contract even
    though there is, as of this writing, no confirmed producer of container
    identifiers yet.
    """
    identifier_value = clean_text(identifier)
    identifier_type_value = clean_text(identifier_type)
    if not identifier_value or not identifier_type_value or not container_type:
        return None
    if not table_exists(conn, "container_identifiers") or not table_exists(conn, "containers"):
        return None
    incoming_title_key = normalize_title(incoming_title)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT c.id, c.title, c.barcode
            FROM containers c
            JOIN container_identifiers ci ON ci.container_id = c.id
            WHERE c.deleted_at IS NULL
              AND c.container_type = %s
              AND lower(ci.identifier_type) = lower(%s)
              AND ci.identifier = %s
            ORDER BY c.created_at
            """,
            (container_type, identifier_type_value, identifier_value),
        )
        rows = cur.fetchall()
    for row in rows:
        if _barcode_conflicts(incoming_barcode, row.get("barcode")):
            continue
        candidate_title_key = normalize_title(row.get("title"))
        if incoming_title_key and candidate_title_key and incoming_title_key != candidate_title_key:
            continue
        return row["id"]
    return None


def find_container_by_title_type(
    conn,
    *,
    title: str | None,
    container_type: str | None,
    incoming_barcode: Any = None,
) -> UUID | None:
    """Trede 4 (§2b, adoption-only): normalized title + exact container_type.

    Containers have no year concept, so unlike find_movie_by_title_year this
    tier has no remake-safety clause -- title + container_type is sufficient,
    plus the same barcode-conflict guard as trede 3.
    """
    normalized = normalize_title(title)
    if not normalized or not container_type:
        return None
    if not table_exists(conn, "containers"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, title, barcode
            FROM containers
            WHERE deleted_at IS NULL
              AND container_type = %s
            ORDER BY created_at
            """,
            (container_type,),
        )
        rows = cur.fetchall()
    for row in rows:
        if _barcode_conflicts(incoming_barcode, row.get("barcode")):
            continue
        if normalize_title(row.get("title")) == normalized:
            return row["id"]
    return None


def match_existing_container(
    *,
    persistent_client_id: str | None,
    barcode_normalized: str | None,
    identifier_type: str | None,
    identifier: str | None,
    container_type: str | None,
    find_by_client_id,
    find_by_barcode,
    find_by_identifier,
) -> tuple[UUID | None, str | None]:
    """Create-path container identity ladder (contract §2b/§4b.2).

    Strict order, mirroring match_existing_movie: clientId -> barcode ->
    external identifier. Trede 4 (title+container_type) is deliberately
    absent here; it is only active on the first-connect reconcile path
    (match_reconcile_container). There is no duplicate_copy equivalent for
    containers (§4b.1) -- a second physical copy of the same box-set
    packaging is not a modeled scenario.
    """
    if persistent_client_id:
        found = find_by_client_id()
        if found is not None:
            return found, "clientId"
    if barcode_normalized:
        found = find_by_barcode()
        if found is not None:
            return found, "barcode"
    if identifier and identifier_type and container_type:
        found = find_by_identifier()
        if found is not None:
            return found, "containerIdentifier"
    return None, None


def match_reconcile_container(
    *,
    persistent_client_id: str | None,
    barcode_normalized: str | None,
    identifier_type: str | None,
    identifier: str | None,
    container_type: str | None,
    title: str | None,
    find_by_client_id,
    find_by_barcode,
    find_by_identifier,
    find_by_title_type,
) -> tuple[UUID | None, str | None]:
    """First-connect adoption ladder for containers (contract §5b).

    Read-only: never creates. The title+container_type tier is active here
    and only here, mirroring match_reconcile_item's restriction of the
    fuzziest tier to the adoption path.
    """
    if persistent_client_id:
        found = find_by_client_id()
        if found is not None:
            return found, "clientId"
    if barcode_normalized:
        found = find_by_barcode()
        if found is not None:
            return found, "barcode"
    if identifier and identifier_type and container_type:
        found = find_by_identifier()
        if found is not None:
            return found, "containerIdentifier"
    if title and container_type:
        found = find_by_title_type()
        if found is not None:
            return found, "titleType"
    return None, None


def container_list_row(row: dict[str, Any]) -> dict[str, Any]:
    """Fold a container list row's joined poster columns into a `poster_url`.

    The list view reads `poster_url` first and falls back to a metadata URL, so
    exposing the container's own primary artwork here is what makes a cover that
    lives in entity_media (a synced, scanned or uploaded one) show in the library
    and not just on the detail page."""
    item = dict(row)
    asset = {
        "id": item.pop("poster_asset_id", None),
        "storage_backend": item.pop("poster_storage_backend", None),
        "storage_key": item.pop("poster_storage_key", None),
        "source_url": item.pop("poster_source_url", None),
    }
    if asset["id"]:
        poster_url = media_asset_public_url(asset)
        if poster_url:
            item["poster_url"] = poster_url
    return item


CONTAINER_SYNC_ARTWORK_KEYS = {
    "poster": ("posterUrl", "poster_url", "poster"),
    "backdrop": ("backdropUrl", "backdrop_url", "backdrop"),
}


def container_sync_artwork_urls(
    payload: dict[str, Any],
    metadata: dict[str, Any] | None = None,
) -> dict[str, str]:
    """Read the artwork a client pushes alongside a container.

    A box set scanned on another client carries the cover its source resolved
    (e.g. MovieVault's), and that link is the set's own artwork -- without it the
    container falls back to a member film's poster, which is a different film's
    cover. The payload root wins over ``metadata`` because a client that sends
    both means the root as the current value."""
    urls: dict[str, str] = {}
    for kind, keys in CONTAINER_SYNC_ARTWORK_KEYS.items():
        for source in (payload, metadata):
            if not isinstance(source, dict):
                continue
            for key in keys:
                value = clean_text(source.get(key))
                if value and value.startswith(("http://", "https://")):
                    urls[kind] = value
                    break
            if kind in urls:
                break
    return urls


def attach_container_sync_artwork(
    conn,
    *,
    container_id: UUID,
    payload: dict[str, Any],
    metadata: dict[str, Any] | None = None,
) -> None:
    """Register pushed container artwork as a selectable option, preferred as
    the primary one.

    ``link_container_media_option`` only honours ``primary`` when the container
    has no primary artwork of that kind yet, so a cover the user has since
    chosen is never overwritten -- the pushed artwork simply becomes the
    default for a container that has none. Artwork is supplementary, so each
    attach runs in its own savepoint and a failure never fails the sync
    mutation carrying it."""
    for kind, source_url in container_sync_artwork_urls(payload, metadata).items():
        try:
            with conn.transaction():
                link_container_media_option(
                    conn,
                    container_id=container_id,
                    kind=kind,
                    source_url=source_url,
                    provider_id="sync",
                    sort_order=0,
                    primary=True,
                )
        except Exception:
            app.logger.warning("Could not attach pushed container %s artwork", kind)


def apply_container_upsert(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = mutation.get("payload")
    if not isinstance(payload, dict):
        raise NextApiError("Container upsert payload must be an object", 400)
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)

    client_entity_id = str(mutation.get("clientEntityId") or "").strip() or None
    provided_entity_id = parse_uuid(mutation.get("entityId"), "entityId")
    mapped_entity_id = None
    if provided_entity_id is None:
        mapped_entity_id = client_entity_mapping(
            conn,
            client_id=client_id,
            entity_type="container",
            client_entity_id=client_entity_id,
        )
    entity_id = provided_entity_id or mapped_entity_id

    # Persistent per-record identity (contract §4b.1), mirroring the movie
    # upsert's persistent_client_id handling. Trede 3's identifier fields are
    # read here too, structurally, even though no client currently sends
    # them -- contract §2b tier 3 is "structurally defined, may have zero
    # live producers initially".
    persistent_client_id = clean_text(payload.get("client_id"))
    metadata_payload = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    incoming_identifier_type = clean_text(metadata_payload.get("identifier_type"))
    incoming_identifier = clean_text(metadata_payload.get("identifier"))
    incoming_title_for_match = clean_text(payload.get("title"))
    incoming_type_for_match: str | None = None
    if "containerType" in payload or "container_type" in payload:
        incoming_type_for_match = normalize_container_type(
            payload.get("containerType", payload.get("container_type"))
        )

    # Create-path identity ladder (contract §2b/§4b.2): clientId -> barcode ->
    # external identifier. Unlike movies, containers carry no UNIQUE(barcode)
    # constraint, so a brand-new box set/vault whose EAN already belongs to a
    # live container would otherwise silently mint a duplicate (there is no
    # duplicate-copy concept for containers -- the same EAN is the same
    # physical box). Only runs when this push is not already tied to a known
    # container by an explicit entityId or a clientEntityId mapping.
    matched_by: str | None = None
    incoming_barcode = clean_text(payload.get("barcode"))
    barcode_norm = normalize_barcode(incoming_barcode)
    if entity_id is None:
        entity_id, matched_by = match_existing_container(
            persistent_client_id=persistent_client_id,
            barcode_normalized=barcode_norm,
            identifier_type=incoming_identifier_type,
            identifier=incoming_identifier,
            container_type=incoming_type_for_match,
            find_by_client_id=lambda: find_container_by_client_id(conn, persistent_client_id),
            find_by_barcode=lambda: find_container_by_barcode(
                conn, incoming_barcode, container_type=incoming_type_for_match
            ),
            find_by_identifier=lambda: find_container_by_identifier(
                conn,
                identifier_type=incoming_identifier_type,
                identifier=incoming_identifier,
                container_type=incoming_type_for_match,
                incoming_title=incoming_title_for_match,
                incoming_barcode=incoming_barcode,
            ),
        )

    entity_id = entity_id or uuid.uuid4()
    existing = container_entity(conn, entity_id)
    created = existing is None
    if created:
        # A brand-new record was not "matched"; matchedBy only describes how
        # an existing record was found by the dedup ladder.
        matched_by = None

    if "containerType" in payload or "container_type" in payload:
        container_type = normalize_container_type(payload.get("containerType", payload.get("container_type")))
    elif existing:
        container_type = existing.get("container_type")
    else:
        container_type = normalize_container_type(None)

    fields = container_payload(payload, existing=existing, container_type=container_type)
    public_id = clean_text(payload.get("publicId") or payload.get("public_id"))
    public_id = public_id or (existing or {}).get("public_id") or f"next-container-{entity_id.hex[:12]}"
    if len(public_id) > 160:
        raise NextApiError("publicId must be 160 characters or fewer", 400)

    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO containers (
                id, public_id, container_type, title, barcode, badge_label, year, description, owner_id, client_id, estimated_value, estimated_value_currency, metadata, created_at, updated_at
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, now(), now())
            ON CONFLICT (id) DO UPDATE SET
                title=COALESCE(EXCLUDED.title, containers.title),
                barcode=EXCLUDED.barcode,
                badge_label=EXCLUDED.badge_label,
                year=EXCLUDED.year,
                description=EXCLUDED.description,
                client_id=COALESCE(containers.client_id, EXCLUDED.client_id),
                estimated_value=COALESCE(EXCLUDED.estimated_value, containers.estimated_value),
                estimated_value_currency=COALESCE(EXCLUDED.estimated_value_currency, containers.estimated_value_currency),
                metadata=containers.metadata || EXCLUDED.metadata,
                updated_at=now()
            """,
            (
                entity_id,
                public_id,
                container_type,
                fields["title"],
                fields["barcode"],
                fields["badge_label"],
                fields["year"],
                fields["description"],
                actor_or_instance_owner_id(conn, actor),
                persistent_client_id,
                fields["estimated_value"],
                fields["estimated_value_currency"],
                Jsonb(json_ready(fields["metadata"])),
            ),
        )

    # No write path into container_identifiers yet: contract §2b tier 3 is
    # "structurally defined, may have zero live producers initially" -- there
    # is no confirmed provider/identifier scheme for containers to persist,
    # unlike movies' tmdb_id. find_container_by_identifier reads whatever a
    # future producer eventually writes there; nothing writes it today.

    attach_container_sync_artwork(
        conn,
        container_id=entity_id,
        payload=payload,
        metadata=fields.get("metadata"),
    )

    store_client_entity_mapping(
        conn,
        client_id=client_id,
        client_entity_id=client_entity_id,
        entity_type="container",
        entity_id=entity_id,
        idem_key=idem_key,
    )
    entity = single_container_sync_entity(conn, entity_id) or {}
    revision = next_revision(conn)
    sync_change(
        conn,
        revision=revision,
        entity_type="container",
        entity_id=str(entity_id),
        operation="upsert",
        payload={
            "id": str(entity_id),
            "entity": entity,
            "clientId": client_id,
            "clientEntityId": client_entity_id,
            "clientMutationId": mutation["clientMutationId"],
        },
    )
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "container",
        "operation": "upsert",
        "entityId": entity_id,
        "clientEntityId": client_entity_id,
        "revision": revision,
        "entity": entity,
        "created": created,
        "matchedBy": matched_by,
        "recordClientId": persistent_client_id,
    }


def apply_container_delete(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
) -> dict[str, Any]:
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)
    client_entity_id = str(mutation.get("clientEntityId") or "").strip() or None
    entity_id = parse_uuid(mutation.get("entityId"), "entityId")
    entity_id = entity_id or client_entity_mapping(
        conn,
        client_id=client_id,
        entity_type="container",
        client_entity_id=client_entity_id,
    )
    if not entity_id:
        raise NextApiError("Container delete requires entityId or mapped clientEntityId", 400)
    # Soft delete (tombstone) rather than a hard cascade: the delta feed emits the
    # deletion so clients prune locally, and a re-pushed old copy hits the H4 guard
    # instead of resurrecting the box set. Membership links are left intact.
    with conn.cursor() as cur:
        cur.execute(
            """
            UPDATE containers
            SET deleted_at=now(), updated_at=now()
            WHERE id=%s AND deleted_at IS NULL
            RETURNING id
            """,
            (entity_id,),
        )
        tombstoned = cur.fetchone()
    if not tombstoned:
        # Idempotent re-delete: already tombstoned still succeeds and re-emits the
        # deletion; a truly unknown id 404s.
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM containers WHERE id=%s", (entity_id,))
            row = cur.fetchone()
        if not row:
            raise NextApiError("Container not found", 404)
    revision = emit_container_change(conn, entity_id, operation="delete")
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "container",
        "operation": "delete",
        "entityId": entity_id,
        "clientEntityId": client_entity_id,
        "revision": revision,
    }


def apply_container_movie_upsert(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
) -> dict[str, Any]:
    payload = mutation.get("payload")
    if not isinstance(payload, dict):
        raise NextApiError("containerMovie upsert payload must be an object", 400)
    if not table_exists(conn, "container_movies"):
        raise NextApiError("Container movie links are not available yet", 503)

    container_id = resolve_sync_entity_id(
        conn,
        client_id=client_id,
        entity_type="container",
        raw_value=payload.get("containerId") or payload.get("container_id"),
    )
    movie_id = resolve_sync_entity_id(
        conn,
        client_id=client_id,
        entity_type="movie",
        raw_value=payload.get("movieId") or payload.get("movie_id"),
    )
    if not container_id or not movie_id:
        raise NextApiError("containerMovie upsert requires containerId and movieId", 400)
    if not container_entity(conn, container_id):
        raise NextApiError("Container not found", 404)
    # A collection keeps its members in collection_items, and
    # container_direct_member_ids() never reads container_movies for one. Writing
    # the row anyway would return `applied` for a link nothing ever reads back --
    # and per contract §4b.6 `isApplied` is the only confirmation a client has, so
    # it would book the membership as settled and never offer it again. Failing
    # loudly is the whole point.
    if container_type_for_id(conn, container_id) == "collection":
        raise NextApiError(
            "containerMovie does not apply to a collection; use collectionItem", 400
        )
    if not movie_entity(conn, movie_id):
        raise NextApiError("Movie not found", 404)

    sort_order_raw = payload.get("sortOrder", payload.get("sort_order"))
    with conn.cursor() as cur:
        if sort_order_raw is None:
            cur.execute(
                "SELECT COALESCE(MAX(sort_order), 0)::int AS max_sort FROM container_movies WHERE container_id=%s",
                (container_id,),
            )
            sort_order = int(cur.fetchone()["max_sort"]) + 1
        else:
            try:
                sort_order = int(sort_order_raw)
            except (TypeError, ValueError):
                raise NextApiError("sortOrder must be an integer", 400)
        cur.execute(
            """
            INSERT INTO container_movies (container_id, movie_id, sort_order, created_at)
            VALUES (%s, %s, %s, now())
            ON CONFLICT (container_id, movie_id) DO UPDATE SET sort_order=EXCLUDED.sort_order
            """,
            (container_id, movie_id, sort_order),
        )
        cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (container_id,))
    revision = emit_container_membership_change(conn, container_id)
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "containerMovie",
        "operation": "upsert",
        "entityId": container_id,
        "movieId": movie_id,
        "sortOrder": sort_order,
        "revision": revision,
    }


def apply_container_movie_delete(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
) -> dict[str, Any]:
    payload = mutation.get("payload")
    if not isinstance(payload, dict):
        raise NextApiError("containerMovie delete payload must be an object", 400)
    if not table_exists(conn, "container_movies"):
        raise NextApiError("Container movie links are not available yet", 503)

    container_id = resolve_sync_entity_id(
        conn,
        client_id=client_id,
        entity_type="container",
        raw_value=payload.get("containerId") or payload.get("container_id"),
    )
    movie_id = resolve_sync_entity_id(
        conn,
        client_id=client_id,
        entity_type="movie",
        raw_value=payload.get("movieId") or payload.get("movie_id"),
    )
    if not container_id or not movie_id:
        raise NextApiError("containerMovie delete requires containerId and movieId", 400)
    # Same reasoning as the upsert: a delete against a collection removes a row
    # that was never the collection's membership, and reports success for it.
    # `optional_container_type` rather than `container_type_for_id` so a delete
    # for an already-removed container stays a no-op success (§4b.6 retries).
    if optional_container_type(conn, container_id) == "collection":
        raise NextApiError(
            "containerMovie does not apply to a collection; use collectionItem", 400
        )
    with conn.cursor() as cur:
        cur.execute(
            "DELETE FROM container_movies WHERE container_id=%s AND movie_id=%s",
            (container_id, movie_id),
        )
        changed = cur.rowcount
        if changed:
            cur.execute(
                "UPDATE containers SET primary_movie_id=NULL WHERE id=%s AND primary_movie_id=%s",
                (container_id, movie_id),
            )
            cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (container_id,))
    revision = emit_container_membership_change(conn, container_id) if changed else current_revision(conn)
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "containerMovie",
        "operation": "delete",
        "entityId": container_id,
        "movieId": movie_id,
        "changed": int(changed or 0),
        "revision": revision,
    }


def collection_item_reference(
    conn,
    *,
    client_id: str,
    payload: dict[str, Any],
    label: str,
) -> tuple[UUID, str, UUID]:
    """Read and resolve a collectionItem payload into (collectionId, itemType, itemId).

    Both ids go through ``resolve_sync_entity_id()`` so a client-minted
    temporary id from an earlier queued create resolves the same way it does
    everywhere else. snake_case aliases are accepted alongside camelCase, as the
    containerMovie payload does; the *entity type* token itself stays
    casing-strict."""
    collection_id = resolve_sync_entity_id(
        conn,
        client_id=client_id,
        entity_type="container",
        raw_value=payload.get("collectionId") or payload.get("collection_id"),
    )
    item_type = clean_text(payload.get("itemType") or payload.get("item_type"))
    raw_item_id = payload.get("itemId") or payload.get("item_id")
    if not collection_id or not item_type or raw_item_id in (None, ""):
        raise NextApiError(f"{label} requires collectionId, itemType and itemId", 400)
    if item_type not in COLLECTION_ITEM_TYPES:
        raise NextApiError(
            "itemType must be one of movie, vault, box_set, collection", 400
        )
    item_id = resolve_sync_entity_id(
        conn,
        client_id=client_id,
        entity_type="movie" if item_type == "movie" else "container",
        raw_value=raw_item_id,
    )
    if not item_id:
        raise NextApiError(f"{label} requires a resolvable itemId", 400)
    return collection_id, item_type, item_id


def apply_collection_item_upsert(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
) -> dict[str, Any]:
    payload = mutation.get("payload")
    if not isinstance(payload, dict):
        raise NextApiError("collectionItem upsert payload must be an object", 400)
    if not table_exists(conn, "collection_items"):
        raise NextApiError("Collection items are not available yet", 503)

    collection_id, item_type, item_id = collection_item_reference(
        conn, client_id=client_id, payload=payload, label="collectionItem upsert"
    )
    if container_type_for_id(conn, collection_id) != "collection":
        raise NextApiError("collectionId must reference a collection", 400)

    if item_type == "movie":
        if not movie_entity(conn, item_id):
            raise NextApiError("Movie not found", 404)
    else:
        # The declared itemType must match what the id actually is. An itemType
        # of box_set pointing at a vault is a client bug worth surfacing; a
        # server that normalised it silently would hide the client's confusion
        # about its own data.
        actual_type = container_type_for_id(conn, item_id)
        if actual_type != item_type:
            raise NextApiError(
                f"itemType {item_type} does not match the container's type {actual_type}",
                400,
            )
    guard_collection_item_cycle(
        conn, collection_id=collection_id, item_type=item_type, item_id=item_id
    )

    sort_order_raw = payload.get("sortOrder", payload.get("sort_order"))
    with conn.cursor() as cur:
        if sort_order_raw is None:
            cur.execute(
                "SELECT COALESCE(MAX(sort_order), 0)::int AS max_sort FROM collection_items WHERE collection_id=%s",
                (collection_id,),
            )
            sort_order = int(cur.fetchone()["max_sort"]) + 1
        else:
            try:
                sort_order = int(sort_order_raw)
            except (TypeError, ValueError):
                raise NextApiError("sortOrder must be an integer", 400)
        # PRIMARY KEY (collection_id, item_type, item_id) makes the repeat a
        # no-op update rather than a second row, so the client may retry an
        # unconfirmed upsert unconditionally (§4b.6).
        cur.execute(
            """
            INSERT INTO collection_items (collection_id, item_type, item_id, sort_order, created_at)
            VALUES (%s, %s, %s, %s, now())
            ON CONFLICT (collection_id, item_type, item_id) DO UPDATE SET sort_order=EXCLUDED.sort_order
            """,
            (collection_id, item_type, item_id, sort_order),
        )
        cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (collection_id,))
    revision = emit_container_membership_change(conn, collection_id)
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "collectionItem",
        "operation": "upsert",
        "entityId": collection_id,
        "itemType": item_type,
        "itemId": item_id,
        "sortOrder": sort_order,
        "revision": revision,
    }


def apply_collection_item_delete(
    conn,
    *,
    client_id: str,
    idem_key: str,
    mutation: dict[str, Any],
) -> dict[str, Any]:
    payload = mutation.get("payload")
    if not isinstance(payload, dict):
        raise NextApiError("collectionItem delete payload must be an object", 400)
    if not table_exists(conn, "collection_items"):
        raise NextApiError("Collection items are not available yet", 503)

    collection_id, item_type, item_id = collection_item_reference(
        conn, client_id=client_id, payload=payload, label="collectionItem delete"
    )
    # Deliberately lenient about the target: a delete must be safe to repeat, so
    # a collection that is already gone is a no-op success and only a *wrong*
    # live target (a box set, a vault) is refused. Nor is a missing row a 404 --
    # clients retry unapplied deletes, and "already not a member" is the state
    # the client asked for.
    existing_type = optional_container_type(conn, collection_id)
    if existing_type is not None and existing_type != "collection":
        raise NextApiError("collectionId must reference a collection", 400)

    with conn.cursor() as cur:
        cur.execute(
            "DELETE FROM collection_items WHERE collection_id=%s AND item_type=%s AND item_id=%s",
            (collection_id, item_type, item_id),
        )
        changed = cur.rowcount
        if changed:
            cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (collection_id,))
    revision = emit_container_membership_change(conn, collection_id) if changed else current_revision(conn)
    return {
        "clientMutationId": mutation["clientMutationId"],
        "status": "applied",
        "entityType": "collectionItem",
        "operation": "delete",
        "entityId": collection_id,
        "itemType": item_type,
        "itemId": item_id,
        "changed": int(changed or 0),
        "revision": revision,
    }


def apply_sync_mutation(
    conn,
    *,
    client_id: str,
    mutation: dict[str, Any],
    batch_ctx: "SyncBatchContext | None" = None,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not isinstance(mutation, dict):
        raise NextApiError("Each mutation must be an object", 400)
    client_mutation_id = str(mutation.get("clientMutationId") or "").strip()
    if not client_mutation_id:
        raise NextApiError("clientMutationId is required", 400)
    mutation["clientMutationId"] = client_mutation_id
    entity_type = str(mutation.get("entityType") or "").strip()
    operation = str(mutation.get("operation") or "").strip()
    key = idempotency_key(client_id, client_mutation_id)
    existing = stored_idempotency_response(conn, key)
    if existing:
        existing["replayed"] = True
        return existing

    if entity_type == "movie" and operation == "upsert":
        result = apply_movie_upsert(
            conn, client_id=client_id, idem_key=key, mutation=mutation, batch_ctx=batch_ctx
        )
    elif entity_type == "movie" and operation == "delete":
        result = apply_movie_delete(conn, client_id=client_id, idem_key=key, mutation=mutation)
    elif entity_type == "container" and operation == "upsert":
        result = apply_container_upsert(
            conn,
            client_id=client_id,
            idem_key=key,
            mutation=mutation,
            actor=actor,
        )
    elif entity_type == "container" and operation == "delete":
        result = apply_container_delete(conn, client_id=client_id, idem_key=key, mutation=mutation)
    elif entity_type == "containerMovie" and operation == "upsert":
        result = apply_container_movie_upsert(conn, client_id=client_id, idem_key=key, mutation=mutation)
    elif entity_type == "containerMovie" and operation == "delete":
        result = apply_container_movie_delete(conn, client_id=client_id, idem_key=key, mutation=mutation)
    elif entity_type == "collectionItem" and operation == "upsert":
        result = apply_collection_item_upsert(conn, client_id=client_id, idem_key=key, mutation=mutation)
    elif entity_type == "collectionItem" and operation == "delete":
        result = apply_collection_item_delete(conn, client_id=client_id, idem_key=key, mutation=mutation)
    else:
        raise NextApiError(f"Unsupported mutation: {entity_type}.{operation}", 400)

    store_idempotency_response(
        conn,
        key=key,
        operation=f"{entity_type}.{operation}",
        status=result["status"],
        entity_type=entity_type,
        entity_id=result.get("entityId"),
        response_payload=result,
    )
    return result


def migration_overview(conn) -> dict[str, Any]:
    migrations = discover_migrations()
    if not table_exists(conn, "schema_migrations"):
        return {
            "state": "not_initialized",
            "applied": 0,
            "pending": len(migrations),
            "checksum_mismatch": 0,
            "items": [
                {
                    "version": migration.version,
                    "name": migration.name,
                    "state": "pending",
                }
                for migration in migrations
            ],
        }

    with conn.cursor() as cur:
        cur.execute("SELECT version, name, checksum, applied_at FROM schema_migrations")
        applied = {row["version"]: row for row in cur.fetchall()}

    items = []
    counters = {"applied": 0, "pending": 0, "checksum_mismatch": 0}
    for migration in migrations:
        row = applied.get(migration.version)
        if not row:
            state = "pending"
        elif row["checksum"] == migration.checksum:
            state = "applied"
        else:
            state = "checksum_mismatch"
        counters[state] += 1
        items.append(
            {
                "version": migration.version,
                "name": migration.name,
                "state": state,
                "applied_at": row["applied_at"] if row else None,
            }
        )

    state = "ready"
    if counters["checksum_mismatch"]:
        state = "blocked"
    elif counters["pending"]:
        state = "pending_migrations"

    return {
        "state": state,
        **counters,
        "items": items,
    }


def plugin_row(row: dict[str, Any]) -> dict[str, Any]:
    manifest = row.get("manifest") or {}
    settings_schema = row.get("settings_schema") or {}
    config = plugin_config_payload(
        settings_schema,
        row.get("settings"),
        row.get("secrets_ref"),
    )
    categories = manifest.get("categories", []) if isinstance(manifest, dict) else []
    capabilities = manifest.get("capabilities", []) if isinstance(manifest, dict) else []
    entitlements = manifest.get("entitlements", {}) if isinstance(manifest, dict) else {}
    runtime = manifest.get("runtime", {}) if isinstance(manifest, dict) else {}
    return {
        "id": row["id"],
        "name": row["name"],
        "version": row["version"],
        "enabled": bool(row["enabled"]),
        "installed": bool(row["installed"]),
        "categories": categories,
        "kind": manifest.get("kind") if isinstance(manifest, dict) else None,
        "orderIndex": row["order_index"],
        "capabilities": capabilities,
        "entitlements": entitlements,
        "manifest": manifest,
        "requiresSecrets": bool(manifest.get("requiresSecrets", False)) if isinstance(manifest, dict) else False,
        "settingsSchema": settings_schema,
        "settingsConfigured": config["settingsConfigured"],
        "secretsConfigured": config["secretsConfigured"],
        "premiumFeatureKey": row.get("premium_feature_key"),
        "runtime": runtime,
        "updatedAt": row.get("updated_at"),
    }


def job_row(row: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": row["id"],
        "jobType": row["job_type"],
        "status": row["status"],
        "requestedBy": row.get("requested_by"),
        "payload": redact_sensitive_payload(row.get("payload") or {}),
        "result": row.get("result") or {},
        "error": row.get("error"),
        "createdAt": row.get("created_at"),
        "startedAt": row.get("started_at"),
        "finishedAt": row.get("finished_at"),
    }


def create_background_job(conn, *, job_type: str, payload: dict[str, Any]) -> dict[str, Any]:
    if not table_exists(conn, "background_jobs"):
        raise NextApiError("Background job table is not available", 503)
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO background_jobs (job_type, payload)
            VALUES (%s, %s)
            RETURNING
                id,
                job_type,
                status,
                requested_by,
                payload,
                result,
                error,
                created_at,
                started_at,
                finished_at
            """,
            (job_type, Jsonb(json_ready(payload))),
        )
        row = cur.fetchone()
    return job_row(row)


def actor_job_payload(actor: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": str(actor.get("id")) if actor.get("id") else None,
        "username": actor.get("username"),
        "role": actor.get("role"),
    }


def queue_movievault_v2_sync_job(
    conn,
    *,
    actor: dict[str, Any],
    source: str,
    skip_when_indexed: bool = False,
) -> tuple[dict[str, Any] | None, bool, bool]:
    if not table_exists(conn, "background_jobs"):
        raise NextApiError("Background job table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT pg_advisory_xact_lock(%s)", (MOVIEVAULT_V2_JOB_LOCK_KEY,))
        if skip_when_indexed and table_exists(conn, "movievault_v2_sync_state"):
            cur.execute(
                """
                SELECT active_generation
                FROM movievault_v2_sync_state
                WHERE plugin_id=%s
                """,
                (MOVIEVAULT_V2_PLUGIN_ID,),
            )
            state = cur.fetchone()
            if state and state.get("active_generation"):
                return None, False, True
        cur.execute(
            """
            SELECT
                id, job_type, status, requested_by, payload, result,
                error, created_at, started_at, finished_at
            FROM background_jobs
            WHERE job_type = %s
              AND status IN ('pending', 'running')
              AND payload ->> 'pluginId' = %s
              AND payload ->> 'entrypoint' = 'sync_index'
            ORDER BY created_at
            LIMIT 1
            """,
            (PLUGIN_EXECUTION_JOB_TYPE, MOVIEVAULT_V2_PLUGIN_ID),
        )
        existing = cur.fetchone()
    if existing:
        return job_row(existing), True, False
    job = create_background_job(
        conn,
        job_type=PLUGIN_EXECUTION_JOB_TYPE,
        payload={
            "pluginId": MOVIEVAULT_V2_PLUGIN_ID,
            "entrypoint": "sync_index",
            "payload": {},
            "requestedBy": actor_job_payload(actor),
            "source": source,
        },
    )
    audit_event(
        conn,
        event_type="plugin.job_queued",
        category="plugins",
        actor=actor,
        target_type="background_job",
        target_id=job.get("id"),
        summary=f"Queued {MOVIEVAULT_V2_PLUGIN_ID}.sync_index",
        metadata={
            "pluginId": MOVIEVAULT_V2_PLUGIN_ID,
            "entrypoint": "sync_index",
            "source": source,
        },
    )
    return job, False, False


def queue_movie_metadata_refresh_job(
    conn,
    movie_id: UUID | str,
    *,
    actor: dict[str, Any] | None = None,
    reason: str,
    source: str | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not table_exists(conn, "background_jobs"):
        return None
    payload: dict[str, Any] = {
        "movieId": str(movie_id),
        "dryRun": False,
        "requestedBy": actor_job_payload(actor or {}),
        "reason": reason,
    }
    if source:
        payload["source"] = source
    if extra:
        payload.update(extra)
    return create_background_job(conn, job_type=METADATA_REFRESH_JOB_TYPE, payload=payload)


def movie_technical_spec_contribution_source(
    conn, movie_id: UUID | str, payload: dict[str, Any]
) -> dict[str, Any]:
    """Express a just-saved movie in the candidate shape the mapper reads.

    A hand-typed release arrives as an ordinary Add form, so there is no
    candidate row to map. What the user actually stated is now on the movie and
    its technical specs, and reading it back from there is the only way to
    contribute exactly what was saved rather than a second guess at it.

    Keys are the wire names the mapper already understands, so the two entry
    points share one mapping instead of growing a parallel one.
    """
    specs = movie_technical_spec_entity(conn, movie_id) or {}
    candidate: dict[str, Any] = {
        "title": clean_text(payload.get("releaseTitle")) or clean_text(payload.get("title")),
        "edition": clean_text(payload.get("edition")),
        "format": clean_text(payload.get("format")),
        "packaging": specs.get("packaging") or [],
        "discRegions": specs.get("regions") or [],
        "audioTracks": specs.get("audio_tracks") or [],
        "subtitles": specs.get("subtitles") or [],
        "video": {
            "resolution": specs.get("video_resolution"),
            "codecs": specs.get("video_codecs") or [],
            "hdrFormats": specs.get("hdr") or [],
            "aspectRatios": specs.get("screen_ratios") or [],
        },
    }
    disc_count = payload.get("discCount") or payload.get("disc_count")
    if isinstance(disc_count, int) and not isinstance(disc_count, bool):
        candidate["discCount"] = disc_count
    # Read back from the saved row rather than the request body: `media_type`
    # is NOT NULL with a MOVIE default, so the row states a type even when the
    # form did not, and that stored value is what the user will see.
    media_type = movie_media_type(conn, movie_id)
    if media_type:
        candidate["workType"] = media_type
    return candidate


def movie_media_type(conn, movie_id: UUID | str) -> str | None:
    """The stored MOVIE/SHOW of a movie, or None when it cannot be read.

    Tolerant of the column being absent so an instance that has not yet run
    migration 063 contributes without a work type rather than failing - absence
    is a valid answer here, and MovieVault reads it as "did not say".
    """
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT media_type FROM movies WHERE id=%s", (movie_id,))
            row = cur.fetchone()
    except psycopg.errors.UndefinedColumn:
        return None
    return clean_text(row.get("media_type")) if row else None


def queue_release_contribution_job(
    conn,
    contribution_payload: dict[str, Any],
    *,
    actor: dict[str, Any] | None = None,
    reason: str,
) -> dict[str, Any] | None:
    """Queue a chosen release for contribution back to MovieVault.

    Queued rather than sent inline, for three reasons that all matter:
    a network round-trip has no business inside a user-visible save; a
    MovieVault outage must not fail an import that already succeeded locally;
    and a signed, attributable write firing in the same second as the anonymous
    resolve that produced the candidate would tie the two together for anyone
    watching the connection.

    Returns None whenever there is nothing to send, so the caller never has to
    decide - the gate, the payload check and the missing-table case all read
    the same way from outside.
    """
    if not contribution_payload or not table_exists(conn, "background_jobs"):
        return None
    payload: dict[str, Any] = {
        "contribution": contribution_payload,
        "requestedBy": actor_job_payload(actor or {}),
        "reason": reason,
    }
    return create_background_job(
        conn, job_type=RELEASE_CONTRIBUTION_JOB_TYPE, payload=payload
    )


def queue_field_correction_job(
    conn,
    correction_payload: dict[str, Any],
    *,
    actor: dict[str, Any] | None = None,
    reason: str,
) -> dict[str, Any] | None:
    """Queue one field correction for MovieVault.

    Queued for the same reasons as a release contribution - the save has
    already succeeded and must not be undone by a MovieVault outage - with one
    that is specific to this path: the user is still looking at the sheet they
    confirmed, and a network round-trip there would make an upstream moderation
    queue feel like part of saving a local edit.

    The job id is the handle the status endpoint reads, so the caller returns it
    rather than waiting for anything.
    """
    if not correction_payload or not table_exists(conn, "background_jobs"):
        return None
    payload: dict[str, Any] = {
        "correction": correction_payload,
        "requestedBy": actor_job_payload(actor or {}),
        "reason": reason,
    }
    return create_background_job(conn, job_type=FIELD_CORRECTION_JOB_TYPE, payload=payload)


def background_job_entity(conn, job_id: Any) -> dict[str, Any] | None:
    """One background job by id, in the shape the API renders.

    `attempts` is selected explicitly rather than through `job_row`: it exists
    only since migration 065, and every other reader of a job predates it and
    does not want it.
    """
    if not table_exists(conn, "background_jobs"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                id, job_type, status, requested_by, payload, result,
                error, created_at, started_at, finished_at, attempts
            FROM background_jobs
            WHERE id = %s
            """,
            (job_id,),
        )
        row = cur.fetchone()
    if not row:
        return None
    return {**job_row(row), "attempts": int(row.get("attempts") or 0)}


def queue_receiver_payload_to_receivers(
    conn,
    *,
    payload: dict[str, Any],
    actor: dict[str, Any] | None = None,
    reason: str = "receiver_payload",
) -> dict[str, Any]:
    receivers = [
        plugin
        for plugin in metadata_receiver_plugins(conn)
        if "receive_metadata" in set(plugin.get("capabilities") or (plugin.get("manifest") or {}).get("capabilities") or [])
    ]
    jobs: list[dict[str, Any]] = []
    if not receivers:
        return {
            "receiverCount": 0,
            "queuedJobs": [],
            "payloadSummary": {
                "entityType": payload.get("entityType"),
                "identity": payload.get("identity"),
                "fieldCount": len(payload.get("payload") or {}),
                "fields": sorted((payload.get("payload") or {}).keys()),
            },
        }
    for plugin in receivers:
        jobs.append(
            create_background_job(
                conn,
                job_type=PLUGIN_EXECUTION_JOB_TYPE,
                payload={
                    "pluginId": plugin["id"],
                    "entrypoint": "receive_metadata",
                    "payload": payload,
                    "requestedBy": actor_job_payload(actor or {}),
                    "reason": reason,
                },
            )
        )
    return {
        "receiverCount": len(receivers),
        "queuedJobs": jobs,
        "payloadSummary": {
            "entityType": payload.get("entityType"),
            "identity": payload.get("identity"),
            "fieldCount": len(payload.get("payload") or {}),
            "fields": sorted((payload.get("payload") or {}).keys()),
            "sourceProviders": ((payload.get("metadata") or {}).get("sourceProviders") or []),
        },
    }


def metadata_refresh_jobs(
    conn,
    *,
    movie_id: UUID | None = None,
    status: str = "",
    limit: int = 50,
) -> list[dict[str, Any]]:
    if not table_exists(conn, "background_jobs"):
        return []
    clauses = ["job_type = %s"]
    params: list[Any] = [METADATA_REFRESH_JOB_TYPE]
    if movie_id:
        clauses.append("payload->>'movieId' = %s")
        params.append(str(movie_id))
    if status:
        clauses.append("status = %s")
        params.append(status)
    where = " AND ".join(clauses)
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                id,
                job_type,
                status,
                requested_by,
                payload,
                result,
                error,
                created_at,
                started_at,
                finished_at
            FROM background_jobs
            WHERE {where}
            ORDER BY created_at DESC
            LIMIT %s
            """,
            (*params, limit),
        )
        rows = cur.fetchall()
    return [job_row(row) for row in rows]


def metadata_refresh_job_counts(conn, *, movie_id: UUID | None = None) -> dict[str, Any]:
    if not table_exists(conn, "background_jobs"):
        return {"total": 0, "byStatus": {}}
    clauses = ["job_type = %s"]
    params: list[Any] = [METADATA_REFRESH_JOB_TYPE]
    if movie_id:
        clauses.append("payload->>'movieId' = %s")
        params.append(str(movie_id))
    where = " AND ".join(clauses)
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT status, COUNT(*)::int AS count
            FROM background_jobs
            WHERE {where}
            GROUP BY status
            """,
            params,
        )
        rows = cur.fetchall()
    by_status = {str(row.get("status") or "unknown"): int(row.get("count") or 0) for row in rows}
    return {"total": sum(by_status.values()), "byStatus": by_status}


