    @flask_app.errorhandler(NextApiError)
    def handle_next_error(error: NextApiError):
        payload = {"status": "error", "error": str(error)}
        if error.code:
            payload["errorCode"] = error.code
        return response(payload, error.status_code)

    @flask_app.errorhandler(HTTPException)
    def handle_http_error(error: HTTPException):
        return response(
            {
                "status": "error",
                "error": error.description,
                "path": request.path,
            },
            error.code or 500,
        )

    @flask_app.errorhandler(psycopg.OperationalError)
    def handle_database_offline_error(error: psycopg.OperationalError):
        # QueryCanceled / LockNotAvailable are what this API's own
        # statement_timeout / lock_timeout (see connect()) raise when Postgres
        # is alive but a query ran long or lost a lock race — e.g. while a
        # metadata refresh briefly holds the global sync_state row. Present
        # that as "busy" with a short retry, not as an outage.
        busy = isinstance(error, (psycopg.errors.QueryCanceled, psycopg.errors.LockNotAvailable))
        if busy:
            flask_app.logger.warning("Database busy (query cancelled) on %s: %s", request.path, error)
        else:
            flask_app.logger.warning("Database connection failed on %s: %s", request.path, error)
        locale_codes = [item["locale"] for item in NEXT_I18N_LOCALES]
        best_locale = request.accept_languages.best_match(locale_codes, default=NEXT_I18N_DEFAULT_LOCALE)
        locale = normalize_next_locale(best_locale)
        if request.endpoint in _HTML_SHELL_ENDPOINTS:
            result = html_response(render_database_offline_page(locale, busy=busy))
        else:
            message = (
                next_translate(locale, "errors.databaseBusy", "DiscVault is busy right now — please try again in a moment")
                if busy
                else next_translate(locale, "errors.databaseOffline", "Database is temporarily unavailable")
            )
            result = jsonify(
                json_ready(
                    {
                        "status": "error",
                        "error": message,
                        "path": request.path,
                    }
                )
            )
        result.status_code = 503
        result.headers["Retry-After"] = "5" if busy else "20"
        return result

    @flask_app.errorhandler(Exception)
    def handle_unexpected_error(error: Exception):  # pragma: no cover - Flask integration
        flask_app.logger.exception("Unhandled Next API error on %s", request.path)
        return response({"status": "error", "error": str(error), "path": request.path}, 500)

    @flask_app.before_request
    def require_next_auth():
        if not (
            request.path == "/"
            or request.path.startswith(("/app", "/api/next", "/api/auth", "/.well-known"))
        ):
            return None
        if is_public_next_path(request.path):
            return None
        with connect() as conn:
            if not next_auth_effective_enabled(conn, table_exists):
                return None
            if next_auth_current_user(conn):
                return None
        return response(
            {
                "status": "error",
                "error": "Authentication required",
                "auth_required": True,
                "path": request.path,
            },
            401,
        )


    @flask_app.get("/api/next/health")
    def health():
        with connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT
                        current_database() AS database,
                        current_user AS user,
                        version() AS postgres_version,
                        now() AS checked_at
                    """
                )
                db = cur.fetchone()
            migrations = migration_overview(conn)
            artwork_purge = {"purgedLinks": 0, "purgedAssets": 0, "purgedFiles": 0}
            if migrations.get("state") == "ready":
                with conn.transaction():
                    artwork_purge = purge_expired_artwork_trash(conn)
        migration_state = migrations["state"]
        is_ready = migration_state == "ready"
        return response(
            {
                "status": "ok" if is_ready else "degraded",
                "service": "discvault-next-api",
                "version": build_version(),
                "sha": build_sha(),
                "database": db,
                "migrations": migrations,
                "maintenance": {"artworkTrash": artwork_purge},
            },
            200 if is_ready else 503,
        )

