                    cur.execute(
                        "DELETE FROM media_group_members WHERE group_id=%s AND user_id=%s",
                        (group_uuid, user_uuid),
                    )
                    cur.execute("UPDATE media_groups SET updated_at=now() WHERE id=%s", (group_uuid,))
