    @flask_app.get("/api/next/containers/lookup")
    def lookup_container_by_barcode():
        barcode = clean_text(request.args.get("barcode")) or ""
        requested_type = clean_text(request.args.get("type")) or ""
        if not barcode:
            raise NextApiError("barcode is required", 400)
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                (
                    "containers.view",
                    "containers.edit",
                    "collection.view",
                    "collection.import",
                    "collection.edit_all",
                ),
            )
            if not table_exists(conn, "containers"):
                raise NextApiError("Container table is not available", 503)
            type_clause = ""
            params: list[Any] = [barcode]
            if requested_type:
                type_clause = " AND container_type=%s"
                params.append(normalize_container_type(requested_type))
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT id, public_id, container_type, title, barcode, badge_label, year
                    FROM containers
                    WHERE barcode=%s{type_clause}
                    ORDER BY created_at ASC
                    LIMIT 1
                    """,
                    tuple(params),
                )
                row = cur.fetchone()
            if not row:
                return response({"status": "ok", "found": False, "container": None})
            member_count = 0
            if table_exists(conn, "container_movies"):
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT COUNT(*)::int AS n FROM container_movies WHERE container_id=%s",
                        (row["id"],),
                    )
                    member_count = int(cur.fetchone()["n"])
            can_edit = actor_has_any_permission(
                actor,
                ("containers.edit", "collection.edit_all", "collection.bulk_edit", "collection.import"),
            )
            return response(
                {
                    "status": "ok",
                    "found": True,
                    "canEdit": can_edit,
                    "container": {
                        "id": str(row["id"]),
                        "publicId": row.get("public_id"),
                        "containerType": row.get("container_type"),
                        "title": row.get("title"),
                        "barcode": row.get("barcode"),
                        "badgeLabel": row.get("badge_label"),
                        "year": row.get("year"),
                        "memberCount": member_count,
                    },
                }
            )

    @flask_app.get("/api/next/import/movie/resolve")
    def resolve_import_member_barcode():
        # Read-only preview for the box-set builder / container scan: classify a
        # scanned member barcode as an existing vault movie, metadata candidates,
        # or nothing — WITHOUT importing. Metadata plugin lookups are only fired
        # when includeCandidates is set, to keep live scan previews cheap.
        barcode = clean_text(request.args.get("barcode")) or ""
        title = clean_text(request.args.get("title") or request.args.get("query")) or ""
        year = clean_text(request.args.get("year")) or ""
        include_candidates = str(request.args.get("includeCandidates") or "").strip().lower() in {"1", "true", "yes"}
        if not barcode and not title:
            raise NextApiError("barcode or title is required", 400)
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                (
                    "collection.add",
                    "collection.add_own",
                    "collection.import",
                    "collection.edit_all",
                    "metadata.search",
                ),
            )
            if not table_exists(conn, "movies"):
                raise NextApiError("Movie table is not available", 503)
            if barcode:
                visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m")
                with conn.cursor() as cur:
                    cur.execute(
                        f"""
                        SELECT
                            m.id,
                            m.public_id,
                            m.barcode,
                            m.title,
                            m.year,
                            m.metadata->>'poster_url' AS poster_url
                        FROM movies m
                        WHERE m.barcode=%s
                          AND {visibility_where}
                        ORDER BY m.created_at ASC
                        LIMIT 1
                        """,
                        (barcode, *visibility_params),
                    )
                    existing = cur.fetchone()
                if existing:
                    return response(
                        {
                            "status": "ok",
                            "state": "existingMovie",
                            "movie": {
                                "id": str(existing["id"]),
                                "publicId": existing.get("public_id"),
                                "barcode": existing.get("barcode"),
                                "title": existing.get("title"),
                                "year": existing.get("year"),
                                "posterUrl": existing.get("poster_url"),
                            },
                        }
                    )
            candidates: list[dict[str, Any]] = []
            if include_candidates:
                if not table_exists(conn, "plugins"):
                    raise NextApiError("Plugin registry table is not available", 503)
                lookup_payload = {
                    "barcode": barcode,
                    "title": title,
                    "year": year,
                    "detectBoxSets": False,
                    "previewMode": True,
                }
                try:
                    metadata_result = lookup_metadata_sources(conn, lookup_payload, actor)
                except Exception:  # pragma: no cover - preview must never hard-fail
                    metadata_result = {}
                results = metadata_result.get("results") if isinstance(metadata_result.get("results"), list) else []
                for item in results:
                    if not isinstance(item, dict):
                        continue
                    summary = metadata_result_summary(item)
                    candidate_title = clean_text(summary.get("title") or summary.get("name"))
                    if not candidate_title:
                        continue
                    candidates.append(
                        {
                            "title": candidate_title,
                            "year": summary.get("year"),
                            "pluginId": summary.get("pluginId"),
                        }
                    )
                    if len(candidates) >= 8:
                        break
            state = "candidates" if candidates else "none"
            return response(
                {
                    "status": "ok",
                    "state": state,
                    "candidateCount": len(candidates),
                    "candidates": candidates,
                }
            )

    @flask_app.post("/api/next/import/release-details/search")
    def search_import_release_details():
        """The v2 fallback for a disc the local route could not identify.

        The catalog-first order is unchanged: this runs only after the normal
        metadata lookup produced nothing for the scanned barcode. It asks
        MovieVault's anonymous release-details resolver directly - by barcode,
        or by the title the user typed once the barcode led nowhere - and hands
        back whatever it answers, including a `candidates` list of pressings of
        one film for the user to choose between.

        A failure is never reported as "not in the catalogue": the outcome
        carries a `failureKind` so the client can say what actually happened,
        and `retryable` marks the failures where waiting costs nothing.
        """
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Release details search body must be an object", 400)
        barcode = normalize_barcode(clean_text(body.get("barcode")) or "")
        title = clean_text(body.get("title") or body.get("query")) or ""
        edition = clean_text(body.get("edition")) or ""
        media_format = clean_text(body.get("format") or body.get("mediaFormat")) or ""
        year_text = clean_text(body.get("year")) or ""
        year = int(year_text) if year_text.isdigit() and 1870 <= int(year_text) <= 2200 else None
        if not barcode and not title:
            raise NextApiError("barcode or title is required", 400)
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                (
                    "metadata.search",
                    "collection.add",
                    "collection.add_own",
                    "collection.import",
                    "collection.edit_all",
                ),
            )
            settings = movievault_v2_release_details_settings(conn)
            # The Add flow waits longer than a metadata refresh does; an
            # operator who configured an even longer budget keeps theirs.
            configured_attempts = settings.get("releaseDetailsPollAttempts")
            if (
                not isinstance(configured_attempts, int)
                or isinstance(configured_attempts, bool)
                or configured_attempts < ADD_FLOW_RELEASE_DETAILS_POLL_ATTEMPTS
            ):
                settings = {
                    **settings,
                    "releaseDetailsPollAttempts": ADD_FLOW_RELEASE_DETAILS_POLL_ATTEMPTS,
                }
            # A barcode is the more specific question, so it is asked first and
            # the title rides along as a hint. Only a request with no barcode at
            # all goes to the title entry point.
            entrypoint = "resolve" if barcode else "search"
            request_payload: dict[str, Any] = {}
            try:
                if barcode:
                    request_payload = {"barcode": barcode}
                    if title:
                        request_payload["title"] = title
                    if year is not None:
                        request_payload["year"] = year
                    if edition:
                        request_payload["edition"] = edition
                    if media_format:
                        request_payload["format"] = media_format
                    result = resolve_release_details(settings, request_payload)
                else:
                    request_payload = {"title": title}
                    if year is not None:
                        request_payload["year"] = year
                    if edition:
                        request_payload["edition"] = edition
                    if media_format:
                        request_payload["format"] = media_format
                    result = search_release_details(settings, request_payload)
            except MovieVaultV2Error as exc:
                result = {
                    "contractVersion": "release-technical-1",
                    "status": "failed",
                    "errorCode": exc.code,
                }
            payload = release_details_search_payload(result, entrypoint=entrypoint)
            audit_event(
                conn,
                event_type="metadata.release_details_search",
                category="metadata",
                actor=actor,
                target_type="release_details_search",
                target_id=None,
                summary=f"MovieVault v2 {entrypoint} for {barcode or title}",
                metadata={
                    "entrypoint": entrypoint,
                    "barcode": barcode,
                    "title": title,
                    "year": year,
                    "status": payload["status"],
                    "errorCode": payload.get("errorCode"),
                    "failureKind": payload.get("failureKind"),
                    "candidateCount": len(payload.get("releases") or []),
                    "verificationStatus": payload.get("verificationStatus"),
                },
            )
        return response({"status": "ok", "result": payload})

    @flask_app.post("/api/next/movies/<movie_id>/collections/<collection_id>")
    def add_movie_to_collection(movie_id: str, collection_id: str):
        movie_uuid = parse_uuid(movie_id, "movieId")
        collection_uuid = parse_uuid(collection_id, "collectionId")
        if not movie_uuid or not collection_uuid:
            raise NextApiError("movieId and collectionId are required", 400)
        with connect() as conn:
            actor = require_any_next_permission(conn, ("containers.edit", "collection.bulk_edit"))
            if not table_exists(conn, "collection_items"):
                raise NextApiError("Collection items are not available yet", 503)
            require_existing_movie_ids(conn, [movie_uuid])
            if container_type_for_id(conn, collection_uuid) != "collection":
                raise NextApiError("Target container must be a collection", 400)
            changed = 0
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT COALESCE(MAX(sort_order), 0)::int AS max_sort FROM collection_items WHERE collection_id=%s",
                        (collection_uuid,),
                    )
                    sort_order = int(cur.fetchone()["max_sort"]) + 1
                    cur.execute(
                        """
                        INSERT INTO collection_items (collection_id, item_type, item_id, sort_order, created_at)
                        VALUES (%s, 'movie', %s, %s, now())
                        ON CONFLICT (collection_id, item_type, item_id) DO NOTHING
                        """,
                        (collection_uuid, movie_uuid, sort_order),
                    )
                    changed = cur.rowcount
                    cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (collection_uuid,))
                audit_event(
                    conn,
                    event_type="collection.movie_added",
                    category="admin",
                    actor=actor,
                    target_type="container",
                    target_id=collection_uuid,
                    summary="Added movie to collection",
                    metadata={"movieId": str(movie_uuid), "changed": changed},
                )
            return response(
                {
                    "status": "ok",
                    "operation": "add",
                    "changed": changed,
                    "movieId": str(movie_uuid),
                    "collectionId": str(collection_uuid),
                    "detail": container_detail_entity(conn, collection_uuid),
                    "actions": movie_library_action_targets(conn, movie_uuid, actor),
                }
            )

