    @flask_app.post("/api/next/locations/<location_id>/backdrop/upload")
    def location_backdrop_upload(location_id: str):
        location_uuid = parse_uuid(location_id, "locationId")
        if not location_uuid:
            raise NextApiError("locationId is required", 400)
        if request.content_length and request.content_length > MAX_ARTWORK_UPLOAD_BYTES:
            raise NextApiError("Artwork upload may not exceed 20 MB", 413)
        upload, _inferred = uploaded_artwork_file()
        with connect() as conn:
            actor = require_next_permission(conn, "containers.edit")
            existing = location_entity(conn, location_uuid)
            if not existing:
                raise NextApiError("Location not found", 404)
            upload_info = save_uploaded_artwork_file(upload, kind="backdrop")
            with conn.transaction():
                asset = store_uploaded_artwork_asset(
                    conn,
                    upload_info=upload_info,
                    kind="backdrop",
                    source="location_upload",
                    actor=actor,
                )
                backdrop_url = media_asset_public_url(asset)
                metadata = existing.get("metadata") if isinstance(existing.get("metadata"), dict) else {}
                metadata = dict(metadata)
                metadata["backdrop_url"] = backdrop_url
                metadata["backdrop_asset_id"] = str(asset.get("id")) if asset.get("id") else None
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE locations SET metadata=%s, updated_at=now() WHERE id=%s",
                        (Jsonb(json_ready(metadata)), location_uuid),
                    )
                audit_event(
                    conn,
                    event_type="location.backdrop_uploaded",
                    category="admin",
                    actor=actor,
                    target_type="location",
                    target_id=location_uuid,
                    summary=f"Uploaded location backdrop for {existing.get('name') or 'location'}",
                    metadata={
                        "publicId": existing.get("public_id"),
                        "locationName": existing.get("name"),
                        "mediaId": str(asset.get("id")) if asset.get("id") else None,
                        "backdropUrl": backdrop_url,
                    },
                )
                emit_location_change(conn, location_uuid, operation="upsert")
            detail = location_detail_entity(conn, location_uuid)
        return response(
            {
                "status": "ok",
                "detail": detail,
                "backdropUrl": (detail or {}).get("backdrop_url"),
            }
        )

    @flask_app.post("/api/next/bulk/containers/<container_id>/movies")
    def bulk_container_movies(container_id: str):
        container_uuid = parse_uuid(container_id, "containerId")
        if not container_uuid:
            raise NextApiError("containerId is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Bulk container request body must be an object", 400)
        movie_ids = parse_uuid_list(body.get("movieIds") or body.get("movie_ids"), "movieIds")
        if not movie_ids:
            raise NextApiError("movieIds must be a non-empty array", 400)
        target_type = str(body.get("targetType") or body.get("target_type") or "").strip()
        if target_type not in {"box_set", "vault", ""}:
            raise NextApiError("targetType must be box_set or vault", 400)
        operation = str(body.get("operation") or "add").strip().lower()
        if operation not in {"add", "remove"}:
            raise NextApiError("operation must be add or remove", 400)
        with connect() as conn:
            require_next_permission(conn, "containers.edit")
            if not table_exists(conn, "container_movies"):
                raise NextApiError("Container movie links are not available yet", 503)
            container_type = container_type_for_id(conn, container_uuid)
            if container_type not in {"box_set", "vault"}:
                raise NextApiError("Target container must be a box-set or vault", 400)
            if target_type and container_type != target_type:
                raise NextApiError("Target container type does not match requested action", 400)
            require_existing_movie_ids(conn, movie_ids)
            changed = 0
            with conn.transaction():
                with conn.cursor() as cur:
                    if operation == "remove":
                        cur.execute(
                            "DELETE FROM container_movies WHERE container_id=%s AND movie_id = ANY(%s)",
                            (container_uuid, movie_ids),
                        )
                        changed = cur.rowcount
                        if changed:
                            cur.execute(
                                "UPDATE containers SET primary_movie_id=NULL WHERE id=%s AND primary_movie_id = ANY(%s)",
                                (container_uuid, movie_ids),
                            )
                    else:
                        cur.execute(
                            "SELECT COALESCE(MAX(sort_order), 0)::int AS max_sort FROM container_movies WHERE container_id=%s",
                            (container_uuid,),
                        )
                        sort_order = int(cur.fetchone()["max_sort"])
                        for movie_id in movie_ids:
                            sort_order += 1
                            cur.execute(
                                """
                                INSERT INTO container_movies (container_id, movie_id, sort_order, created_at)
                                VALUES (%s, %s, %s, now())
                                ON CONFLICT (container_id, movie_id) DO NOTHING
                                """,
                                (container_uuid, movie_id, sort_order),
                            )
                            changed += cur.rowcount
                    cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (container_uuid,))
                if changed:
                    emit_container_membership_change(conn, container_uuid)
            capture_collection_value_snapshot(conn, actor)
        return response(
            {
                "status": "ok",
                "operation": operation,
                "changed": changed,
                "requested": len(movie_ids),
                "containerId": str(container_uuid),
                "containerType": container_type,
            }
        )

    @flask_app.post("/api/next/bulk/collections/<collection_id>/items")
    def bulk_collection_items(collection_id: str):
        collection_uuid = parse_uuid(collection_id, "collectionId")
        if not collection_uuid:
            raise NextApiError("collectionId is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Bulk collection request body must be an object", 400)
        movie_ids = parse_uuid_list(body.get("movieIds") or body.get("movie_ids"), "movieIds")
        container_ids = parse_uuid_list(body.get("containerIds") or body.get("container_ids"), "containerIds")
        container_ids = [item for item in container_ids if item != collection_uuid]
        if not movie_ids and not container_ids:
            raise NextApiError("movieIds or containerIds must be supplied", 400)
        operation = str(body.get("operation") or "add").strip().lower()
        if operation not in {"add", "remove"}:
            raise NextApiError("operation must be add or remove", 400)
        with connect() as conn:
            require_any_next_permission(conn, ("containers.edit", "collection.bulk_edit"))
            if not table_exists(conn, "collection_items"):
                raise NextApiError("Collection items are not available yet", 503)
            target_type = container_type_for_id(conn, collection_uuid)
            if target_type != "collection":
                raise NextApiError("Target container must be a collection", 400)
            require_existing_movie_ids(conn, movie_ids)
            changed = 0
            with conn.transaction():
                container_types = container_types_for_ids(conn, container_ids, lock=True)
                allowed_container_ids = [
                    item for item in container_ids if container_types.get(item) in {"box_set", "vault", "collection"}
                ]
                if operation == "add":
                    # Filtering the direct self-reference above is not enough:
                    # adding A to B while B already sits inside A closes a loop
                    # just as well. Contract §4b.7 rejects the cycle on write,
                    # matching what collectionItem.upsert does on the sync path.
                    ancestors = collection_ancestor_container_ids(conn, collection_uuid)
                    for item in allowed_container_ids:
                        if item in ancestors:
                            raise NextApiError(
                                "Adding this container would create a collection membership cycle",
                                400,
                            )
                requested = len(movie_ids) + len(allowed_container_ids)
                with conn.cursor() as cur:
                    if operation == "remove":
                        if movie_ids:
                            cur.execute(
                                """
                                DELETE FROM collection_items
                                WHERE collection_id=%s AND item_type='movie' AND item_id = ANY(%s)
                                """,
                                (collection_uuid, movie_ids),
                            )
                            changed += cur.rowcount
                        if allowed_container_ids:
                            cur.execute(
                                """
                                DELETE FROM collection_items
                                WHERE collection_id=%s AND item_type = ANY(%s::text[]) AND item_id = ANY(%s)
                                """,
                                (collection_uuid, ["box_set", "vault", "collection"], allowed_container_ids),
                            )
                            changed += cur.rowcount
                    else:
                        cur.execute(
                            "SELECT COALESCE(MAX(sort_order), 0)::int AS max_sort FROM collection_items WHERE collection_id=%s",
                            (collection_uuid,),
                        )
                        sort_order = int(cur.fetchone()["max_sort"])
                        for movie_id in movie_ids:
                            sort_order += 1
                            cur.execute(
                                """
                                INSERT INTO collection_items (collection_id, item_type, item_id, sort_order, created_at)
                                VALUES (%s, 'movie', %s, %s, now())
                                ON CONFLICT (collection_id, item_type, item_id) DO NOTHING
                                """,
                                (collection_uuid, movie_id, sort_order),
                            )
                            changed += cur.rowcount
                        for item_id in allowed_container_ids:
                            sort_order += 1
                            item_type = container_types[item_id]
                            cur.execute(
                                """
                                INSERT INTO collection_items (collection_id, item_type, item_id, sort_order, created_at)
                                VALUES (%s, %s, %s, %s, now())
                                ON CONFLICT (collection_id, item_type, item_id) DO NOTHING
                                """,
                                (collection_uuid, item_type, item_id, sort_order),
                            )
                            changed += cur.rowcount
                    cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (collection_uuid,))
        return response(
            {
                "status": "ok",
                "operation": operation,
                "changed": changed,
                "requested": requested,
                "collectionId": str(collection_uuid),
            }
        )

    @flask_app.post("/api/next/bulk/delete")
    def bulk_delete_collection_items():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Bulk delete body must be an object", 400)
        movie_ids = parse_uuid_list(body.get("movieIds") or body.get("movie_ids"), "movieIds", maximum=500)
        container_ids = parse_uuid_list(body.get("containerIds") or body.get("container_ids"), "containerIds", maximum=500)
        if not movie_ids and not container_ids:
            raise NextApiError("movieIds or containerIds must be supplied", 400)
        if body.get("confirm") != "delete-selected":
            raise NextApiError("Bulk delete requires confirm=delete-selected", 400)
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                ("collection.delete_all", "collection.delete_own", "collection.delete_group", "containers.delete"),
            )
            permissions = {str(item) for item in actor.get("permissions") or []}
            can_delete_containers = actor.get("role") == "owner" or "*" in permissions or "containers.delete" in permissions
            delete_container_members = actor_delete_container_members_enabled(conn, actor)
            if container_ids and not can_delete_containers:
                raise NextApiError("Permission required: containers.delete", 403)
            if movie_ids:
                for movie_uuid in movie_ids:
                    movie = movie_entity(conn, movie_uuid)
                    if not movie:
                        raise NextApiError(f"Movie not found: {movie_uuid}", 404)
                    if not actor_can_delete_movie(actor, movie):
                        raise NextApiError("Permission required: collection.delete_all", 403)
            if container_ids:
                for container_uuid in container_ids:
                    container = container_entity(conn, container_uuid)
                    if not container:
                        raise NextApiError(f"Container not found: {container_uuid}", 404)
            deleted_movies: list[dict[str, Any]] = []
            deleted_containers: list[dict[str, Any]] = []
            deleted_counts: dict[str, int] = {}
            with conn.transaction():
                for movie_uuid in movie_ids:
                    movie, deleted = delete_movie_records(conn, movie_uuid)
                    deleted_movies.append({"id": str(movie_uuid), "title": movie.get("title"), "deleted": deleted})
                    for key, value in deleted.items():
                        deleted_counts[key] = deleted_counts.get(key, 0) + int(value or 0)
                    revision = next_revision(conn) if table_exists(conn, "sync_state") else 0
                    if revision and table_exists(conn, "sync_changes"):
                        sync_change(
                            conn,
                            revision=revision,
                            entity_type="movie",
                            entity_id=str(movie_uuid),
                            operation="delete",
                            payload={
                                "id": str(movie_uuid),
                                "title": movie.get("title"),
                                "clientId": "next-app",
                                "clientMutationId": f"bulk-delete-movie-{uuid.uuid4()}",
                                "actor": actor_job_payload(actor),
                            },
                        )
                for container_uuid in container_ids:
                    container, deleted = delete_container_records(
                        conn,
                        container_uuid,
                        delete_members=delete_container_members,
                    )
                    deleted_containers.append(
                        {
                            "id": str(container_uuid),
                            "title": container.get("title"),
                            "containerType": container.get("container_type"),
                            "deleteMembers": delete_container_members,
                            "deleted": deleted,
                        }
                    )
                    for key, value in deleted.items():
                        deleted_counts[key] = deleted_counts.get(key, 0) + int(value or 0)
                audit_event(
                    conn,
                    event_type="collection.bulk_deleted",
                    category="admin",
                    actor=actor,
                    target_type="bulk",
                    summary="Deleted selected movies and containers",
                    metadata={
                        "movieIds": [str(item) for item in movie_ids],
                        "containerIds": [str(item) for item in container_ids],
                        "deleteContainerMembers": delete_container_members,
                        "deleted": deleted_counts,
                    },
                )
        return response(
            {
                "status": "ok",
                "deleted": deleted_counts,
                "movies": deleted_movies,
                "containers": deleted_containers,
                "deleteContainerMembers": delete_container_members,
                "requested": len(movie_ids) + len(container_ids),
            }
        )

    @flask_app.delete("/api/next/containers/<container_id>/movies/<movie_id>")
    def remove_container_movie(container_id: str, movie_id: str):
        container_uuid = parse_uuid(container_id, "containerId")
        movie_uuid = parse_uuid(movie_id, "movieId")
        if not container_uuid or not movie_uuid:
            raise NextApiError("containerId and movieId are required", 400)
        with connect() as conn:
            require_next_permission(conn, "containers.edit")
            if not table_exists(conn, "container_movies"):
                raise NextApiError("Container movie links are not available yet", 503)
            container_type = container_type_for_id(conn, container_uuid)
            if container_type not in {"box_set", "vault"}:
                raise NextApiError("Target container must be a box-set or vault", 400)
            changed = 0
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute(
                        "DELETE FROM container_movies WHERE container_id=%s AND movie_id=%s",
                        (container_uuid, movie_uuid),
                    )
                    changed = cur.rowcount
                    if changed:
                        cur.execute(
                            "UPDATE containers SET primary_movie_id=NULL WHERE id=%s AND primary_movie_id=%s",
                            (container_uuid, movie_uuid),
                        )
                    cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (container_uuid,))
                if changed:
                    emit_container_membership_change(conn, container_uuid)
            detail = container_detail_entity(conn, container_uuid)
            capture_collection_value_snapshot(conn, actor)
        if not detail:
            raise NextApiError("Container not found", 404)
        return response(
            {
                "status": "ok",
                "changed": changed,
                "containerId": str(container_uuid),
                "movieId": str(movie_uuid),
                "detail": detail,
            }
        )

    @flask_app.patch("/api/next/containers/<container_id>/movies/order")
    def reorder_container_movies(container_id: str):
        container_uuid = parse_uuid(container_id, "containerId")
        if not container_uuid:
            raise NextApiError("containerId is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Container order request body must be an object", 400)
        movie_ids = parse_uuid_list(body.get("movieIds") or body.get("movie_ids"), "movieIds", maximum=1000)
        if not movie_ids:
            raise NextApiError("movieIds must be a non-empty array", 400)
        with connect() as conn:
            require_next_permission(conn, "containers.edit")
            if not table_exists(conn, "container_movies"):
                raise NextApiError("Container movie links are not available yet", 503)
            container_type = container_type_for_id(conn, container_uuid)
            if container_type not in {"box_set", "vault"}:
                raise NextApiError("Target container must be a box-set or vault", 400)
            with conn.cursor() as cur:
                cur.execute("SELECT movie_id FROM container_movies WHERE container_id=%s", (container_uuid,))
                current = {row["movie_id"] for row in cur.fetchall()}
            missing = [str(item) for item in movie_ids if item not in current]
            if missing:
                raise NextApiError(f"Movie is not linked to this container: {', '.join(missing)}", 400)
            omitted = [str(item) for item in current if item not in set(movie_ids)]
            if omitted:
                raise NextApiError("movieIds must include every linked movie for this container", 400)
            with conn.transaction():
                with conn.cursor() as cur:
                    for index, movie_uuid in enumerate(movie_ids, start=1):
                        cur.execute(
                            "UPDATE container_movies SET sort_order=%s WHERE container_id=%s AND movie_id=%s",
                            (index, container_uuid, movie_uuid),
                        )
                    cur.execute("UPDATE containers SET updated_at=now() WHERE id=%s", (container_uuid,))
                emit_container_membership_change(conn, container_uuid)
            detail = container_detail_entity(conn, container_uuid)
        return response({"status": "ok", "detail": detail})

