    @flask_app.post("/api/next/api/v1/containers")
    def public_api_create_container():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Container request body must be an object", 400)
        container_type = normalize_container_type(body.get("containerType", body.get("container_type")))
        payload = container_payload(body, container_type=container_type)
        container_uuid = uuid.uuid4()
        public_id = clean_text(body.get("publicId") or body.get("public_id")) or f"api-container-{container_uuid.hex[:12]}"
        if len(public_id) > 160:
            raise NextApiError("publicId must be 160 characters or fewer", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "api.write")
            if not table_exists(conn, "containers"):
                raise NextApiError("Container table is not available", 503)
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute("SELECT id FROM containers WHERE public_id=%s", (public_id,))
                    if cur.fetchone():
                        raise NextApiError("A container with this public id already exists", 409)
                    if container_type == "box_set" and payload["barcode"]:
                        lock_box_set_barcode(conn, payload["barcode"])
                        cur.execute(
                            "SELECT id FROM containers WHERE barcode=%s AND container_type='box_set' LIMIT 1",
                            (payload["barcode"],),
                        )
                        if cur.fetchone():
                            raise NextApiError("A box-set with this barcode already exists", 409)
                    cur.execute(
                        """
                        INSERT INTO containers (
                            id, public_id, container_type, title, barcode, badge_label, year, description, location_id, owner_id, estimated_value, estimated_value_currency, metadata, created_at, updated_at
                        )
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, now(), now())
                        """,
                        (
                            container_uuid,
                            public_id,
                            container_type,
                            payload["title"],
                            payload["barcode"],
                            payload["badge_label"],
                            payload["year"],
                            payload["description"],
                            payload["location_id"],
                            actor_or_instance_owner_id(conn, actor),
                            payload["estimated_value"],
                            payload["estimated_value_currency"],
                            Jsonb(json_ready(payload["metadata"])),
                        ),
                    )
                audit_api_interaction(
                    conn,
                    actor,
                    command="create_container",
                    event_type="api.container_created",
                    target_type="container",
                    target_id=container_uuid,
                    summary=f"Created {container_type} {payload['title']} through the public API",
                    request_payload={"containerType": container_type, "title": payload["title"], "barcode": payload["barcode"]},
                    metadata={
                        "containerType": container_type,
                        "publicId": public_id,
                        "title": payload["title"],
                        "barcode": payload["barcode"],
                        "year": payload["year"],
                        "badgeLabel": payload["badge_label"],
                    },
                )
                emit_container_change(conn, container_uuid, operation="upsert")
            detail = container_detail_entity(conn, container_uuid)
            capture_collection_value_snapshot(conn, actor)
        return response({"status": "ok", "detail": detail}, 201)

