    @flask_app.patch("/api/next/api/v1/containers/<container_id>")
    def public_api_update_container(container_id: str):
        container_uuid = parse_uuid(container_id, "containerId")
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Container request body must be an object", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "api.write")
            existing = container_entity(conn, container_uuid)
            if not existing:
                raise NextApiError("Container not found", 404)
            if not actor_can_edit_visible_container(conn, actor, container_uuid):
                raise NextApiError("Permission required: containers.edit", 403)
            payload = container_payload(body, existing=existing, container_type=existing.get("container_type"))
            receiver_payload = container_receiver_payload(conn, existing, payload)
            receiver_summary: dict[str, Any] = {"skipped": True, "reason": "no_receiver_fields_changed"}
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        UPDATE containers
                        SET title=%s,
                            barcode=%s,
                            badge_label=%s,
                            year=%s,
                            description=%s,
                            location_id=%s,
                            estimated_value=%s,
                            estimated_value_currency=%s,
                            metadata=%s,
                            updated_at=now()
                        WHERE id=%s
                        """,
                        (
                            payload["title"],
                            payload["barcode"],
                            payload["badge_label"],
                            payload["year"],
                            payload["description"],
                            payload["location_id"],
                            payload["estimated_value"],
                            payload["estimated_value_currency"],
                            Jsonb(json_ready(payload["metadata"])),
                            container_uuid,
                        ),
                    )
                audit_api_interaction(
                    conn,
                    actor,
                    command="update_container",
                    event_type="api.container_updated",
                    target_type="container",
                    target_id=container_uuid,
                    summary=f"Updated container {payload['title']} through the public API",
                    request_payload={"title": payload["title"], "barcode": payload["barcode"], "containerType": existing.get("container_type")},
                    metadata={
                        "containerType": existing.get("container_type"),
                        "publicId": existing.get("public_id"),
                        "title": payload["title"],
                        "previousTitle": existing.get("title"),
                        "barcode": payload["barcode"],
                        "previousBarcode": existing.get("barcode"),
                        "year": payload["year"],
                        "badgeLabel": payload["badge_label"],
                    },
                )
                if receiver_payload:
                    try:
                        receiver_summary = push_receiver_payload_to_receivers(conn, payload=receiver_payload, actor=actor)
                    except Exception as exc:
                        receiver_summary = {"status": "error", "error": str(exc)}
                    audit_event(
                        conn,
                        event_type="metadata.receiver_pushed",
                        category="metadata",
                        actor=actor,
                        target_type="container",
                        target_id=container_uuid,
                        summary=f"Pushed API box-set edit to receiver plugins for {payload['title']}",
                        metadata={
                            "containerType": existing.get("container_type"),
                            "title": payload["title"],
                            "barcode": payload["barcode"],
                            "changedFields": (receiver_payload.get("metadata") or {}).get("changedFields") or [],
                            "receiverSummary": receiver_summary,
                        },
                    )
                emit_container_change(conn, container_uuid, operation="upsert")
            detail = container_detail_entity(conn, container_uuid, actor=actor)
            capture_collection_value_snapshot(conn, actor)
        return response({"status": "ok", "detail": detail, "receiverSummary": receiver_summary})

