    @flask_app.get("/api/next/plugins/<plugin_id>/attribution-logo")
    def plugin_attribution_logo(plugin_id: str):
        """A source's own logo, served from that source's own directory.

        Not through the shared frontend asset allowlist: that list is a fixed set
        of DiscVault's own files, and a per-source credit has to work for a
        plugin nobody has written yet. The file therefore ships inside the
        plugin, and only a file the plugin's manifest names can be read.

        Three things bound this: the plugin must be installed and enabled (the
        same condition under which its credit is displayed at all), the manifest
        must name a bare filename, and the resolved path must still be inside the
        plugin directory after following symlinks. The last one is the one that
        matters -- `Path(name).name` alone would still let a symlink inside the
        plugin point anywhere on the disk.
        """
        plugin_id = str(plugin_id or "").strip()
        if not plugin_id or not PLUGIN_ID_PATTERN.match(plugin_id):
            raise NextApiError("Plugin id is required", 400)
        with connect() as conn:
            if not table_exists(conn, "plugins"):
                raise NextApiError("Asset not found", 404)
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT manifest, source_path
                    FROM plugins
                    WHERE id = %s AND installed = true AND enabled = true
                    """,
                    (plugin_id,),
                )
                row = cur.fetchone()
        if not row:
            raise NextApiError("Asset not found", 404)
        manifest = row.get("manifest") if isinstance(row.get("manifest"), dict) else {}
        attribution = plugin_attribution(manifest)
        source_path = str(row.get("source_path") or "")
        if not attribution or not attribution["logo"] or not source_path:
            raise NextApiError("Asset not found", 404)
        plugin_root = Path(source_path).resolve()
        path = (plugin_root / attribution["logo"]).resolve()
        if not path.is_relative_to(plugin_root) or not path.is_file():
            raise NextApiError("Asset not found", 404)
        return send_file(
            path,
            mimetype=mimetypes.guess_type(path.name)[0] or "application/octet-stream",
        )

    @flask_app.get("/api/next/plugins/<plugin_id>/export")
    def export_plugin(plugin_id: str):
        plugin_id = str(plugin_id or "").strip()
        if not plugin_id:
            raise NextApiError("Plugin id is required", 400)
        with connect() as conn:
            require_any_next_permission(conn, PLUGIN_REGISTRY_MANAGE_PERMISSIONS)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)
            if table_exists(conn, "metadata_plugins"):
                sync_metadata_plugin_registry(conn)
            else:
                sync_plugin_registry(conn, table_exists, Jsonb)
            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            plugin = next((item for item in registry["plugins"] if item["id"] == plugin_id), None)
            if not plugin:
                raise NextApiError("Plugin not found", 404)
            require_any_next_permission(conn, plugin_manage_permissions(plugin))
            file_name = plugin_archive_filename(plugin)
            handle = tempfile.NamedTemporaryFile(delete=False, suffix=".zip")
            archive_path = Path(handle.name)
            handle.close()
            write_plugin_archive(plugin, archive_path)

        @after_this_request
        def cleanup_plugin_archive(response_obj):
            try:
                archive_path.unlink(missing_ok=True)
            except OSError:
                pass
            return response_obj

        return send_file(
            archive_path,
            mimetype="application/zip",
            as_attachment=True,
            download_name=file_name,
        )

    @flask_app.post("/api/next/plugins/import")
    def import_plugin_zip():
        with connect() as conn:
            # Importing a plugin writes a new plugin.py to disk, which
            # discover_plugins() executes unconditionally on the next
            # registry sync below -- this is the confirmed RCE path, so it
            # must require the owner/admin-only plugin install boundary, not
            # the broad PLUGIN_REGISTRY_MANAGE_PERMISSIONS tuple.
            actor = require_plugin_registry_install_permission(conn)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)

            package_digest: str | None = None
            upload_size: int | None = None
            install_target: Path | None = None
            previous_source_path: Path | None = None
            previous_trash_path: Path | None = None
            previous_trash_root: Path | None = None
            install_started = False
            import_succeeded = False
            failure_stage = "upload"
            try:
                with tempfile.TemporaryDirectory(
                    prefix="discvault-plugin-import-",
                    ignore_cleanup_errors=True,
                ) as temp_dir_name:
                    temp_dir = Path(temp_dir_name)
                    upload_path = uploaded_plugin_file_path(temp_dir)
                    upload_size = upload_path.stat().st_size
                    package_digest = plugin_package_sha256(upload_path)
                    failure_stage = "extract"
                    extracted_dir = temp_dir / "extracted"
                    extracted_dir.mkdir(parents=True, exist_ok=True)
                    try:
                        safe_extract_plugin_zip(upload_path, extracted_dir)
                    except zipfile.BadZipFile as exc:
                        raise NextApiError("Plugin upload is not a valid ZIP file", 400) from exc
                    plugin_root = locate_plugin_root(extracted_dir)
                    failure_stage = "validate"
                    manifest = validate_import_plugin_root(plugin_root)
                    install_target = plugin_install_target_path(manifest)
                    failure_stage = "backup"
                    previous_source_path, previous_trash_path, previous_trash_root = move_plugin_source_to_trash(
                        {"sourcePath": str(install_target)}
                    )
                    failure_stage = "install"
                    install_started = True
                    installed_path = install_plugin_from_root(plugin_root, manifest)
                    failure_stage = "registry_sync"
                    with conn.transaction():
                        if table_exists(conn, "metadata_plugins"):
                            sync_metadata_plugin_registry(conn)
                        else:
                            sync_plugin_registry(conn, table_exists, Jsonb)

                        imported_plugin_id = str(manifest["id"])
                        with conn.cursor() as cur:
                            cur.execute(
                                "SELECT categories FROM plugins WHERE id=%s",
                                (imported_plugin_id,),
                            )
                            imported_row = cur.fetchone()
                        imported_categories = (
                            (imported_row.get("categories") if imported_row else None) or []
                        )
                        imported_is_metadata_plugin = bool(
                            {"metadata_source", "metadata_receiver"}.intersection(
                                set(imported_categories)
                            )
                        )
                        with conn.cursor() as cur:
                            if imported_is_metadata_plugin and table_exists(conn, "metadata_plugins"):
                                cur.execute(
                                    "UPDATE metadata_plugins SET enabled=true, updated_at=now() WHERE id=%s",
                                    (imported_plugin_id,),
                                )
                            cur.execute(
                                "UPDATE plugins SET enabled=true, updated_at=now() WHERE id=%s",
                                (imported_plugin_id,),
                            )
                        audit_event(
                            conn,
                            event_type="plugin.imported",
                            category="plugins",
                            actor=actor,
                            target_type="plugin",
                            target_id=str(manifest["id"]),
                            summary=f"Imported plugin {manifest['id']} {manifest.get('version')}",
                            metadata={
                                "pluginId": manifest["id"],
                                "name": manifest.get("name"),
                                "version": manifest.get("version"),
                                "categories": manifest.get("categories"),
                                "installedPath": str(installed_path),
                                "enabled": True,
                                "packageSha256": package_digest,
                                "uploadSizeBytes": upload_size,
                            },
                        )
                    import_succeeded = True
            except Exception as exc:
                # Once installation starts, every later failure must remove the
                # new executable and restore the previous plugin before failing.
                if install_started and install_target and install_target.exists():
                    try:
                        shutil.rmtree(install_target)
                    except OSError:
                        app.logger.error("Failed to remove a partially imported plugin")
                backup_available = bool(previous_trash_path and previous_trash_path.exists())
                try:
                    restored_previous = restore_plugin_source(previous_source_path, previous_trash_path)
                except (OSError, shutil.Error):
                    app.logger.error("Failed to restore the previous plugin after import failure")
                else:
                    if backup_available and not restored_previous:
                        app.logger.error(
                            "Previous plugin restore skipped because the target path is still occupied"
                        )
                audit_plugin_import_failure(
                    conn,
                    actor=actor,
                    package_digest=package_digest,
                    upload_size=upload_size,
                    stage=failure_stage,
                    error=exc,
                )
                raise
            finally:
                if previous_trash_root:
                    backup_remains = bool(previous_trash_path and previous_trash_path.exists())
                    if import_succeeded or not backup_remains:
                        shutil.rmtree(previous_trash_root, ignore_errors=True)
                    else:
                        app.logger.error("Preserved a previous plugin backup after failed import recovery")

            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            plugin = next((item for item in registry["plugins"] if item["id"] == manifest["id"]), None)
        return response({"status": "ok", "plugin": plugin, "registry": registry})

    @flask_app.delete("/api/next/plugins/<plugin_id>")
    def delete_plugin(plugin_id: str):
        plugin_id = str(plugin_id or "").strip()
        if not plugin_id:
            raise NextApiError("Plugin id is required", 400)
        body = request.get_json(silent=True) or {}
        confirm_plugin_id = clean_text(body.get("confirmPluginId") or body.get("pluginId"))
        confirmation = clean_text(body.get("confirmation"))
        expected_confirmation = f"DELETE {plugin_id}"
        if confirm_plugin_id != plugin_id or confirmation != expected_confirmation:
            raise NextApiError(
                f"Type the plugin id and confirmation phrase exactly: {expected_confirmation}",
                400,
            )

        source_path: Path | None = None
        trash_path: Path | None = None
        trash_root: Path | None = None
        plugin: dict[str, Any] | None = None
        deleted: dict[str, int] = {}
        actor: dict[str, Any] | None = None
        try:
            with connect() as conn:
                require_any_next_permission(conn, PLUGIN_REGISTRY_VIEW_PERMISSIONS)
                if not table_exists(conn, "plugins"):
                    raise NextApiError("Plugin registry table is not available", 503)
                if table_exists(conn, "metadata_plugins"):
                    sync_metadata_plugin_registry(conn)
                else:
                    sync_plugin_registry(conn, table_exists, Jsonb)
                registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
                plugin = next((item for item in registry["plugins"] if item["id"] == plugin_id), None)
                if not plugin:
                    raise NextApiError("Plugin not found", 404)
                actor = require_plugin_delete_permission(conn, plugin)

                source_path, trash_path, trash_root = move_plugin_source_to_trash(plugin)
                with conn.transaction():
                    deleted = delete_plugin_records(conn, plugin_id)
                    audit_event(
                        conn,
                        event_type="plugin.deleted",
                        category="plugins",
                        actor=actor,
                        target_type="plugin",
                        target_id=plugin_id,
                        summary=f"Deleted plugin {plugin_id}",
                        metadata={
                            "pluginId": plugin_id,
                            "name": plugin.get("name"),
                            "version": plugin.get("version"),
                            "categories": plugin.get("categories") or [],
                            "sourcePath": str(source_path) if source_path else None,
                            "deleted": deleted,
                        },
                    )
                registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
        except Exception:
            restore_plugin_source(source_path, trash_path)
            raise
        finally:
            if trash_root:
                shutil.rmtree(trash_root, ignore_errors=True)

        return response(
            {
                "status": "ok",
                "deleted": {
                    "pluginId": plugin_id,
                    "sourcePath": str(source_path) if source_path else None,
                    "records": deleted,
                },
                "registry": registry,
            }
        )

    @flask_app.patch("/api/next/plugins/<plugin_id>")
    def update_plugin(plugin_id: str):
        plugin_id = str(plugin_id or "").strip()
        if not plugin_id:
            raise NextApiError("Plugin id is required", 400)
        body = request.get_json(silent=True) or {}
        has_enabled = "enabled" in body
        has_order = "orderIndex" in body or "order_index" in body
        if not has_enabled and not has_order:
            raise NextApiError("Supply enabled and/or orderIndex", 400)

        enabled = bool(body.get("enabled")) if has_enabled else None
        order_value = body.get("orderIndex", body.get("order_index"))
        order_index = None
        if has_order:
            try:
                order_index = max(1, min(int(order_value), 10000))
            except (TypeError, ValueError) as exc:
                raise NextApiError("orderIndex must be an integer", 400) from exc

        with connect() as conn:
            require_any_next_permission(conn, PLUGIN_REGISTRY_VIEW_PERMISSIONS)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)
            if table_exists(conn, "metadata_plugins"):
                sync_metadata_plugin_registry(conn)
            else:
                sync_plugin_registry(conn, table_exists, Jsonb)

            with conn.cursor() as cur:
                cur.execute(
                    "SELECT id, categories, enabled FROM plugins WHERE id=%s",
                    (plugin_id,),
                )
                plugin = cur.fetchone()
            if not plugin:
                raise NextApiError("Plugin not found", 404)
            actor = require_any_next_permission(conn, plugin_manage_permissions(plugin))

            categories = plugin.get("categories") or []
            is_metadata_plugin = bool(
                {"metadata_source", "metadata_receiver"}.intersection(set(categories))
            )
            queue_initial_sync = bool(
                has_enabled
                and enabled
                and not bool(plugin.get("enabled"))
                and plugin_id == MOVIEVAULT_V2_PLUGIN_ID
            )
            if queue_initial_sync:
                config = plugin_config_from_db(conn, plugin_id)
                if not config["settingsConfigured"]:
                    raise NextApiError("Plugin configuration is incomplete", 409)

            initial_job = None
            initial_duplicate = False
            initial_skipped_current = False
            with conn.transaction():
                with conn.cursor() as cur:
                    if is_metadata_plugin and table_exists(conn, "metadata_plugins"):
                        assignments = []
                        params: list[Any] = []
                        if has_enabled:
                            assignments.append("enabled=%s")
                            params.append(enabled)
                        if has_order:
                            assignments.append("order_index=%s")
                            params.append(order_index)
                        if assignments:
                            cur.execute(
                                f"""
                                UPDATE metadata_plugins
                                SET {', '.join(assignments)}, updated_at=now()
                                WHERE id=%s
                                """,
                                (*params, plugin_id),
                            )

                    assignments = []
                    params = []
                    if has_enabled:
                        assignments.append("enabled=%s")
                        params.append(enabled)
                    if has_order:
                        assignments.append("order_index=%s")
                        params.append(order_index)
                    if assignments:
                        cur.execute(
                            f"""
                            UPDATE plugins
                            SET {', '.join(assignments)}, updated_at=now()
                            WHERE id=%s
                            """,
                            (*params, plugin_id),
                        )
                audit_event(
                    conn,
                    event_type="plugin.updated",
                    category="plugins",
                    actor=actor,
                    target_type="plugin",
                    target_id=plugin_id,
                    summary=f"Updated plugin {plugin_id}",
                    metadata={
                        "enabled": enabled if has_enabled else None,
                        "orderIndex": order_index if has_order else None,
                        "categories": categories,
                    },
                )
                if queue_initial_sync:
                    (
                        initial_job,
                        initial_duplicate,
                        initial_skipped_current,
                    ) = queue_movievault_v2_sync_job(
                        conn,
                        actor=actor,
                        source="enable",
                        skip_when_indexed=True,
                    )

            if table_exists(conn, "metadata_plugins"):
                sync_metadata_plugin_registry(conn)
            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            updated = next((item for item in registry["plugins"] if item["id"] == plugin_id), None)
        return response(
            {
                "status": "ok",
                "plugin": updated,
                "registry": registry,
                "initialSync": {
                    "job": initial_job,
                    "duplicate": initial_duplicate,
                    "skippedCurrent": initial_skipped_current,
                }
                if queue_initial_sync
                else None,
            }
        )

