    @flask_app.post("/api/next/plugins/movievault/connection/refresh", defaults={"plugin_id": MOVIEVAULT_PLUGIN_ID})
    @flask_app.post("/api/next/plugins/<plugin_id>/connection/refresh")
    def refresh_movievault_plugin_connection(plugin_id: str):
        plugin_id = str(plugin_id or "").strip()
        if not is_movievault_plugin(plugin_id):
            raise NextApiError("MovieVault plugin not found", 404)
        body = request.get_json(silent=True) or {}
        reset = bool(body.get("reset"))
        with connect() as conn:
            require_any_next_permission(conn, PLUGIN_REGISTRY_VIEW_PERMISSIONS)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)
            if table_exists(conn, "metadata_plugins"):
                sync_metadata_plugin_registry(conn)
            else:
                sync_plugin_registry(conn, table_exists, Jsonb)
            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            plugin = next((item for item in registry["plugins"] if item["id"] == plugin_id), None)
            if not plugin:
                raise NextApiError("MovieVault plugin not found", 404)
            actor = require_any_next_permission(conn, plugin_manage_permissions(plugin))
            status = "ok"
            status_code = 200
            error = None
            try:
                refresh_movievault_connection(conn, plugin_id=plugin_id, actor_id=actor.get("id"), reset=reset)
                summary = f"MovieVault connection refreshed for {plugin_id}"
            except MovieVaultInstanceRevoked as exc:
                status = "error"
                status_code = 409
                error = str(exc)
                summary = f"MovieVault connection revoked for {plugin_id}"
            except MovieVaultConnectionError as exc:
                status = "error"
                status_code = 409
                error = str(exc)
                summary = f"MovieVault connection refresh failed for {plugin_id}"
            connection = movievault_connection_status(conn, plugin_id)
            audit_event(
                conn,
                event_type="plugin.movievault_connection_refreshed" if status == "ok" else "plugin.movievault_connection_failed",
                category="plugins",
                actor=actor,
                target_type="plugin",
                target_id=plugin_id,
                summary=summary,
                metadata={
                    "pluginId": plugin_id,
                    "reset": reset,
                    "status": status,
                    "error": error,
                    "authMethod": connection.get("authMethod"),
                    "linkStatus": connection.get("linkStatus"),
                    "tokenPrefix": connection.get("tokenPrefix"),
                },
            )
            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            plugin = next((item for item in registry["plugins"] if item["id"] == plugin_id), plugin)
            config = plugin_config_from_db(conn, plugin_id)
        payload = {
            "status": status,
            "plugin": plugin,
            "config": {
                "settingsConfigured": config["settingsConfigured"],
                "secretNames": config["secretNames"],
                "secretsConfigured": config["secretsConfigured"],
            },
            "connection": connection,
        }
        if error:
            payload["error"] = error
        return response(payload, status_code)

    @flask_app.get("/api/next/plugins/<plugin_id>/health")
    def plugin_health(plugin_id: str):
        plugin_id = str(plugin_id or "").strip()
        if not plugin_id:
            raise NextApiError("Plugin id is required", 400)

        with connect() as conn:
            require_any_next_permission(conn, PLUGIN_REGISTRY_VIEW_PERMISSIONS)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)
            if table_exists(conn, "metadata_plugins"):
                sync_metadata_plugin_registry(conn)
            else:
                sync_plugin_registry(conn, table_exists, Jsonb)

            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            plugin = next((item for item in registry["plugins"] if item["id"] == plugin_id), None)
            if not plugin:
                raise NextApiError("Plugin not found", 404)
            actor = require_plugin_action_permission(conn, plugin, "health_check")
            config = plugin_config_from_db(conn, plugin_id)
            context = plugin_execution_context(
                conn,
                plugin,
                config,
                actor,
                ensure_movievault_token=is_movievault_plugin(plugin_id),
            )

        manifest = plugin.get("manifest") or {}
        requires_secrets = bool(plugin.get("requiresSecrets") or manifest.get("requiresSecrets"))
        runtime = run_plugin_health(plugin_id, context)
        state = str(runtime.get("state") or "unknown")
        if runtime.get("status") == "error":
            state = str(runtime.get("state") or "runtime_error")
        elif requires_secrets and not config["secretsConfigured"]:
            state = "needs_configuration"

        return response(
            {
                "status": "ok",
                "plugin": plugin,
                "config": {
                    "settingsConfigured": config["settingsConfigured"],
                    "secretNames": config["secretNames"],
                    "secretsConfigured": config["secretsConfigured"],
                },
                "health": {
                    "state": state,
                    "requiresSecrets": requires_secrets,
                    "runtime": runtime,
                },
            }
        )

    @flask_app.post("/api/next/plugins/<plugin_id>/execute")
    def execute_plugin(plugin_id: str):
        plugin_id = str(plugin_id or "").strip()
        if not plugin_id:
            raise NextApiError("Plugin id is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Plugin execution body must be an object", 400)

        with connect() as conn:
            require_any_next_permission(conn, PLUGIN_REGISTRY_VIEW_PERMISSIONS)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)
            if table_exists(conn, "metadata_plugins"):
                sync_metadata_plugin_registry(conn)
            else:
                sync_plugin_registry(conn, table_exists, Jsonb)
            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            plugin = next((item for item in registry["plugins"] if item["id"] == plugin_id), None)
            if not plugin:
                raise NextApiError("Plugin not found", 404)
            entrypoint, payload = validate_plugin_execution_request(plugin, body)
            if entrypoint == "sync_index":
                raise NextApiError("Queue sync_index through the plugin jobs endpoint", 409)
            actor = require_plugin_action_permission(conn, plugin, entrypoint)
            config = plugin_config_from_db(conn, plugin_id)
            if plugin_requires_config_for_entrypoint(plugin, config, entrypoint):
                raise NextApiError("Plugin configuration is incomplete", 409)
            context = plugin_execution_context(
                conn,
                plugin,
                config,
                actor,
                ensure_movievault_token=is_movievault_plugin(plugin_id) and entrypoint != "health_check",
            )

        execution = run_plugin_entrypoint(plugin_id, entrypoint, payload, context)
        status_code = 200 if execution.get("status") == "ok" else 422
        return response(
            {
                "status": "ok" if execution.get("status") == "ok" else "error",
                "plugin": plugin,
                "execution": execution,
            },
            status_code,
        )

    @flask_app.post("/api/next/plugins/<plugin_id>/jobs")
    def queue_plugin_execution(plugin_id: str):
        plugin_id = str(plugin_id or "").strip()
        if not plugin_id:
            raise NextApiError("Plugin id is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Plugin execution body must be an object", 400)

        with connect() as conn:
            require_any_next_permission(conn, PLUGIN_REGISTRY_VIEW_PERMISSIONS)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)
            if table_exists(conn, "metadata_plugins"):
                sync_metadata_plugin_registry(conn)
            else:
                sync_plugin_registry(conn, table_exists, Jsonb)
            registry = plugin_registry_snapshot(conn, table_exists, Jsonb)
            plugin = next((item for item in registry["plugins"] if item["id"] == plugin_id), None)
            if not plugin:
                raise NextApiError("Plugin not found", 404)
            entrypoint, payload = validate_plugin_execution_request(plugin, body)
            actor = require_plugin_action_permission(conn, plugin, entrypoint)
            config = plugin_config_from_db(conn, plugin_id)
            if plugin_requires_config_for_entrypoint(plugin, config, entrypoint):
                raise NextApiError("Plugin configuration is incomplete", 409)
            job_payload = {
                "pluginId": plugin_id,
                "entrypoint": entrypoint,
                "payload": payload,
                "requestedBy": {
                    "id": str(actor.get("id")) if actor.get("id") else None,
                    "username": actor.get("username"),
                    "role": actor.get("role"),
                },
            }
            duplicate = False
            with conn.transaction():
                job = None
                if plugin_id == MOVIEVAULT_V2_PLUGIN_ID and entrypoint == "sync_index":
                    job, duplicate, _skipped_current = queue_movievault_v2_sync_job(
                        conn,
                        actor=actor,
                        source="manual",
                    )
                if job is None:
                    job = create_background_job(
                        conn,
                        job_type=PLUGIN_EXECUTION_JOB_TYPE,
                        payload=job_payload,
                    )
                    audit_event(
                        conn,
                        event_type="plugin.job_queued",
                        category="plugins",
                        actor=actor,
                        target_type="background_job",
                        target_id=job.get("id"),
                        summary=f"Queued {plugin_id}.{entrypoint}",
                        metadata={"pluginId": plugin_id, "entrypoint": entrypoint, "payload": payload},
                    )
        return response(
            {"status": "ok", "plugin": plugin, "job": job, "duplicate": duplicate},
            200 if duplicate else 201,
        )

    @flask_app.get("/api/next/metadata/plugins")
    def metadata_plugins():
        with connect() as conn:
            if not table_exists(conn, "metadata_plugins"):
                return response({"status": "ok", "plugins": []})
            sync_metadata_plugin_registry(conn)
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT
                        p.id,
                        p.name,
                        p.version,
                        p.enabled,
                        p.installed,
                        p.order_index,
                        p.manifest,
                        p.settings_schema,
                        p.premium_feature_key,
                        p.updated_at,
                        s.settings,
                        s.secrets_ref
                    FROM metadata_plugins p
                    LEFT JOIN metadata_plugin_settings s ON s.plugin_id = p.id
                    ORDER BY p.order_index, p.name
                    """
                )
                plugins = [plugin_row(row) for row in cur.fetchall()]
        return response({"status": "ok", "plugins": plugins})

    @flask_app.get("/api/next/movies")
    def movies():
        # 1000 matches the sibling list routes (/api/next/api/v1/movies,
        # /api/next/media-groups, /api/next/digital-items). The old 200 ceiling was a
        # leftover of the removed library cap and silently truncated any caller that
        # asked for more.
        limit = min(max(int(request.args.get("limit", 50)), 1), 1000)
        offset = max(int(request.args.get("offset", 0)), 0)
        query = (request.args.get("q") or "").strip()
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                ("collection.view", "collection.view_own", "collection.view_group", "collection.view_all"),
            )
            if not table_exists(conn, "movies"):
                return response({"status": "ok", "items": [], "limit": limit, "offset": offset})
            params: list[Any] = []
            conditions: list[str] = []
            if query:
                conditions.append("lower(m.title) LIKE lower(%s)")
                params.append(f"%{query}%")
            visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m")
            conditions.append(visibility_where)
            params.extend(visibility_params)
            where = "WHERE " + " AND ".join(f"({condition})" for condition in conditions)
            with conn.cursor() as cur:
                if table_exists(conn, "entity_media") and table_exists(conn, "media_assets"):
                    cur.execute(
                        f"""
                        SELECT
                            m.id,
                            m.public_id,
                            m.barcode,
                            m.title,
                            m.sort_title,
                            m.original_title,
                            m.year,
                            m.format,
                            m.media_type,
                            m.edition,
                            m.owner_id,
                            m.metadata->>'poster_url' AS poster_url,
                            m.metadata->>'backdrop_url' AS backdrop_url,
                            poster_asset.id AS poster_asset_id,
                            poster_asset.storage_backend AS poster_asset_storage_backend,
                            poster_asset.storage_key AS poster_asset_storage_key,
                            poster_asset.source_url AS poster_asset_source_url,
                            backdrop_asset.id AS backdrop_asset_id,
                            backdrop_asset.storage_backend AS backdrop_asset_storage_backend,
                            backdrop_asset.storage_key AS backdrop_asset_storage_key,
                            backdrop_asset.source_url AS backdrop_asset_source_url,
                            m.created_at,
                            m.updated_at
                        FROM movies m
                        LEFT JOIN LATERAL (
                            SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                            FROM entity_media em
                            JOIN media_assets ma ON ma.id = em.media_id
                            WHERE em.entity_type='movie'
                              AND em.entity_id=m.id
                              AND em.deleted_at IS NULL
                              AND em.hidden_at IS NULL
                              AND ma.kind='poster'
                            ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                            LIMIT 1
                        ) poster_asset ON true
                        LEFT JOIN LATERAL (
                            SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                            FROM entity_media em
                            JOIN media_assets ma ON ma.id = em.media_id
                            WHERE em.entity_type='movie'
                              AND em.entity_id=m.id
                              AND em.deleted_at IS NULL
                              AND em.hidden_at IS NULL
                              AND ma.kind='backdrop'
                            ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                            LIMIT 1
                        ) backdrop_asset ON true
                        {where}
                        ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                        LIMIT %s OFFSET %s
                        """,
                        (*params, limit, offset),
                    )
                    items = [with_preview_media_urls(row) for row in cur.fetchall()]
                else:
                    cur.execute(
                        f"""
                        SELECT
                            m.id,
                            m.public_id,
                            m.barcode,
                            m.title,
                            m.sort_title,
                            m.original_title,
                            m.year,
                            m.format,
                            m.media_type,
                            m.edition,
                            m.owner_id,
                            m.metadata->>'poster_url' AS poster_url,
                            m.metadata->>'backdrop_url' AS backdrop_url,
                            m.created_at,
                            m.updated_at
                        FROM movies m
                        {where}
                        ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                        LIMIT %s OFFSET %s
                        """,
                        (*params, limit, offset),
                    )
                    items = cur.fetchall()
            items = attach_media_group_availability(conn, attach_digital_availability(conn, items))
        return response({"status": "ok", "items": items, "limit": limit, "offset": offset})

    @flask_app.get("/api/next/movies/<movie_id>")
    def movie_detail(movie_id: str):
        movie_uuid = parse_uuid(movie_id, "movieId")
