    # ------------------------------------------------------------------
    # Wishlist: metadata-only "want to acquire" entries.
    # ------------------------------------------------------------------
    _WISHLIST_MAX_SHOPS = 10

    def _normalise_shop_currency(raw: Any) -> str:
        value = clean_text(raw)
        return (value or "EUR").upper()[:3]

    def _validate_wishlist_price_url(raw_url: str) -> None:
        try:
            validate_public_url(raw_url)
        except PublicHttpError as exc:
            if exc.code == "url_invalid":
                raise NextApiError(
                    "Price URL must be a valid http or https URL without credentials",
                    400,
                    "wishlist_price_url_invalid",
                ) from None
            raise NextApiError(
                "Price URL must resolve only to public network addresses",
                400,
                "wishlist_price_url_not_public",
            ) from None

    def _validated_shop_selector_payload(body: dict[str, Any]) -> tuple[str | None, str | None, dict[str, Any]]:
        selector = body.get("priceSelector")
        selector_type = clean_text(body.get("selectorType") or body.get("selector_type"))
        selector_value = clean_text(body.get("selectorValue") or body.get("selector_value"))
        selector_options: dict[str, Any] = {}
        if isinstance(selector, dict):
            selector_type = clean_text(selector.get("type") or selector_type)
            selector_value = clean_text(selector.get("value") or selector_value)
            if isinstance(selector.get("options"), dict):
                selector_options = json_ready(selector.get("options")) or {}
        if selector_type or selector_value:
            allowed_types = {"css_text", "regex_capture"}
            if selector_type not in allowed_types:
                raise NextApiError("Selector type must be css_text or regex_capture", 400)
            if not selector_value:
                raise NextApiError("Selector value is required when selector type is set", 400)
            return selector_type, selector_value, selector_options
        return None, None, {}

    def _validated_shop_provider_payload(body: dict[str, Any]) -> tuple[str | None, str | None]:
        provider = body.get("provider")
        provider_id = clean_text(body.get("providerId") or body.get("provider_id"))
        provider_ref = clean_text(body.get("providerProductRef") or body.get("provider_product_ref"))
        if isinstance(provider, dict):
            provider_id = clean_text(provider.get("id") or provider_id)
            provider_ref = clean_text(provider.get("productRef") or provider.get("product_ref") or provider_ref)
        if provider_id and not re.fullmatch(r"[a-z0-9][a-z0-9_-]{1,80}", provider_id):
            raise NextApiError("Provider id has an invalid format", 400)
        return provider_id or None, provider_ref or None

    def _validated_shop_payload(
        body: dict[str, Any],
    ) -> tuple[str, str, str, str | None, str | None, dict[str, Any], str | None, str | None]:
        name = clean_text(body.get("shopName") or body.get("shop_name"))
        if not name:
            raise NextApiError("Shop name is required", 400)
        raw_url = clean_text(body.get("priceUrl") or body.get("price_url"))
        if not raw_url:
            raise NextApiError("Shop URL is required", 400)
        _validate_wishlist_price_url(raw_url)
        selector_type, selector_value, selector_options = _validated_shop_selector_payload(body)
        provider_plugin_id, provider_product_ref = _validated_shop_provider_payload(body)
        return (
            name,
            raw_url,
            _normalise_shop_currency(body.get("priceCurrency") or body.get("price_currency")),
            selector_type,
            selector_value,
            selector_options,
            provider_plugin_id,
            provider_product_ref,
        )

    def _normalise_tmdb_id(value: Any) -> str | None:
        if value is None:
            return None
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            return str(value) if value > 0 else None
        if isinstance(value, float):
            return str(int(value)) if value > 0 and value.is_integer() else None
        text = clean_text(value)
        if not text:
            return None
        return text if text.isdigit() else None

    def _normalise_tmdb_media_type(value: Any) -> str | None:
        text = clean_text(value)
        if not text:
            return None
        lowered = text.lower()
        return lowered if lowered in {"movie", "tv"} else None

    def _normalise_wishlist_source(value: Any) -> str | None:
        text = clean_text(value)
        if not text:
            return None
        return text.lower()[:48]

    def _wishlist_snapshot(payload: dict[str, Any]) -> dict[str, Any]:
        return json_ready(
            {
                "title": payload.get("title"),
                "movie_title": payload.get("title"),
                "year": payload.get("year"),
                "movie_year": payload.get("year"),
                "barcode": payload.get("barcode"),
                "format": payload.get("format"),
                "movie_format": payload.get("format"),
                "movievault_id": payload.get("movievault_id"),
                "poster_url": payload.get("poster_url"),
                "tmdb_id": payload.get("tmdb_id"),
                "tmdb_media_type": payload.get("tmdb_media_type"),
                "source": payload.get("source"),
            }
        )

