    @flask_app.get("/api/next/stats/personal")
    def personal_statistics():
        with connect() as conn:
            actor = require_next_permission(conn, "watchlist.manage")
            user_id = actor.get("id")
            where, params = visible_movie_where_sql(conn, actor, "m")

            def _bucket_rows(sql: str) -> list[dict[str, Any]]:
                with conn.cursor() as cur:
                    cur.execute(sql, params)
                    return cur.fetchall()

            total = 0
            by_format: list[dict[str, Any]] = []
            for row in _bucket_rows(
                f"""
                SELECT COALESCE(NULLIF(TRIM(m.format), ''), 'Unknown') AS label,
                       COUNT(*)::int AS count
                FROM movies m
                WHERE {where}
                GROUP BY 1
                ORDER BY count DESC, label
                """
            ):
                by_format.append({"label": row.get("label"), "count": int(row.get("count") or 0)})
                total += int(row.get("count") or 0)

            by_decade = [
                {"label": (f"{row.get('decade')}s" if row.get("decade") is not None else "Unknown"),
                 "count": int(row.get("count") or 0)}
                for row in _bucket_rows(
                    f"""
                    SELECT (NULLIF(substring(m.year from '[0-9]{{4}}'), '')::int / 10 * 10) AS decade,
                           COUNT(*)::int AS count
                    FROM movies m
                    WHERE {where}
                    GROUP BY 1
                    ORDER BY decade NULLS LAST
                    """
                )
            ]

            by_rating = [
                {"label": row.get("label"), "count": int(row.get("count") or 0)}
                for row in _bucket_rows(
                    f"""
                    SELECT COALESCE(NULLIF(TRIM(m.rating), ''), 'Unrated') AS label,
                           COUNT(*)::int AS count
                    FROM movies m
                    WHERE {where}
                    GROUP BY 1
                    ORDER BY count DESC, label
                    """
                )
            ]

            genre_counts: dict[str, int] = {}
            for row in _bucket_rows(
                f"""
                SELECT mg.genre_key AS genre, COUNT(DISTINCT m.id)::int AS count
                FROM movies m
                JOIN movie_genres mg ON mg.movie_id = m.id
                WHERE {where}
                GROUP BY mg.genre_key
                """
                if table_exists(conn, "movie_genres")
                else f"SELECT NULL AS genre, 0 AS count FROM movies m WHERE {where} LIMIT 0"
            ):
                key = clean_text(row.get("genre"))
                count = int(row.get("count") or 0)
                if key in GENRE_KEYS:
                    genre_counts[key] = genre_counts.get(key, 0) + count
            unknown_genre_sql = (
                f"""
                SELECT COUNT(*)::int AS count
                FROM movies m
                WHERE {where}
                  AND NOT EXISTS (SELECT 1 FROM movie_genres mg WHERE mg.movie_id = m.id)
                """
                if table_exists(conn, "movie_genres")
                else f"SELECT COUNT(*)::int AS count FROM movies m WHERE {where}"
            )
            unknown_rows = _bucket_rows(unknown_genre_sql)
            unknown_count = int(unknown_rows[0].get("count") or 0) if unknown_rows else 0
            by_genre = sorted(
                [
                    {"label": GENRE_KEY_TO_LABEL.get(key, key), "i18nKey": f"genre.{key}", "count": count}
                    for key, count in genre_counts.items()
                ],
                key=lambda item: (-item["count"], item["label"]),
            )[:20]
            if unknown_count:
                by_genre.append({"label": "Unknown", "count": unknown_count})

            watch = {"total": 0, "thisYear": 0, "distinctMovies": 0, "topMovies": []}
            if table_exists(conn, "watch_history"):
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT
                            COUNT(*)::int AS total,
                            COUNT(*) FILTER (WHERE date_part('year', watched_at) = date_part('year', now()))::int AS this_year,
                            COUNT(DISTINCT COALESCE(movie_id::text, snapshot->>'movie_id', snapshot->>'title'))::int AS distinct_movies
                        FROM watch_history
                        WHERE user_id=%s
                        """,
                        (user_id,),
                    )
                    row = cur.fetchone() or {}
                    watch["total"] = int(row.get("total") or 0)
                    watch["thisYear"] = int(row.get("this_year") or 0)
                    watch["distinctMovies"] = int(row.get("distinct_movies") or 0)
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT
                            COALESCE(snapshot->>'title', snapshot->>'movie_title', 'Unknown') AS title,
                            COUNT(*)::int AS count
                        FROM watch_history
                        WHERE user_id=%s
                        GROUP BY 1
                        ORDER BY count DESC, title
                        LIMIT 10
                        """,
                        (user_id,),
                    )
                    watch["topMovies"] = [
                        {"title": r.get("title"), "count": int(r.get("count") or 0)}
                        for r in cur.fetchall()
                    ]

            wishlist_count = 0
            if table_exists(conn, "wishlist_items"):
                with conn.cursor() as cur:
                    cur.execute("SELECT COUNT(*)::int AS count FROM wishlist_items WHERE user_id=%s", (user_id,))
                    wishlist_count = int((cur.fetchone() or {}).get("count") or 0)

            loans_stats = {"active": 0, "overdue": 0, "returned": 0}
            if table_exists(conn, "loans"):
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT
                            COUNT(*) FILTER (WHERE returned_at IS NULL)::int AS active,
                            COUNT(*) FILTER (WHERE returned_at IS NULL AND due_at IS NOT NULL AND due_at < now())::int AS overdue,
                            COUNT(*) FILTER (WHERE returned_at IS NOT NULL)::int AS returned
                        FROM loans
                        WHERE user_id=%s
                        """,
                        (user_id,),
                    )
                    row = cur.fetchone() or {}
                    loans_stats = {
                        "active": int(row.get("active") or 0),
                        "overdue": int(row.get("overdue") or 0),
                        "returned": int(row.get("returned") or 0),
                    }

            wishlist_price_trend = {
                "enabled": bool(loans_stats.get("active", 0) > 0),
                "activeLoans": int(loans_stats.get("active") or 0),
                "movies": [],
            }
            if table_exists(conn, "wishlist_items") and table_exists(conn, "wishlist_item_shop_prices"):
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT
                            wi.id::text AS wishlist_item_id,
                            COALESCE(NULLIF(TRIM(wi.title), ''), 'Unknown') AS title,
                            wi.year AS year,
                            date_trunc('day', p.observed_at) AS observed_day,
                            MIN(p.observed_price)::float8 AS observed_price,
                            COALESCE(NULLIF(TRIM(MAX(p.price_currency)), ''), 'EUR') AS price_currency
                        FROM wishlist_items wi
                        JOIN wishlist_item_shop_prices p ON p.wishlist_item_id = wi.id
                        WHERE wi.user_id=%s
                          AND wi.acquired_at IS NULL
                          AND wi.acquired_movie_id IS NULL
                        GROUP BY wi.id, COALESCE(NULLIF(TRIM(wi.title), ''), 'Unknown'), wi.year, date_trunc('day', p.observed_at)
                        ORDER BY title, wi.year NULLS LAST, observed_day ASC
                        """,
                        (user_id,),
                    )
                    trend_rows = cur.fetchall()
                movie_trends: dict[str, dict[str, Any]] = {}
                for row in trend_rows:
                    item_id = str(row.get("wishlist_item_id") or "").strip()
                    if not item_id:
                        continue
                    observed_price = row.get("observed_price")
                    if observed_price is None:
                        continue
                    try:
                        price_value = float(observed_price)
                    except (TypeError, ValueError):
                        continue
                    if price_value < 0:
                        continue
                    observed_day = row.get("observed_day")
                    observed_at = (
                        observed_day.isoformat()
                        if isinstance(observed_day, datetime)
                        else str(observed_day or "")
                    )
                    if not observed_at:
                        continue
                    currency = clean_text(row.get("price_currency")) or "EUR"
                    movie = movie_trends.setdefault(
                        item_id,
                        {
                            "wishlistItemId": item_id,
                            "title": clean_text(row.get("title")) or "Unknown",
                            "year": row.get("year"),
                            "currency": currency.upper(),
                            "points": [],
                        },
                    )
                    movie["points"].append({"at": observed_at, "price": round(price_value, 2)})
                movies: list[dict[str, Any]] = []
                for movie in movie_trends.values():
                    points = movie.get("points") or []
                    if not points:
                        continue
                    first_price = float(points[0]["price"])
                    current_price = float(points[-1]["price"])
                    min_price = min(float(point["price"]) for point in points)
                    max_price = max(float(point["price"]) for point in points)
                    movie["currentPrice"] = round(current_price, 2)
                    movie["minPrice"] = round(min_price, 2)
                    movie["maxPrice"] = round(max_price, 2)
                    movie["changeFromStart"] = round(current_price - first_price, 2)
                    movie["sampleCount"] = len(points)
                    movie["lastObservedAt"] = points[-1]["at"]
                    movies.append(movie)
                movies.sort(key=lambda item: (str(item.get("title") or "").lower(), str(item.get("year") or "")))
                wishlist_price_trend["movies"] = movies

            # Capturing here as well as on every write keeps the series alive on a
            # day the user only looked: without it, a quiet week leaves a gap the
            # chart would have to interpolate across.
            container_where, container_params = visible_container_where_sql(conn, actor, "c")
            collection_value = compute_collection_value(
                conn,
                movie_where=where,
                movie_params=params,
                container_where=container_where,
                container_params=container_params,
                exchange_rates=dict(price_display_exchange_rates().get("exchangeRates") or {}),
            )
            capture_collection_value_snapshot(conn, actor)

            return response(
                {
                    "status": "ok",
                    "totalMovies": total,
                    "byFormat": by_format,
                    "byDecade": by_decade,
                    "byGenre": by_genre,
                    "byRating": by_rating,
                    "watch": watch,
                    "wishlistCount": wishlist_count,
                    "loans": loans_stats,
                    "wishlistPriceTrend": wishlist_price_trend,
                    "collectionValue": collection_value,
                }
            )

    @flask_app.get("/api/next/stats/collection-value/history")
    def collection_value_history_view():
        """The stored value-over-time series for one scope.

        Reads snapshots only - it never recomputes, so a gap in the series is a
        day on which nothing changed and nobody opened the statistics view.
        """
        scope_type = clean_text(request.args.get("scope")) or "total"
        if scope_type not in SNAPSHOT_SCOPE_TYPES:
            raise NextApiError(f"scope must be one of: {', '.join(SNAPSHOT_SCOPE_TYPES)}", 400)
        scope_id = clean_text(request.args.get("scopeId"))
        if scope_type == "total":
            scope_id = None
        elif not scope_id:
            raise NextApiError("scopeId is required for a vault or collection scope", 400)
        since = parse_optional_date(request.args.get("from"), "from")
        until = parse_optional_date(request.args.get("until") or request.args.get("to"), "until")
        with connect() as conn:
            actor = require_next_permission(conn, "watchlist.manage")
            points = collection_value_history(
                conn,
                user_id=actor.get("id"),
                scope_type=scope_type,
                scope_id=scope_id,
                since=since,
                until=until,
            )
        return response(
            {
                "status": "ok",
                "scope": scope_type,
                "scopeId": scope_id,
                "points": points,
            }
        )

    @flask_app.post("/api/next/movies/<movie_id>/identifiers")
    def add_movie_identifier(movie_id: str):
        movie_uuid = parse_uuid(movie_id, "movieId")
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Identifier request body must be an object", 400)
        provider_id = clean_text(body.get("providerId") or body.get("provider_id"))
        identifier = clean_text(body.get("identifier") or body.get("value"))
        identifier_type = clean_text(body.get("identifierType") or body.get("identifier_type")) or "movie_id"
        if not provider_id or not identifier:
            raise NextApiError("providerId and identifier are required", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "collection.edit_all")
            if not table_exists(conn, "movie_identifiers"):
                raise NextApiError("Movie identifiers table is not available", 503)
            existing = movie_entity(conn, movie_uuid)
            if not existing:
                raise NextApiError("Movie not found", 404)
            if not actor_can_edit_visible_movie(conn, actor, existing):
                raise NextApiError("Permission required: collection.edit_all", 403)
            with conn.transaction():
                with conn.cursor() as cur:
                    # A movie carries a single current value per (provider, type),
                    # so replace any stale value before inserting the new link.
                    cur.execute(
                        """
                        DELETE FROM movie_identifiers
                        WHERE movie_id=%s AND provider_id=%s AND identifier_type=%s
                          AND identifier<>%s
                        """,
                        (movie_uuid, provider_id, identifier_type, identifier),
                    )
                    cur.execute(
                        """
                        INSERT INTO movie_identifiers (movie_id, provider_id, identifier_type, identifier)
                        VALUES (%s, %s, %s, %s)
                        ON CONFLICT DO NOTHING
                        """,
                        (movie_uuid, provider_id, identifier_type, identifier),
                    )
                emit_movie_identifiers_change(conn, movie_uuid, operation="upsert")
                audit_event(
                    conn,
                    event_type="movie.identifier_added",
                    category="metadata",
                    actor=actor,
                    target_type="movie",
                    target_id=movie_uuid,
                    summary="Added movie identifier",
                    metadata={"providerId": provider_id, "identifierType": identifier_type},
                )
            return response(
                {
                    "status": "ok",
                    "movieId": str(movie_uuid),
                    "identifiers": movie_identifier_entities(conn, movie_uuid),
                },
                201,
            )

    @flask_app.delete("/api/next/movies/<movie_id>/identifiers")
    def remove_movie_identifier(movie_id: str):
        movie_uuid = parse_uuid(movie_id, "movieId")
        provider_id = clean_text(request.args.get("providerId") or request.args.get("provider_id"))
        identifier_type = clean_text(request.args.get("identifierType") or request.args.get("identifier_type"))
        identifier = clean_text(request.args.get("identifier") or request.args.get("value"))
        if not provider_id:
            raise NextApiError("providerId is required", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "collection.edit_all")
            if not table_exists(conn, "movie_identifiers"):
                raise NextApiError("Movie identifiers table is not available", 503)
            existing = movie_entity(conn, movie_uuid)
            if not existing:
                raise NextApiError("Movie not found", 404)
            if not actor_can_edit_visible_movie(conn, actor, existing):
                raise NextApiError("Permission required: collection.edit_all", 403)
            with conn.transaction():
                with conn.cursor() as cur:
                    sql = "DELETE FROM movie_identifiers WHERE movie_id=%s AND provider_id=%s"
                    params: list[Any] = [movie_uuid, provider_id]
                    if identifier_type:
                        sql += " AND identifier_type=%s"
                        params.append(identifier_type)
                    if identifier:
                        sql += " AND identifier=%s"
                        params.append(identifier)
                    cur.execute(sql, tuple(params))
                    deleted = int(cur.rowcount or 0)
                if deleted:
                    # Emit the movie's remaining identifier set so offline clients
                    # replace their local copy for this movie.
                    emit_movie_identifiers_change(conn, movie_uuid, operation="upsert")
                audit_event(
                    conn,
                    event_type="movie.identifier_removed",
                    category="metadata",
                    actor=actor,
                    target_type="movie",
                    target_id=movie_uuid,
                    summary="Removed movie identifier",
                    metadata={"providerId": provider_id, "identifierType": identifier_type, "deleted": deleted},
                )
            return response(
                {
                    "status": "ok",
                    "movieId": str(movie_uuid),
                    "deleted": deleted,
                    "identifiers": movie_identifier_entities(conn, movie_uuid),
                }
            )

