    @flask_app.get("/api/next/containers")
    def containers():
        container_type = (request.args.get("type") or "").strip()
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                ("containers.view", "collection.view", "collection.view_own", "collection.view_group", "collection.view_all"),
            )
            if not table_exists(conn, "containers"):
                return response({"status": "ok", "items": []})
            params: list[Any] = []
            conditions: list[str] = []
            if container_type:
                conditions.append("c.container_type = %s")
                params.append(container_type)
            visibility_where, visibility_params = visible_container_where_sql(conn, actor, "c")
            conditions.append(visibility_where)
            params.extend(visibility_params)
            where = "WHERE " + " AND ".join(f"({condition})" for condition in conditions)
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT
                        c.id,
                        c.public_id,
                        c.container_type,
                        c.title,
                        c.barcode,
                        c.badge_label,
                        c.year,
                        c.description,
                        c.metadata,
                        c.created_at,
                        c.updated_at,
                        poster.id AS poster_asset_id,
                        poster.storage_backend AS poster_storage_backend,
                        poster.storage_key AS poster_storage_key,
                        poster.source_url AS poster_source_url
                    FROM containers c
                    -- The container's own cover, so the library shows the artwork
                    -- the detail view already resolves from entity_media instead of
                    -- only the subset that happens to carry a metadata URL.
                    LEFT JOIN LATERAL (
                        SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                        FROM entity_media em
                        JOIN media_assets ma ON ma.id = em.media_id
                        WHERE em.entity_type = 'container'
                          AND em.entity_id = c.id
                          AND em.role = 'poster'
                          AND em.deleted_at IS NULL
                          AND em.hidden_at IS NULL
                          AND ma.kind = 'poster'
                        ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                        LIMIT 1
                    ) poster ON true
                    {where}
                    ORDER BY c.container_type, lower(c.title)
                    LIMIT 200
                    """,
                    params,
                )
                items = [
                    with_preview_media_urls(container_list_row(row))
                    for row in cur.fetchall()
                ]
        return response({"status": "ok", "items": items})

