    @flask_app.get("/api/next/jobs")
    def jobs():
        limit = parse_int_arg("limit", 100, minimum=1, maximum=500)
        status = (request.args.get("status") or "").strip()
        job_type = (request.args.get("jobType") or request.args.get("job_type") or "").strip()
        plugin_id = (request.args.get("pluginId") or request.args.get("plugin_id") or "").strip()
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                (
                    "admin.view_jobs",
                    "collection.import",
                    "admin.restore_functional",
                    "metadata.view_plugin_health",
                    "metadata.refresh_one",
                    "metadata.refresh_bulk",
                    "digital_sources.view",
                    "digital_sources.sync",
                    "digital_sources.manage",
                ),
            )
            if not table_exists(conn, "background_jobs"):
                return response({"status": "ok", "jobs": []})
            params: list[Any] = []
            clauses: list[str] = []
            permissions = set(actor.get("permissions") or [])
            role = actor.get("role")
            if role != "owner" and "admin.view_jobs" not in permissions:
                allowed_types = []
                if permissions.intersection({"metadata.view_plugin_health", "digital_sources.view", "digital_sources.sync", "digital_sources.manage", "collection.import"}):
                    allowed_types.append(PLUGIN_EXECUTION_JOB_TYPE)
                if permissions.intersection({"metadata.refresh_one", "metadata.refresh_bulk"}):
                    allowed_types.append(METADATA_REFRESH_JOB_TYPE)
                if permissions.intersection({"collection.import", "admin.restore_functional"}):
                    allowed_types.append(MIGRATION_JOB_TYPE)
                if job_type and job_type not in allowed_types:
                    raise NextApiError(f"Permission required for job type: {job_type}", 403)
                if not job_type and len(allowed_types) == 1:
                    job_type = allowed_types[0]
                elif not job_type and allowed_types:
                    clauses.append("job_type = ANY(%s)")
                    params.append(allowed_types)
            if status:
                clauses.append("status = %s")
                params.append(status)
            if job_type:
                clauses.append("job_type = %s")
                params.append(job_type)
            if plugin_id:
                clauses.append("payload->>'pluginId' = %s")
                params.append(plugin_id)
            where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT
                        id,
                        job_type,
                        status,
                        requested_by,
                        payload,
                        result,
                        error,
                        created_at,
                        started_at,
                        finished_at
                    FROM background_jobs
                    {where}
                    ORDER BY created_at DESC
                    LIMIT %s
                    """,
                    (*params, limit),
                )
                rows = cur.fetchall()
        return response({"status": "ok", "jobs": [job_row(row) for row in rows]})


