    @flask_app.post("/api/next/migration/legacy-auth/options")
    def legacy_migration_auth_options():
        if not _passkey_access_valid():
            raise NextApiError(
                "Passkeys require a valid RP_ID and HTTPS RP_ORIGIN, accessed through the configured origin",
                403,
            )
        with connect() as conn:
            readiness = migration_readiness(conn)
            source = readiness["legacyData"]
            if not legacy_auth_required(source):
                return response({"status": "ok", "required": False})
            sqlite_db = Path(str(source.get("sqliteDb") or ""))
            credentials = legacy_passkey_rows(sqlite_db)
            if not credentials:
                raise NextApiError("No legacy passkeys are available for migration approval.", 409)
            challenge = _make_challenge()
            with conn.transaction():
                store_migration_challenge(conn, MIGRATION_LEGACY_AUTH_CHALLENGE_KEY, challenge)
        return response(
            {
                "status": "ok",
                "required": True,
                "options": {
                    "challenge": _b64url_encode(challenge),
                    "timeout": 60000,
                    "rpId": _rp_id(),
                    "allowCredentials": [
                        {"type": "public-key", "id": clean_text(row.get("id"))}
                        for row in credentials
                        if clean_text(row.get("id"))
                    ],
                    "userVerification": "preferred",
                },
            }
        )

    @flask_app.post("/api/next/migration/legacy-auth/verify")
    def legacy_migration_auth_verify():
        if not _passkey_access_valid():
            raise NextApiError(
                "Passkeys require a valid RP_ID and HTTPS RP_ORIGIN, accessed through the configured origin",
                403,
            )
        body = request.get_json(silent=True) or {}
        credential = body.get("credential") or {}
        credential_id = clean_text(credential.get("id"))
        if not credential_id:
            raise NextApiError("Credential id is required", 400)

        with connect() as conn:
            readiness = migration_readiness(conn)
            source = readiness["legacyData"]
            if not legacy_auth_required(source):
                return response({"status": "ok", "required": False})
            challenge = pop_migration_challenge(conn, MIGRATION_LEGACY_AUTH_CHALLENGE_KEY)
            if not challenge:
                raise NextApiError("No pending legacy passkey challenge", 400)
            sqlite_db = Path(str(source.get("sqliteDb") or ""))
            credentials = {clean_text(row.get("id")): row for row in legacy_passkey_rows(sqlite_db)}
            stored = credentials.get(credential_id)
            if not stored:
                raise NextApiError("Unknown legacy credential", 400)
            if not legacy_admin_user(stored):
                raise NextApiError("Legacy owner/admin passkey is required to approve migration.", 403)

            try:
                client_data_raw = _b64url_decode(credential["response"]["clientDataJSON"])
                client_data = json_lib.loads(client_data_raw)
                if client_data.get("type") != "webauthn.get":
                    raise ValueError("Wrong type in clientDataJSON")
                if _b64url_decode(client_data["challenge"]) != challenge:
                    raise ValueError("Challenge mismatch")
                incoming_origin = clean_text(client_data.get("origin")).rstrip("/")
                if incoming_origin not in _rp_origins():
                    raise ValueError(f"Origin not allowed: {incoming_origin}")
                auth_data = _b64url_decode(credential["response"]["authenticatorData"])
                expected_rp_hash = hashlib.sha256(_rp_id().encode("utf-8")).digest()
                if auth_data[:32] != expected_rp_hash:
                    raise ValueError("RP ID hash mismatch")
                signature = _b64url_decode(credential["response"]["signature"])
                client_data_hash = hashlib.sha256(client_data_raw).digest()
                _verify_signature(bytes(stored["public_key"]), auth_data, client_data_hash, signature)
                _, _, new_sign_count = _parse_auth_data(auth_data)
            except Exception as exc:
                raise NextApiError(f"Legacy passkey verification failed: {exc}", 400) from exc

            token = secrets.token_urlsafe(32)
            with conn.transaction():
                store_migration_challenge(
                    conn,
                    migration_legacy_grant_key(token),
                    f"{clean_text(stored.get('username'))}:{credential_id}:{new_sign_count}".encode("utf-8"),
                    seconds=MIGRATION_LEGACY_AUTH_GRANT_SECONDS,
                )
        return response(
            {
                "status": "ok",
                "required": True,
                "legacyMigrationToken": token,
                "username": clean_text(stored.get("username")),
                "displayName": clean_text(stored.get("display_name")),
            }
        )

    @flask_app.post("/api/next/migration/start")
    def start_migration():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Migration request body must be an object", 400)

        include_security = parse_bool_value(body.get("includeSecurity", body.get("include_security")), default=True)
        include_personal = parse_bool_value(body.get("includePersonal", body.get("include_personal")), default=False)
        if include_personal and not include_security:
            raise NextApiError("includePersonal requires includeSecurity", 400)
        owner_username = clean_text(body.get("ownerUsername") or body.get("owner_username"))
        import_media_references = body.get("importMediaReferences", body.get("import_media_references", True))
        import_media_references = parse_bool_value(import_media_references, default=True)
        source_path = clean_text(body.get("sourcePath") or body.get("source_path") or body.get("path"))

        with connect() as conn:
            readiness = migration_readiness(conn)
            actor = require_migration_actor(conn, readiness)
            active = readiness.get("activeJob")
            if active:
                return response({"status": "ok", "job": active, "readiness": readiness, "replayed": True}, 200)
            if not readiness["canStart"]:
                raise NextApiError(
                    f"Migration cannot start while readiness state is {readiness['state']}",
                    409,
                )
            legacy = readiness["legacyData"]
            import_source_id = clean_text(
                body.get("importSourceId")
                or body.get("import_source_id")
                or legacy.get("pluginId")
            )
            selected_source = legacy
            if import_source_id and (import_source_id != legacy.get("pluginId") or source_path):
                plugin = import_source_plugin_by_id(conn, import_source_id)
                if not plugin:
                    raise NextApiError(f"Import source plugin is not available: {import_source_id}", 409)
                inspect_payload = import_source_payload_for_path(import_source_id, source_path)
                selected_source, execution = inspect_import_source_plugin(conn, plugin, inspect_payload, actor)
                if execution.get("status") != "ok":
                    raise NextApiError(
                        f"Import source inspection failed: {execution.get('error') or execution.get('state')}",
                        502,
                    )
                if not selected_source.get("found") or not selected_source.get("readable"):
                    raise NextApiError(f"Import source is not ready: {import_source_id}", 409)
            options = {
                "includeSecurity": include_security,
                "includePersonal": include_personal,
                "ownerUsername": owner_username,
                "importMediaReferences": import_media_references,
                "sourcePath": source_path,
            }
            job_type, payload, import_plan = plan_migration_import_job(
                conn,
                plugin_id=import_source_id,
                source=selected_source,
                options=options,
                actor=actor,
            )
            with conn.transaction():
                job = create_background_job(conn, job_type=job_type, payload=payload)
                audit_event(
                    conn,
                    event_type="migration.started",
                    category="migration",
                    actor=actor,
                    target_type="background_job",
                    target_id=job.get("id"),
                    summary="Started legacy DiscVault migration",
                    metadata={
                        "jobType": job_type,
                        "sourceKind": selected_source.get("sourceKind"),
                        "pluginId": import_source_id or selected_source.get("pluginId"),
                        "readinessState": readiness.get("state"),
                        "options": options,
                    },
                )
        return response({"status": "ok", "job": job, "readiness": readiness, "importPlan": import_plan}, 201)

