    @flask_app.get("/api/next/sync/bootstrap")
    def sync_bootstrap():
        limit = parse_int_arg("limit", 1000, minimum=1, maximum=5000)
        with connect() as conn:
            revision = current_revision(conn)
            movie_people = all_movie_credit_entities(
                conn,
                movie_limit=limit,
                credit_limit=min(max(limit * 80, 1000), 50000),
            )
            payload = {
                "movies": all_movie_entities(conn, limit=limit),
                "containers": all_container_entities(conn, limit=limit),
                "containerMembership": collection_container_membership_entities(
                    conn, limit=min(max(limit * 20, 1000), 200000)
                ),
                "movieIdentifiers": all_movie_identifier_entities(
                    conn, limit=min(max(limit * 20, 1000), 200000)
                ),
                # Unbounded by `limit`: the tree is at most four levels deep and
                # a movie's `location_id` is meaningless without the row it
                # points at, so truncating it would hand clients exactly the
                # unresolvable ids sync-contract §4c exists to remove.
                "locations": location_sync_entities(conn),
                # The series line. Which seasons sit on a given disc is *not*
                # here: it rides on the movie entity, so the delta carries it
                # too. A membership array beside these would only ever refresh
                # on a bootstrap.
                "series": series_sync_entities(conn),
                "seriesSeasons": series_season_sync_entities(conn),
                "moviePeople": movie_people,
                "movieCast": [credit for credit in movie_people if credit.get("department") == "cast"],
                "movieCrew": [credit for credit in movie_people if credit.get("department") == "crew"],
                "metadataPlugins": metadata_plugin_entities(conn),
                "settings": non_secret_settings(conn),
            }
        return response(
            {
                "status": "ok",
                "currentRevision": revision,
                "serverTime": datetime.utcnow().isoformat(timespec="seconds") + "Z",
                "payload": payload,
            }
        )

    @flask_app.get("/api/next/sync/delta")
    def sync_delta():
        since = parse_int_arg("since", 0, minimum=0, maximum=9_000_000_000)
        limit = parse_int_arg("limit", 500, minimum=1, maximum=1000)
        with connect() as conn:
            revision = current_revision(conn)
            if not table_exists(conn, "sync_changes"):
                return response(
                    {
                        "status": "ok",
                        "since": since,
                        "currentRevision": revision,
                        "changes": [],
                        "hasMore": False,
                        "nextSince": revision,
                    }
                )
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT
                        id,
                        revision,
                        entity_type,
                        entity_id,
                        operation,
                        payload,
                        created_at
                    FROM sync_changes
                    WHERE revision > %s
                    ORDER BY revision ASC
                    LIMIT %s
                    """,
                    (since, limit),
                )
                changes = cur.fetchall()
        next_since = int(changes[-1]["revision"]) if changes else since
        return response(
            {
                "status": "ok",
                "since": since,
                "currentRevision": revision,
                "changes": changes,
                "hasMore": bool(changes and next_since < revision),
                "nextSince": revision if not changes else next_since,
            }
        )

    @flask_app.post("/api/next/sync/mutations")
    def sync_mutations():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Mutation request body must be an object", 400)
        client_id = str(body.get("clientId") or "").strip()
        if not client_id:
            raise NextApiError("clientId is required", 400)
        base_revision = body.get("baseRevision", 0)
        try:
            base_revision = int(base_revision or 0)
        except (TypeError, ValueError) as exc:
            raise NextApiError("baseRevision must be an integer", 400) from exc
        mutations = body.get("mutations")
        if not isinstance(mutations, list):
            raise NextApiError("mutations must be a list", 400)
        if len(mutations) > 100:
            raise NextApiError("At most 100 mutations can be submitted at once", 400)

        results = []
        batch_ctx = SyncBatchContext()
        with connect() as conn:
            actor = require_next_authenticated_user(conn)
            # The batch is the unit the route authenticates, so the actor is
            # attached here and read by every apply_* that audits.
            batch_ctx.actor = actor
            ensure_sync_state(conn)
            for mutation in mutations:
                client_mutation_id = None
                if isinstance(mutation, dict):
                    client_mutation_id = mutation.get("clientMutationId")
                try:
                    with conn.transaction():
                        results.append(
                            apply_sync_mutation(
                                conn,
                                client_id=client_id,
                                mutation=mutation,
                                batch_ctx=batch_ctx,
                                actor=actor,
                            )
                        )
                except NextApiError as exc:
                    results.append(
                        {
                            "clientMutationId": client_mutation_id,
                            "status": "rejected",
                            "error": str(exc),
                        }
                    )
                except Exception as exc:  # pragma: no cover - safety net for per-mutation failures
                    results.append(
                        {
                            "clientMutationId": client_mutation_id,
                            "status": "error",
                            "error": str(exc),
                        }
                    )
            revision = current_revision(conn)
        return response(
            {
                "status": "ok",
                "baseRevision": base_revision,
                "currentRevision": revision,
                "results": results,
            }
        )

    @flask_app.post("/api/next/sync/reconcile")
    def sync_reconcile():
        """First-connect adoption: the client offers its full local list and gets
        back, per item, whether the server already has that record (``matched``
        with the server id + ``matchedBy``) or not (``unknown``). Read-only — no
        creates, no mutations. This is the only path where the title+year tier is
        active, keeping the fuzziest match confined to first connect."""
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Reconcile request body must be an object", 400)
        client_id = str(body.get("clientId") or "").strip()
        if not client_id:
            raise NextApiError("clientId is required", 400)
        items = body.get("items")
        if not isinstance(items, list):
            raise NextApiError("items must be a list", 400)
        if len(items) > 1000:
            raise NextApiError("At most 1000 items can be reconciled at once", 400)
        container_items = body.get("containerItems")
        if container_items is None:
            container_items = []
        if not isinstance(container_items, list):
            raise NextApiError("containerItems must be a list", 400)
        if len(container_items) > 1000:
            raise NextApiError("At most 1000 containerItems can be reconciled at once", 400)

        results: list[dict[str, Any]] = []
        container_results: list[dict[str, Any]] = []
        with connect() as conn:
            require_next_authenticated_user(conn)
            revision = current_revision(conn)
            for item in items:
                if not isinstance(item, dict):
                    results.append({"status": "invalid", "matched": False})
                    continue
                persistent_client_id = clean_text(item.get("client_id"))
                barcode = item.get("barcode")
                barcode_normalized = normalize_barcode(barcode)
                tmdb_id = clean_text(item.get("tmdb_id"))
                fmt = clean_text(item.get("format"))
                edition = clean_text(item.get("edition"))
                raw_container_ids = item.get("container_ids")
                if raw_container_ids is None:
                    container_ids: list[str] = []
                elif isinstance(raw_container_ids, list):
                    try:
                        container_ids = [str(UUID(str(value))) for value in raw_container_ids]
                    except (TypeError, ValueError, AttributeError):
                        results.append(
                            {
                                "client_id": persistent_client_id,
                                "status": "invalid",
                                "matched": False,
                            }
                        )
                        continue
                else:
                    results.append(
                        {
                            "client_id": persistent_client_id,
                            "status": "invalid",
                            "matched": False,
                        }
                    )
                    continue
                title = item.get("title")
                year = item.get("year")
                media_type = normalize_media_type(
                    item.get("media_type") or item.get("mediaType")
                )
                matched_id, matched_by = match_reconcile_item(
                    persistent_client_id=persistent_client_id,
                    barcode_normalized=barcode_normalized,
                    tmdb_id=tmdb_id,
                    fmt=fmt,
                    title=title,
                    year=year,
                    find_by_client_id=lambda: find_movie_by_client_id(
                        conn, persistent_client_id
                    ),
                    find_by_barcode=lambda: find_movie_by_barcode_match(
                        conn, barcode, incoming_media_type=media_type
                    ),
                    find_by_tmdb_edition=lambda: find_movie_by_tmdb_edition(
                        conn,
                        tmdb_id=tmdb_id,
                        fmt=fmt,
                        edition=edition,
                        incoming_title=title,
                        incoming_year=year,
                        incoming_barcode=barcode,
                        incoming_media_type=media_type,
                    ),
                    find_by_title_year=lambda: find_movie_by_title_year(
                        conn,
                        title=title,
                        year=year,
                        fmt=fmt,
                        incoming_barcode=barcode,
                        incoming_edition=edition,
                        incoming_container_ids=container_ids,
                        incoming_media_type=media_type,
                    ),
                )
                if matched_id is not None:
                    results.append(
                        {
                            "client_id": persistent_client_id,
                            "status": "matched",
                            "matched": True,
                            "entityId": str(matched_id),
                            "matchedBy": matched_by,
                        }
                    )
                else:
                    results.append(
                        {
                            "client_id": persistent_client_id,
                            "status": "unknown",
                            "matched": False,
                        }
                    )

            # Container branch (contract §5b): same read-only adoption shape
            # as the movie loop above, offered as a separate containerItems
            # array/containerResults response so a client can reconcile its
            # local box-sets/vaults/collections on first connect too, not
            # just its movies.
            for item in container_items:
                if not isinstance(item, dict):
                    container_results.append({"status": "invalid", "matched": False})
                    continue
                persistent_client_id = clean_text(item.get("client_id"))
                barcode = item.get("barcode")
                barcode_normalized = normalize_barcode(barcode)
                identifier_type = clean_text(item.get("identifier_type"))
                identifier = clean_text(item.get("identifier"))
                title = item.get("title")
                raw_container_type = item.get("container_type")
                if raw_container_type is None:
                    container_type = None
                else:
                    try:
                        container_type = normalize_container_type(raw_container_type)
                    except NextApiError:
                        container_results.append(
                            {
                                "client_id": persistent_client_id,
                                "status": "invalid",
                                "matched": False,
                            }
                        )
                        continue
                matched_id, matched_by = match_reconcile_container(
                    persistent_client_id=persistent_client_id,
                    barcode_normalized=barcode_normalized,
                    identifier_type=identifier_type,
                    identifier=identifier,
                    container_type=container_type,
                    title=title,
                    find_by_client_id=lambda: find_container_by_client_id(
                        conn, persistent_client_id
                    ),
                    find_by_barcode=lambda: find_container_by_barcode(
                        conn, barcode, container_type=container_type
                    ),
                    find_by_identifier=lambda: find_container_by_identifier(
                        conn,
                        identifier_type=identifier_type,
                        identifier=identifier,
                        container_type=container_type,
                        incoming_title=title,
                        incoming_barcode=barcode,
                    ),
                    find_by_title_type=lambda: find_container_by_title_type(
                        conn, title=title, container_type=container_type, incoming_barcode=barcode
                    ),
                )
                if matched_id is not None:
                    container_results.append(
                        {
                            "client_id": persistent_client_id,
                            "status": "matched",
                            "matched": True,
                            "entityId": str(matched_id),
                            "matchedBy": matched_by,
                        }
                    )
                else:
                    container_results.append(
                        {
                            "client_id": persistent_client_id,
                            "status": "unknown",
                            "matched": False,
                        }
                    )
        return response(
            {
                "status": "ok",
                "currentRevision": revision,
                "results": results,
                "containerResults": container_results,
            }
        )

    @flask_app.get("/api/next/sync/user/bootstrap")
    def sync_user_bootstrap():
        with connect() as conn:
            actor = require_next_permission(conn, "watchlist.manage")
            user_id = actor.get("id")
            revision = current_user_revision(conn, user_id)
            payload = {
                "watchlist": all_watchlist_sync_entities(conn, user_id),
                "watchHistory": all_watch_history_sync_entities(conn, user_id),
                "wishlist": all_wishlist_sync_entities(conn, user_id),
                "tags": all_tag_sync_entities(conn, user_id),
                "movieTags": all_movie_tag_sync_entities(conn, user_id),
                "loans": all_loan_sync_entities(conn, user_id),
            }
        return response(
            {
                "status": "ok",
                "currentRevision": revision,
                "serverTime": datetime.utcnow().isoformat(timespec="seconds") + "Z",
                "payload": payload,
            }
        )

    @flask_app.get("/api/next/sync/user/delta")
    def sync_user_delta():
        since = parse_int_arg("since", 0, minimum=0, maximum=9_000_000_000)
        limit = parse_int_arg("limit", 500, minimum=1, maximum=1000)
        with connect() as conn:
            actor = require_next_permission(conn, "watchlist.manage")
            user_id = actor.get("id")
            revision = current_user_revision(conn, user_id)
            if not table_exists(conn, "user_sync_changes"):
                return response(
                    {
                        "status": "ok",
                        "since": since,
                        "currentRevision": revision,
                        "changes": [],
                        "hasMore": False,
                        "nextSince": revision,
                    }
                )
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT
                        id,
                        revision,
                        entity_type,
                        entity_id,
                        operation,
                        payload,
                        created_at
                    FROM user_sync_changes
                    WHERE user_id=%s AND revision > %s
                    ORDER BY revision ASC
                    LIMIT %s
                    """,
                    (user_id, since, limit),
                )
                changes = cur.fetchall()
        next_since = int(changes[-1]["revision"]) if changes else since
        return response(
            {
                "status": "ok",
                "since": since,
                "currentRevision": revision,
                "changes": changes,
                "hasMore": bool(changes and next_since < revision),
                "nextSince": revision if not changes else next_since,
            }
        )


